    [W] = {sight = {"Farmhouses and old fields lay scattered around the militia's tower.", "The farms stood among mines, quarries and a coast where the Defias could hide."}, stakes = {"Some families were leaving; others still tried to keep their farms working.", "The militia's fight and the farmers' daily needs belonged to the same troubled countryside."}},
    [R] = {sight = {"Lakeshire stood beside the lake with hostile ground beyond its roads.", "Stonewatch's occupation cast a shadow over the country outside Lakeshire."}, stakes = {"Solomon needed help that the kingdom had been slow to provide.", "Keeping a town supplied mattered alongside holding its attackers back."}},
    [D] = {sight = {"Darkshire's watch stood between the town and the restless graveyards.", "The settlements and cemeteries of Duskwood lay under the same dark canopy."}, stakes = {"The Night Watch had too few defenders to meet every threat alone.", "The town still required food and ordinary labor while its dead refused to rest."}},
    ["Dun Morogh"] = {sight = {"Coldridge's camps and Kharanos's workshops were separated by snow and dangerous passages.", "The depot's siege engines and the quarry's broken equipment told different parts of Dun Morogh's working life."}, stakes = {"The dwarven settlements needed reports, provisions and working tools as much as weapons.", "Gnomeregan's surviving engineers sought a way forward while their fallen city remained beyond them."}},
    ["Loch Modan"] = {sight = {"Thelsamar's roads curved around the loch toward digs in the hills.", "Excavation camps depended on supplies sent out from town."}, stakes = {"Trogg attacks could bring the search for ancient history to a halt.", "The gate's defenders and the prospectors both needed help from outside their own ranks."}},
    ["Wetlands"] = {sight = {"Menethil's boats connected a marshbound settlement with distant ports.", "The road toward Dun Modr ran through country claimed by crocolisks and deep marsh."}, stakes = {"The port's trades depended on work in the dangerous country outside town.", "Beyond the road, Rethiel attended to wounds in the living marsh."}},
    [T] = {sight = {"Moonwells and little settlements lay beneath the new World Tree's canopy.", "The path from Shadowglen led toward Dolanaar, with troubled furbolg homes beyond the road."}, stakes = {"The kaldorei's new home had not restored the immortality lost at Mount Hyjal.", "The corruption of the forest threatened homes, sacred places and the creatures that shared them."}},
    ["Darkshore"] = {sight = {"Auberdine stood between the coastal strandings and the inland ruins.", "Old Highborne stones survived amid forest, salt air and restless spirits."}, stakes = {"The temple's researchers and the forest's keepers still sought explanations for the sickness around them.", "The work ranged from keeping strange machines supplied to investigating wounds far older than the town."}},
    ["Stormwind City"] = {sight = {"Candles gathered from Elwynn's kobolds supplied Pestle's Apothecary in the Trade District.", "Reports from outlying towns reached a capital with demands on every side."}, stakes = {"The kingdom's distant settlements needed more than promises of help.", "Small deliveries connected the capital's daily life with its troubled countryside."}},
    ["Ironforge"] = {sight = {"The Assembly of Explorers received reports from digs far outside the city's halls.", "The Great Forge shared the mountain city with workshops and the Explorers' League."}, stakes = {"Questions about missing powder could follow an expedition all the way back to its sponsors.", "The city's reach depended on supplied expeditions and defended roads."}},
    ["Darnassus"] = {sight = {"The druid grove and the Temple of the Moon held different responsibilities within the city.", "Water carried from Teldrassil's moonwells reached the capital's sacred places."}, stakes = {"The new World Tree's flaws remained a concern for the city's leaders.", "Fandral's work as Arch Druid sat alongside Tyrande's responsibility for the kaldorei people."}},
}
P.zones["Stormwind City"].source = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #60 Kobold Candles; #61 Shipment to Stormwind; #783 A Threat Within"}
-- Exact Solarsal stages: discovery, report, and scales stay distinct.
-- Against the Hatecrest also names referral3130; do not promote2869 to title fallback.
P.threads.alliance_solarsal = "the Hatecrest presence at Solarsal"
q(2866, "The Ruins of Solarsal", "Feralas", 43, "alliance_solarsal",
    "Shandris Feathermoon wanted the ancient Solarsal ruins searched after Hatecrest naga occupied them in alarming numbers.",
    "The Hatecrest gathering at Solarsal troubled Shandris, who suspected more than preparations for an attack.",
    "A gazebo stood newer than the surrounding ruins, its stone warm beneath a pattern of unfamiliar glyphs.",
    "The gazebo's repeating glyphs gave no clear meaning, but its warm stone and recent construction set it apart.", 3)
q(2867, "Return to Feathermoon Stronghold", "Feralas", 43, "alliance_solarsal",
    "The unusual gazebo in Solarsal called for a report to General Shandris Feathermoon.",
    "Shandris needed news of the strange gazebo found among the naga-held ruins of Solarsal.",
    "The report disturbed Shandris, who saw the Hatecrest presence as a danger to the advance into Feralas.",
    "Shandris received the findings and sought more help against the naga, whose purpose remained uncertain.", 3)
q(2869, "Against the Hatecrest", "Feralas", 43, "alliance_solarsal",
    "Latronicus Moonspear wanted the Hatecrest weakened before they could claim Sardor Isle.",
    "Latronicus feared the naga would try to take Sardor Isle and wanted their scales as proof of a counterattack.",
    "Latronicus accepted the Hatecrest scales and considered sending them to Pratt to see what could be made from them.",
    "The recovered scales satisfied Latronicus, who valued the help given to Shandris and the stronghold.", 3)

-- Complete short scenes: exact recorded stages only; see editorial-20261016 author packet.
P.questIDs[18].highlight = {"The guards exchanged the Defias thieves' bandanas for a weapon, honoring their bargain for the fighting east of Northshire's river.", "Defias bandanas from across the river earned a weapon and the Stormwind Army's thanks at Northshire."}
P.questIDs[6].highlight = {"Garrick Padfoot's head settled the guards' bounty on the cutthroat who had preyed on Northshire's farms and merchants.", "The guards paid for Garrick Padfoot's head. The raider who had troubled Northshire's farmers and merchants was dead."}
P.questIDs[47].highlight = {"Remy Two Times paid for the kobolds' gold dust and added a token from his associates, hinting it might prove useful.", "The kobolds' gold dust earned Remy's payment, along with a small token from associates he left unnamed."}
P.questIDs[62].highlight = {"Scouting confirmed kobolds in Fargodeep Mine. Marshal Dughan took the bad news and called for stronger patrols.", "Fargodeep was full of kobolds. The report prompted Dughan to call for more patrols near the mine."}
P.questIDs[921].highlight = {"With moonwell water returned, Tenaron spoke of Hyjal's cost to Nordrassil and of Elune's wells, whose ancient waters came from the Well of Eternity.", "The moonwell errand carried Tenaron's lesson. Nordrassil's power had been spent at Hyjal, while Elune's shrines held the ancient magic of the Well of Eternity."}
P.questIDs[932].highlight = {"Tallonkai wanted the matter kept quiet, since the satyr Melenas and his grell were embarrassingly close to home. Melenas's death ended that concern.", "Tallonkai received proof of Melenas's death. The satyr gathering grell in nearby Fel Rock had been dealt with."}
P.questIDs[483].highlight = {"Four Relics of Wakening were recovered from Gnarlpine-held Ban'ethil, ready for the ritual meant to wake its trapped druids.", "The recovered Relics of Wakening made preparations possible for the sleeping druids in Ban'ethil, endangered by Gnarlpine invaders."}
P.questIDs[2438].highlight = {"The emerald dreamcatcher was recovered from Starbreeze. Tallonkai prized it as a rare gift from Ban'ethil's warden.", "The emerald dreamcatcher, a rare gift from Ban'ethil's warden, came back from corrupted Starbreeze to the owner who had hoped it was unharmed."}
P.questIDs[2866].highlight = {"Among naga-held Solarsal's ruins, the search found a newer gazebo with unfamiliar glyphs and warm stone.", "The Solarsal investigation found a gazebo newer than the ruins around it, with warm stone and repeating, unreadable glyphs."}
P.questIDs[2867].highlight = {"The gazebo report disturbed Shandris. Whatever the Hatecrest's purpose, she wanted further help against their presence in Feralas.", "Shandris found the news from Solarsal disturbing and asked for more help against the naga around the strange gazebo."}
P.questIDs[2869].highlight = {"Hatecrest scales proved the counterattack Latronicus wanted on Sardor Isle. He considered sending them to Pratt for crafting.", "Latronicus accepted scales from the Hatecrest as proof of the fighting on Sardor Isle, then wondered what Pratt could make of them."}
P.questIDs[255].highlight = {"With Ironforge's soldiers months away, Bluntnose welcomed help against Thelsamar's ogres. He hoped the town could soon turn its attention to the troggs.", "Thelsamar's ogres suffered losses while Ironforge's reinforcements were still months away. Bluntnose offered thanks, already thinking of the troggs."}
P.questIDs[267].highlight = {"With Ironforge's Reserve away, Rugelfuss needed help against Loch Modan's troggs. The returned teeth earned his thanks and the praise he imagined from King Magni.", "Trogg teeth reached Captain Rugelfuss, whose regiment could not leave the gate. He declared that such defense of dwarven lands would make King Magni proud."}
P.questIDs[263].highlight = {"The fight against Stonesplinter shamans and bonesnappers earned Wallbang's salute and a recommendation to speak with the captain.", "Wallbang praised the fighting against the Stonesplinter shamans and bonesnappers. He thought the captain might now offer a greater responsibility."}
P.questIDs[273].highlight = {"Huldar's powder shipment was found after a Dark Iron ambush. The betrayal of Saean, a colleague of nearly a year, had stunned him.", "The search reached Huldar and the powder shipment. He had weathered the Dark Iron ambush, but never expected Saean to side with the attackers."}
P.questIDs[298].highlight = {"Ironband's report brought another powder request to Jern, who wondered what had become of the shipment he had sent weeks earlier.", "Jern received Ironband's report and request for blastpowder. A generous shipment had already left Thelsamar weeks before, and he wanted to know where it had gone."}
P.questIDs[294].highlight = {"Raptors drawn to Whelgar's excavation had killed Ormer's fellow workers. The first hunt brought vengeance while duty kept him beside Merrin and the Prospector.", "The raptors west of the bluff suffered Ormer's first reprisal for his fallen coworkers. He said he would have joined the fighting if duty to Merrin and the Prospector allowed it."}
P.questIDs[295].highlight = {"The next hunt thinned the scytheclaws and razormaws below the bluff, earning Ormer's hearty praise.", "Ormer welcomed the losses among the scytheclaws and razormaws that crowded the excavation below his shelter."}
P.questIDs[296].highlight = {"Sarltooth's talon proved Ormer's final target dead. He hoped the vengeance for the fallen workers would deter attacks on King Magni's people.", "Ormer received Sarltooth's talon and remembered the dwarves killed at their work. He believed the vengeance would make the creatures fear another attack."}

-- Band 20-30 pass (2026-11-06, tests/Band2030.lua): Astranaar's arrivals and
-- defense, Relara's neighbours, Gaxim's war on the Venture Company, Kayneth
-- Stillwind's watch, the Howling Vale through Velinde's fate, the dryads of the
-- Shrine of Aessina and Gerrig's manuscript. Quest text by ID; NPCs and places
-- checked against Interface/AddOns/LoreForever/Data (facts only).
P.threads.alliance_astranaar = "the defense of Astranaar"
P.threads.alliance_gaxim = "Gaxim's campaign against the Venture Company"
P.threads.alliance_kayneth = "Kayneth Stillwind's watch over Ashenvale"
P.threads.alliance_aessina = "the dryads of the Shrine of Aessina"
P.threads.alliance_gerrig = "Gerrig Bonegrip's collection"
local AA, AG, AK, AD = "alliance_astranaar", "alliance_gaxim", "alliance_kayneth", "alliance_aessina"
q(990, "Trek to Ashenvale", "Ashenvale", 19, AA,
    "Sentinel Selarin's mistress, Raene Wolfrunner, was waiting in {p:Astranaar}. Corruption had taken hold in Ashenvale, and Selarin hoped that help from Darkshore might ease some of it.",
    "The road south from Auberdine led into Ashenvale and on to Astranaar. Raene Wolfrunner wanted every pair of hands Selarin could send her.",
    "Raene Wolfrunner welcomed the arrival from Darkshore and said Selarin had done well to send help so quickly. She wished the visit had come under less dire stress, and pointed to the citizens of Astranaar who needed aid.",
    "In Astranaar, Raene said the trip had been made under dire stress and that Selarin had chosen well. The other citizens of the town could use help, she said, and that was the place to start.")
q(1133, "Journey to Astranaar", "Ashenvale", 20, AA,
    "Fiora Longears in Theramore had advice for anyone fresh off the boat from Menethil. The first thing to do was go to {p:Astranaar} and offer services to Shindrell Swiftfire. It was better not to mention Fiora, since Shindrell did not know her.",
    "Astranaar was where an eager member of the Alliance could do real good, Fiora Longears said. She asked that nobody mention who had sent them.",
    "Shindrell Swiftfire welcomed the offer of service. Ashenvale kept its beauty, she said, but it was no longer the peaceful place it had been.",
    "In Astranaar, Shindrell accepted the help and spoke of a forest that was lovely still and peaceful no more.")
q(1134, "Pridewings of Stonetalon", "Stonetalon Mountains", 21, AA,
    "The Alliance and the Horde were not at open war, Shindrell said, but the peace was fragile. Hidden sources in Theramore claimed that orc assassins used venom from the pridewings near Mirkfallon Lake on their death raids. Shindrell meant to deny them their source.",
    "The claim from Theramore was that orcs milked the pridewings of Stonetalon for an assassin's poison. If it was true, Shindrell said, the orcs had to be stopped.",
    "Shindrell took the venom sacs with no joy. It saddened her to order the slaughter of creatures that might not willingly serve her enemies. It was her duty, she said, and her allies were safer for it.",
    "The pridewing venom reached Astranaar. Shindrell admitted the beasts might not have served the orcs willingly. A heart could weep for them, she said, and still be glad the Alliance was safe from their venom.")
q(945, "Therylune's Escape", "Darkshore", 18, AD,
    "Therylune had wandered into the {p:Master's Glaive} in Darkshore and been surrounded by cultists. She had hidden well, and now wanted a way out and word carried to her sister Therysil at the Shrine of Aessina in Ashenvale.",
    "Cultists ringed the Master's Glaive, and Therylune was hiding among them. Her sister waited far to the south at the Shrine of Aessina, knowing nothing of it.",
    "Therysil could hardly believe where her sister had got to. Therylune never minded getting dirty, she said, but the Master's Glaive was an unwholesome place and a long way to wander.",
    "At the Shrine of Aessina, Therysil learned that her sister was all right, and where she had been hiding. She thanked the bearer of the news.")
q(976, "Supplies to Auberdine", "Ashenvale", 24, "alliance_darkshore",
    "Delgren had given Feero Ironhand messages and supplies for Sentinel Starbreeze in Auberdine, and Feero would not take the road north alone. Dangerous foes worked in the forest, and he feared the goods and the information falling into the wrong hands.",
    "Feero Ironhand was ready to leave {p:Maestra's Post} the moment he had guards. The supplies he carried were meant to reinforce the Sentinels in Darkshore.",
    "Feero got through the forest with his escort. Delgren said the goods would be put to use at once against the dark threats there.",
    "The supplies for Auberdine were on their way with Feero. Delgren called it a good day's work and said the Sentinels would use the goods immediately.")
q(1016, "Elemental Bracers", "Ashenvale", 24, AA,
    "Sentinel Velene Starstrike at Silverwind Refuge wanted to know who had made the elementals fouling the pools. Her divining scroll needed something of theirs to focus on, and a few intact bracers would do.",
    "The corrupted elementals wore bracers, and most broke when the creatures died. Velene needed a few whole ones for a divining scroll that could name their maker.",
    "The divined paper should give Velene what she needed to find the culprit. A wizard was filling the pools with corrupt elementals on purpose, she said, and it sickened her. She wanted him to pay.",
    "Velene read the result of the divining scroll and spoke of a mage who was corrupting Ashenvale's waters deliberately. The next step, she said, was to take him out.")
q(1017, "Mage Summoner", "The Barrens", 25, AA,
    "Only one undead mage in the Barrens could defile so many water elementals, Velene said, and only one was foolish enough to try. Sarilus Foulborne was probably sitting atop Dreadmist Peak laughing at her, and she wanted his head.",
    "Velene had had enough of Sarilus Foulborne. The undead mage on Dreadmist Peak had been fouling the Sentinels' pools from inside Horde territory, where the Horde might be watching.",
    "Sarilus Foulborne's head came back across the border to Silverwind Refuge. Velene said she could see his repugnant smile wiped away forever, and gave the Light of Elune, a draught to drink when death was near.",
    "Velene received the head of the mage who had annoyed the Sentinels once too often. In thanks she gave the Light of Elune, to be drunk when all seemed lost.", 4)
q(1025, "An Aggressive Defense", "Ashenvale", 24, AA,
    "Before the trip to the moonwell, Raene Wolfrunner had another task. Furbolgs had been attacking travelers on the road east of Astranaar, short of the Falfarren River, and their camps lay south of the road.",
    "Raene described the furbolgs east of Astranaar as minds tortured and fed on fear. She asked that they be shown the same mercy they had shown her people.",
    "Raene said the work on the eastern road had been done well, and thanked the one who did it.",
    "The furbolg camps south of the Falfarren road were thinned. Raene's thanks were brief.")
q(1054, "Culling the Threat", "Ashenvale", 25, AA,
    "Directly north of Astranaar the Thistlefur furbolg had grown in number for months. Raene feared they would soon find the courage to attack the town. She wanted their chieftain's skull as proof that their efforts had been stifled.",
    "Raene's scouts counted more Thistlefur every month. Their chieftain, Dal Bloodclaw, had to die before the tribe grew bold enough to march on Astranaar.",
    "Dal Bloodclaw's skull reached Raene in Astranaar. The furbolg threat was constant, she said, and this would keep them at bay a while longer.",
    "Raene took the chieftain's skull and hoped for a little breathing room. Astranaar lived under constant threat from the furbolg.", 4)
q(1011, "Forsaken Diseases", "Ashenvale", 29, AK,
    "Kayneth Stillwind believed the Forsaken who lurked in Ashenvale's ruins and barrows had come to spread disease among the night elves. A bottle from their camp south of Forest Song, near the Dor'Danil Barrow Den, would prove it.",
    "The Forsaken had a camp near the Dor'Danil Barrow Den where they brewed poisons and bottled them. Kayneth wanted one bottle to test.",
    "Kayneth took the bottle of disease from the Forsaken camp. By testing its contents, he said, the Forsaken's goals in Ashenvale would be revealed.",
    "The stolen bottle reached Kayneth at Forest Song. He meant to find out what the Forsaken were brewing, and why.")
q(4581, "Kayneth Stillwind", "Ashenvale", 29, AK,
    "The druid Kayneth Stillwind had asked Shindrell for an account of the coast and the forests around Astranaar. He feared a corruption moving through Ashenvale, and Shindrell thought he might be right.",
    "Shindrell's report went east to the shrine of Forest Song in the Nightsong Woods, where Kayneth Stillwind watched the forest.",
    "Kayneth read Shindrell's report for clues of the wickedness he feared was moving through Ashenvale. He called her a fine sentinel, brave and keen.",
    "Shindrell's report reached Forest Song. Kayneth praised the sentinel who wrote it and turned to it for signs of corruption.")
q(1012, "Insane Druids", "Ashenvale", 32, AK,
    "Struggling with the Forsaken's poisons, Kayneth had seen a vision of the druids of the Dor'Danil Barrow Den. The undead had poisoned and murdered them and left them as maddened ghosts. For their spirits to find peace, their leaders Taneel Darkwood, Uthil Mooncall and Mavoris Cloudsbreak had to be destroyed.",
    "Kayneth's dreams were haunted by the anguish of the Dor'danil druids. The spirits of their three leaders, severed from their bodies and driven mad, had to be put down inside the barrow den.",
    "Kayneth felt the anguish of the Dor'danil barrows lessen and knew the work was done. It was grim work, he said, for the spirits destroyed had been victims of the Forsaken. He hoped the rest might now find peace.",
    "The three druid leaders were destroyed in the barrow den. Kayneth called it grim, and hoped the other maddened spirits would find rest.", 4)
q(1022, "The Howling Vale", "Ashenvale", 30, VL,
    "Sentinel Melyria Frostshadow had kept most of Felwood's demons out of Ashenvale, but something new had come. Wolf-men had overrun the ruined shrine of Mel'Thandris near the Felwood border. Their calls had earned the place the name of the Howling Vale.",
    "The Tome of Mel'Thandris, kept at the shrine in the Howling Vale, was no ordinary tome. Its leaves had been blessed by Mel'Thandris herself and showed events of import, and Melyria hoped it would explain the wolf-men.",
    "What the Tome of Mel'Thandris showed, no one truly understood, Melyria said. But it was clear that the Scythe of Elune, given to Priestess Starsong, needed looking into.",
    "The tome's vision pointed to a priestess named Starsong and a weapon called the Scythe of Elune. Melyria could not say why the tome showed what it did, only that the scythe bore investigation.", 4)
q(1037, "Velinde Starsong", "Darnassus", 30, VL,
    "Velinde Starsong had been Melyria's predecessor in Ashenvale. Her work against Felwood had faltered little by little, and one day she had simply disappeared. Thyn'tel Bladeweaver, a commander of the Sentinels, might know more.",
    "Melyria knew nothing of the priestess whose post she had inherited. She thought Thyn'tel Bladeweaver in {p:Darnassus} might know details of the disappearance that Melyria had never been told.",
    "Thyn'tel Bladeweaver allowed that Velinde's disappearance was common knowledge. Anything further, she said, would take good reason to divulge.",
    "In Darnassus, Thyn'tel confirmed that the priestess had vanished some time ago and said no more. The details would need a reason.")
q(1040, "Passage to Booty Bay", "Stranglethorn Vale", 30, VL,
    "Wharfmaster Dizzywig found the entry at last. Velinde had booked passage to {p:Booty Bay} on the Black Osprey and asked about overland travel on the far side of the world. He had mentioned Ruzzgot, a caravan driver based in that port.",
    "Dizzywig's ledgers put Velinde on the Black Osprey to Booty Bay, with nothing to say the ship had failed to arrive. The next name was Ruzzgot, a goblin caravaneer there.",
    "Caravaneer Ruzzgot sized up his visitor as someone without goods to ship. Either it was a job seeker, and there were no jobs, or the wrong goblin was being asked.",
    "In Booty Bay, Ruzzgot saw no cargo to ship. He offered two choices, a job he did not have or the wrong goblin, and asked which it was.")
q(1041, "The Caravan Road", "Duskwood", 30, VL,
    "Ruzzgot admitted he had been wrong about his visitor, and that did not happen every day. He remembered Velinde, a night elf priestess who had traveled with his caravan. They had parted on the way north, he said, when she turned for {p:Darkshire}.",
    "A night elf priestess on a dirty old caravan was not a passenger Ruzzgot forgot. She had left him on the road north, bound for Darkshire, where the clerk kept notes on everything.",
    "Clerk Daltry kept note of every stranger who passed through Darkshire, he said, with all the strange happenings of recent years. It was seldom pleasant business when those notes were needed, though he suggested nothing about Velinde by it.",
    "In Darkshire, Clerk Daltry said he wrote down what he could about strangers these days. He had not meant to imply anything about the priestess.")
q(1042, "The Carevin Family", "Duskwood", 30, VL,
    "Daltry had nothing on a Velinde Starsong taking a room in Darkshire, and could hardly picture a night elf priestess at the inn. The wolf-men were another matter. Calor had come into town with a string of their heads. He worked for the Carevin family, hunters of demons, undead and other monstrosities.",
    "The clerk's notes held no Velinde, but the mention of wolf-men caught him. The Carevins hunted such things, and Jonathan Carevin headed the household.",
    "Jonathan Carevin did not apologize for his suspicion. A stranger had walked into his home in dark times asking about worgen, and he meant to have answers.",
    "In the Carevin house, Jonathan heard the question about worgen with open suspicion. Evil lay under every rock these days, he said, and he would have answers before he gave any.")
q(1043, "The Scythe of Elune", "Duskwood", 30, VL,
    "Jonathan Carevin did not understand the motives behind the search, but if it meant fewer worgen in Duskwood he could forgo understanding for results. The beasts had first appeared at a mine to the south, Roland's Doom, and it was overrun with them still.",
    "The worgen had come out of nowhere, as far as Darkshire knew, and the mine south of town was where they were first seen. Jonathan asked that anything of import found there be shared with him.",
    "Jonathan found the account from the mine interesting. The Carevin family could not reach the root of the trouble, he said. It would do what it could to contain the worgen in Duskwood. Calor would make that his first priority.",
    "What came out of Roland's Doom was an interesting account, Jonathan said. His family could not finish the matter, only hold the worgen's numbers down, and he set Calor to it.", 4)
q(1044, "Answered Questions", "Darnassus", 30, VL,
    "Jonathan Carevin promised the worgen would be reined in. He bore Velinde no ill will for the evil she had brought into his woods. Others ought to hear, he said, what the mines of Duskwood had revealed.",
    "What had been found in Roland's Doom belonged in {p:Darnassus}. Jonathan kept the stranger no longer.",
    "So that was Velinde's fate, Thyn'tel said. The high priestess would be disappointed, for the two had been friends. It unsettled Thyn'tel that the Scythe of Elune, surely a boon from the goddess, had fallen out of her servants' hands.",
    "Thyn'tel Bladeweaver heard how the search for Velinde had ended. She owed thanks for it, she said, and worried where the Scythe of Elune had gone. That was a matter for another time.", 5)
q(1021, "Vile Satyr! Dryads in Danger!", "Ashenvale", 32, AD,
    "Illiyana's sisters had gone to take back the Branch of Cenarius from the satyrs and had been gone two whole days. They had been looking for the ruins of a night elf temple in Xavian, to the northeast, with Anilia leading them.",
    "At the Shrine of Aessina, Illiyana did not know what to think. Anilia had led the search for the stolen Branch of Cenarius into Xavian and had not come back.",
    "Anilia was found in Xavian with a gaping wound in her side, on the verge of death.",
    "The search found Anilia among the ruins of Xavian, dying of a wound in her side.")
q(1031, "The Branch of Cenarius", "Ashenvale", 32, AD,
    "Anilia drew her rescuer close, pointed to the arch to the north and breathed a name, Geltharis, before she died. Her last wish was plain enough. The Branch of Cenarius had to go back to dryad hands.",
    "With her last breath Anilia named Geltharis as the thief of the Branch of Cenarius and pointed north. There was nothing to do for her but finish what she had started.",
    "Illiyana could not believe Anilia was gone. Only yesterday they had been running and playing in the woods, she said, and those days were over now.",
    "The Branch of Cenarius came back to Illiyana along with the news of Anilia's death. She spoke of the days they had played together in the forest, and said those days were done.", 5)
q(1032, "Satyr Slaying!", "Ashenvale", 32, AD,
    "Illiyana said she almost felt sad, and knew one thing that might help. The satyrs that had taken Anilia from her could die, and their horns would prove it.",
    "Illiyana wanted Anilia avenged on the satyrs of Xavian, with their horns as proof.",
    "Illiyana took the satyr horns and said her sister's spirit was gladdened.",
    "The horns of Anilia's killers reached the Shrine of Aessina. Illiyana believed her sister's spirit was gladdened by it.")
q(971, "Knowledge in the Deeps", "Blackfathom Deeps", 23, "alliance_gerrig",
    "Gerrig Bonegrip in Ironforge collected old lore, the kind that opened doorways and could wake Those Who Sleep. He had heard of the Lorgalis Manuscript at the bottom of {p:Blackfathom Deeps}, the old dwelling of long-dead elves, and wanted it.",
    "The Lorgalis Manuscript was said to lie deep in Blackfathom Deeps in Ashenvale. Elves of great knowledge had lived there before their city fell. Gerrig Bonegrip promised not to forget whoever brought it to him, not even after the end days.",
    "Gerrig called it a joyous day. Copies of the Lorgalis Manuscript would be made and spread among his brothers and sisters, and he said the service was greater than its bearer knew.",
    "The manuscript from Blackfathom reached Gerrig Bonegrip in Ironforge. He spoke of brothers and sisters who would read it, and offered a gift as the gratitude his kind extended to their allies.", 4)
-- Gaxim's campaign: the NG-5, the scroll, the two covert operations and the reports home.
q(1072, "An Old Colleague", IF, 21, AG,
    "Gaxim's most advanced device needed a special charge, Nitromirglyceronium, and only one person could make it. His old friend Lomac Gearstrip was in {p:Tinker Town}, in Ironforge.",
    "Gaxim admitted the mission might be a last one, so he wanted the good stuff. NG-5 came from Lomac Gearstrip in Tinker Town, and someone had to talk him into making it.",
    "Lomac Gearstrip wanted to know why he should believe that Gaxim had sent anyone. He asked twice.",
    "In Tinker Town, Lomac greeted Gaxim's name with suspicion and demanded proof that the request was not a lie.")
q(1073, "Ineptitude + Chemicals = Fun", IF, 21, AG,
    "Lomac laughed at the idea of using Nitromirglyceronium to save a forest, and would gladly supply it just to see someone explode. He was out of it, though, and wanted the right potions brought before he brewed more.",
    "NG-5 was Lomac's greatest creation, and he would not hand a sample to just anyone. The potions he needed for it would show whether the asker knew any alchemy.",
    "The potions satisfied Lomac. The stranger seemed to know something about alchemy, he said, and the world was not all swords and sorcery.",
    "Lomac said the potions would do nicely. He had what he needed to make the NG-5.")
q(1074, "Ineptitude + Chemicals = Fun", "Stonetalon Mountains", 21, AG,
    "Lomac handed over the NG-5 with a warning that it was volatile, and a greeting for Gaxim if the courier really was his friend.",
    "The Nitromirglyceronium was ready for the crossing back to Stonetalon. Lomac's parting words were to enjoy blowing oneself up if the friendship with Gaxim was a lie.",
    "Gaxim took the NG-5 and explained its purpose. It would ignite wagons of dynamite, he said, and make the perfect distraction.",
    "The volatile charge reached Gaxim in {p:Stonetalon Mountains}. He called it the one ingredient that could set off whole wagons of dynamite, and promised the distraction would be worth seeing.")
q(1075, "A Scroll from Mauren", SW, 21, AG,
    "Gaxim's next piece was remote detonation. With a little magic the NG-5 could go off at the push of a button. The spell had to come from Collin Mauren in Stormwind's {p:Mage Quarter}.",
    "A device that set off explosives from a distance needed a mage's help. Gaxim named Collin Mauren, a human in the Mage Quarter of Stormwind.",
    "Collin Mauren turned the request over. A spell to detonate explosives from a distance would take some thought.",
    "In the Mage Quarter, Mauren heard what Gaxim needed and began considering how such a spell might work.")
q(1077, "Special Delivery for Gaxim", "Stonetalon Mountains", 21, AG,
    "Collin Mauren had his spell ready and sent his regards to Gaxim with it. He wanted to hear how the adventure ended.",
    "The scroll from Stormwind was the last part of Gaxim's remote explosive. Mauren asked only to be told how it went.",
    "Gaxim called Mauren's spell perfect. Mixed with the NG-5 it made a remote explosive. The distraction it caused would cover a theft of the Venture Company's letters and engineering plans.",
    "With the spell in hand, Gaxim had his remote explosive. The plan was now a distraction and a burglary, aimed at the Venture Company's plans and letters to slow its deforestation.")
q(1079, "Covert Ops - Alpha", "Stonetalon Mountains", 22, AG,
    "Gaxim's devices were done. Plan Alpha was not about the size of the blast, he said. It was about coming back with the Venture Company's engineering plans from the lumber mill south of Cragpool Lake.",
    "Gaxim's notes explained where to place the detonators and the NG-5. The target was the lumber mill below Cragpool Lake and the plans kept inside it.",
    "The engineering plans came out of the lumber mill. Gaxim called it a huge blow to the Venture Company, whose machines could now be studied for weaknesses and copied.",
    "Gaxim had the Venture Company's plans in hand and called it a wonderful day. Their designs would show him their weaknesses and feed his own inventions.", 4)
q(1080, "Covert Ops - Beta", "Stonetalon Mountains", 22, AG,
    "Plan Beta ran like Plan Alpha, a distraction and a theft, except that the prize this time was the Venture Company's letters. Gaxim wanted them, and the thief back alive.",
    "Gaxim's notes said where the explosives should go. Beyond the distraction, only the letters mattered.",
    "The letters reached Gaxim, who said Kaela and the Sentinels would be delighted. With his creations and a willing agent, he felt unstoppable.",
    "Gaxim was thrilled by the stolen letters and declared the partnership unstoppable. Kaela and the Sentinels would hear of it next.", 4)
q(1091, "Kaela's Update", "Stonetalon Mountains", 22, AG,
    "Gaxim sent the stolen letters on to Kaela. The instructions were to say how well it had gone, and that it could not have been done without a little magic.",
    "The letters stolen from the Venture Company were bound for Kaela, with the credit for Gaxim's magic to be mentioned.",
    "Kaela found the letters interesting indeed, and said the work with Gaxim had been done very well.",
    "The letters reached Kaela Shadowspear. She called their contents interesting and praised the work done beside Gaxim.")
q(1082, "Update for Sentinel Thenysil", "Ashenvale", 22, AG,
    "Kaela sent word back to {p:Astranaar} that she and Gaxim were alive and well on their way to stopping the Venture Company. Tara Thenysil would want to hear it.",
    "There was good news at last for Tara in Astranaar. Her friend Kaela was alive, the gnome too, and the work in Stonetalon was going forward.",
    "Tara thanked the messenger for the service to the Sentinels. She was glad to hear Kaela was well, and even Gaxim.",
    "The news reached Tara Thenysil in Astranaar. Kaela was safe, and Tara allowed that she was glad about Gaxim too.")
q(1081, "Reception from Tyrande", "Darnassus", 28, AG,
    "Tara Thenysil believed Tyrande Whisperwind herself would want to give thanks. What had begun in Stonetalon might strengthen the night elves' foothold there, and the {p:Temple of the Moon} in Darnassus waited.",
    "The work in Stonetalon had earned an audience with the High Priestess. Tara sent the Sentinels' ally to the Temple of the Moon.",
    "Tyrande had heard the name before. She was pleased with the path chosen by one still full of youth, she said, and gave a gift in appreciation.",
    "In the Temple of the Moon, Tyrande Whisperwind said the name was already known to her, and offered a gift for the work in Stonetalon.", 5)
q(1083, "Enraged Spirits", "Stonetalon Mountains", 26, AG,
    "Kaela did not know what the Venture Company had done in the {p:Charred Vale}, only that the creatures there had overpowered them. In setting the forest aflame the goblins had freed burning spirits of flame, stone and rage. The land had no chance while they roamed.",
    "The first time Kaela saw the Charred Vale she had almost wept. She asked for the smoldering embers of its fire spirits as proof that their numbers were falling.",
    "The embers of the vale's fire spirits reached Kaela. She called them the remains of the enemy, and said the strength that won them served her people well.",
    "Kaela took the smoldering embers. Fewer enraged spirits walked the Charred Vale, and she thanked the strength that had thinned them.")
q(1084, "Wounded Ancients", "Stonetalon Mountains", 28, AG,
    "The treants had surely helped drive the Venture Company out of the Charred Vale, Kaela thought, and now even those guardians had turned. Gaxim suspected the goblins' weapons, and wanted shrapnel from a wounded treant to study.",
    "Something had corrupted the protectors of the vale. Gaxim's theory pointed at the weapons the goblins used in their retreat, and the proof would be the shrapnel still lodged in the treants.",
    "Kaela took the shrapnel for Gaxim. It would be more than enough, she said, for the gnome to work out how the treants were corrupted.",
    "The shrapnel from the wounded treants went to Kaela, who meant to give it to Gaxim right away.")
q(1078, "Retrieval for Mauren", SW, 26, AG,
    "Travelers kept asking Collin Mauren about the Stonetalon Mountains. He had a request of his own. Basilisks had once lived in the Charred Vale whose scales, ground to dust, made a fine reagent for his spells.",
    "Collin Mauren wanted a few basilisk scales from the Charred Vale, if the creatures still lived there. There was no rush, he said, and he paid well.",
    "Mauren called the scales perfect and thanked their bearer greatly. One day, he hoped, he might return the help.",
    "The basilisk scales reached Collin Mauren in the Mage Quarter. He paid, and promised to remember the favor.")
P.questIDs[1035].highlight = {"The Shadethicket Oracle's moonstone reached Pelturas in time, he said, with Relara down to her last breaths. He gave the thing he held dearest after his daughter.", "Pelturas took the fallen moonstone and called his daughter saved. In thanks he gave what he treasured most after Relara."}
P.questIDs[1009].highlight = {"Ruuzel died on the isle at Zoram's northern edge. The Ring of Zoram, the key to the statuette's lock, went to Talen, who paid for it and swore never to forget.", "Talen paid for the Ring of Zoram taken from Ruuzel. He had the key to his statuette at last."}
P.questIDs[1017].highlight = {"Sarilus Foulborne's head came down from Dreadmist Peak to Velene Starstrike, who gave the Light of Elune in return.", "Velene received the head of the mage who had fouled her pools, and gave the Light of Elune, a draught for when death was near."}
P.questIDs[1054].highlight = {"Dal Bloodclaw's skull reached Raene in Astranaar. She hoped it would keep the Thistlefur at bay a while longer.", "Raene took the Thistlefur chieftain's skull and hoped for a little breathing room for Astranaar."}
P.questIDs[1012].highlight = {"The maddened spirits of Taneel Darkwood, Uthil Mooncall and Mavoris Cloudsbreak were destroyed in the barrow den. Kayneth called it grim work done to victims, and hoped the rest found peace.", "Kayneth felt the anguish of the Dor'danil barrows lessen. The three druid leaders were gone, and he hoped the other spirits could rest."}
P.questIDs[1044].highlight = {"The search for Velinde Starsong ended before Thyn'tel in Darnassus. The high priestess would be disappointed, she said, and the Scythe of Elune was out of the goddess's servants' hands.", "Thyn'tel heard Velinde's fate and gave her thanks. The Scythe of Elune troubled her, a matter for another time."}
P.questIDs[1031].highlight = {"The Branch of Cenarius came back to Illiyana with the news that Anilia was dead. Only yesterday they had played in the woods, she said.", "Illiyana had the Branch of Cenarius back, and her sister Anilia was dead. Those days of playing in the forest were over, she said."}
P.questIDs[1079].highlight = {"The Venture Company's engineering plans came out of the lumber mill south of Cragpool Lake. Gaxim called it a huge blow to the company.", "Gaxim had the Venture Company's plans from the lumber mill and called it a wonderful day."}
P.questIDs[1080].highlight = {"The Venture Company's letters, the prize of Plan Beta, reached Gaxim. Kaela and the Sentinels would be delighted, he said.", "With the stolen letters in hand, Gaxim said that together they were unstoppable."}
P.questIDs[1081].highlight = {"Tyrande Whisperwind received the Sentinels' ally in the Temple of the Moon. The name was known to her, she said, and she gave a gift for the work in Stonetalon.", "In the Temple of the Moon, Tyrande gave a gift of appreciation for what had begun in Stonetalon."}
P.questIDs[971].highlight = {"The Lorgalis Manuscript came up from Blackfathom Deeps to Gerrig Bonegrip in Ironforge, who promised copies for his brothers and sisters.", "Gerrig Bonegrip called the day joyous. The Lorgalis Manuscript would be copied and spread."}
P.threads.alliance_boran = "the Blind Princess's lost cargo"
P.threads.alliance_theramore = "Fiora Longears's work from Theramore"
P.threads.alliance_kraul = "the dead of Razorfen Kraul"
q(34, "An Unwelcome Guest", R, 24, K,
    "Martie Jainrose's garden in {p:Lakeshire} had been trampled again, and she knew the brute. Marshal Marris called the boar Bellygrub. Her daffodils were ruined until next season, and she offered a reward for his tusk. He foraged in the field southwest of town.",
    "A boar named Bellygrub had pillaged Martie Jainrose's garden once too often. She wanted to see his tusk.",
    "Martie called the menace laid to rest. Her garden would be in full bloom that season, she said.",
    "Bellygrub's tusk reached Martie Jainrose, who looked forward to a garden in bloom.")
q(281, "Reclaiming Goods", "Wetlands", 25, "alliance_boran",
    "Murlocs had raided the merchant vessel Blind Princess off Menethil. The ship got away, but much of its cargo went overboard with the creatures, among it a valuable statuette of Terenas Menethil. Karl Boran wanted it back from the coastal hovels.",
    "Karl Boran sent a search through the murloc hovels on the coast for the Blind Princess's lost cargo, and above all for the Menethil Statuette.",
    "The first crate was clawed and water-stained. Under the rotted straw lay an armload of red bottles, and no statuette.",
    "A scratched crate among the hovels held soggy straw and red-colored bottles. The statuette was elsewhere.")
q(284, "The Search Continues", "Wetlands", 25, "alliance_boran",
    "The cluster of hovels held no trace of the Menethil Statuette. Two more lay to the north and northeast.",
    "The search for the Blind Princess's statuette went on to the next murloc hovels up the coast.",
    "An untouched barrel gave up a pungent smell of cheese, a little wet and still tasty.",
    "The next barrel held cheese, wet but good, and nothing of Terenas Menethil.")
q(285, "Search More Hovels", "Wetlands", 25, "alliance_boran",
    "A thorough inspection of another group of hovels turned up nothing. One of the hovels to the north had to have the statuette.",
    "Each empty hovel made the next one likelier. The search pushed north along the murloc coast.",
    "A barrel lay half buried in the mud and grass of the last hovel.",
    "The search ended at a barrel sunk halfway into the muck.")
q(286, "Return the Statuette", "Wetlands", 25, "alliance_boran",
    "The barrel pulled from the muck held a silvery figurine packed in fine straw, a young, long-haired paladin with hammer upraised. It had to be the Menethil Statuette, and Karl Boran in {p:Menethil Harbor} was waiting for it.",
    "The Menethil Statuette came out of a murloc hovel's barrel, straw and all, bound for Karl Boran.",
    "Karl Boran said the captain of the Blind Princess would be relieved to have his precious cargo back. Dependable folk were good to see in trying times, he said, and he paid for services rendered.",
    "The statuette of Terenas Menethil reached Karl Boran in Menethil. The Blind Princess's captain would hear of it, and the finder was paid.", 4)
q(1132, "Fiora Longears", "Dustwallow Marsh", 20, "alliance_theramore",
    "Red Jack Flint in Menethil Harbor longed for the sea and saw it in other people's futures. His job was to tell eager souls of Kalimdor, the land of opportunity. He sent them by ship to {p:Theramore} to his partner, the elf Fiora Longears.",
    "A ship from Menethil went to the port of Theramore, where Fiora Longears started newcomers on their Kalimdor adventure, Red Jack Flint said.",
    "Fiora Longears welcomed anyone Mr. Flint sent. He was a strong judge of character, she said, and if he had sent them, they belonged in Kalimdor.",
    "In Theramore, Fiora Longears took Mr. Flint's word as proof enough that the newcomer belonged in Kalimdor.")
q(1135, "Highperch Venom", "Thousand Needles", 30, "alliance_theramore",
    "Wyvern venom, Fiora said, was worth more in some circles than the wyvern. The Highperch wyverns of Thousand Needles, west of Theramore, carried a potent kind, and she had a job for anyone unafraid of hunting them.",
    "Fiora Longears wanted venom sacs from the wyverns of {p:Highperch}, potent and valuable.",
    "Most of the sacs were nearly bursting with venom, Fiora said, the kind normally taken only from young wyverns or fertile females. It must have been quite a slaughter up at Highperch.",
    "Fiora took the venom sacs from Highperch and remarked on their fullness, and on what that said about the hunt.")
q(1142, "Mortality Wanes", "Razorfen Kraul", 30, "alliance_kraul",
    "Heralath Fallowbrook lay dying in {p:Razorfen Kraul}. The brave dwarf Lonebrow had been sent to warn Falfindel, he managed to say. One of the quilboar had stolen the pendant that bound him to his wife Treshala. He asked that it be found and taken to her in Darnassus, with word of his lonely death.",
    "A dying night elf in the Kraul had one request. His wife Treshala's pendant of bonding, stolen by the quilboar, was to go home to her in Darnassus along with the news.",
    "Treshala cried out against a cruel and intolerable world. She would carry the grief, she said, and not let Heralath's work die with him, and then she asked to be left alone to mourn.",
    "The pendant of bonding and the news of Heralath's death reached Treshala in Darnassus. She asked for solitude and spoke of carrying his work on.", 5)
-- Gnomeregan: Techbot, the green glow, Castpipe's data, Kernobee and the Sparklematic.
q(2923, "Tinkmaster Overspark", IF, 26, G,
    "Brother Sarno in Stormwind remembered Techbot as a kind and helpful tool for the gnomes, and had heard from Tinkmaster Overspark that it had malfunctioned. Overspark was in {p:Tinker Town} in Ironforge and would welcome help.",
    "Word of Techbot's breakdown had reached Stormwind. Brother Sarno sent help to its maker, Tinkmaster Overspark in Tinker Town.",
    "It was true, Overspark said. Techbot had gone rogue, and he asked for help.",
    "In Tinker Town, Overspark confirmed the worst about Techbot and accepted the offer of help.")
q(2922, "Save Techbot's Brain!", "Gnomeregan", 26, G,
    "When Gnomeregan fell, a rogue spark had jolted Tinkmaster Overspark's creation, Techbot, and polarized its positronic brain. Now it was negatronic, its behavior reversed, and it roamed {p:Gnomeregan} in a frenzy. Overspark wanted its memory core to find the cause.",
    "Techbot had once aided Overspark and his associates with countless gizmos and a limitless store of information. Its memory core, salvaged from the ruined city, might let the Tinkmaster fix it.",
    "Overspark called it wonderful and got to work at once, with a word of comfort for poor Techbot. Then he went looking for the plug for his hydro-jack swivel spanner.",
    "Techbot's memory core reached Tinkmaster Overspark, who promised the machine it would be fixed and began hunting for a spanner plug.")
q(2927, "The Day After", "Dun Morogh", 27, G,
    "Gnoarn had not always been bald. The radiation leak in Gnomeregan had taken the only gnomefro in Azeroth, and he shook his fist at the troggs. It might not be too late to save the city, he said. Ozzie Togglevolt in {p:Kharanos} and his partner Razzle were working on it.",
    "Gnoarn blamed the troggs for the loss of his hair and damned them all. He sent help to Ozzie Togglevolt in Kharanos, who was working on a solution for Gnomeregan.",
    "Ozzie had stood beside Gnoarn when the radiation bolt hit him and watched those brown locks hit the floor in clumps. Gnoarn had touched his bald head in disbelief, Ozzie said, and the look in his eyes had screamed revenge against the troggs.",
    "Ozzie remembered the day Gnoarn lost his hair, clumps and clusters of it, and the moment his anger turned on the troggs. He had not thought Gnoarn would survive the loss.")
q(2926, "Gnogaine", "Gnomeregan", 27, G,
    "Since the accident, Gnoarn talked of nothing but cleansing Gnomeregan of troggs and curing the sickness, Ozzie Togglevolt said. Ozzie and Razzle were close to a cure, or to a very powerful rum. To test it they needed a phial of green glow from the irradiated troggs.",
    "Ozzie Togglevolt in Kharanos needed fallout from Gnomeregan's irradiated troggs for a formula. Whether it cured gnomes or got them drunk, he could not yet say.",
    "Ozzie called it excellent work and prepared to test the formula. If it worked, he said, the captured leper gnome would be cured and he would have a full head of hair. Then he told everyone to stand back.",
    "The phial of green glow reached Ozzie in Kharanos. He meant to test the formula on a captured leper gnome, and hoped for a full head of hair himself.")
q(2962, "The Only Cure is More Green Glow", "Gnomeregan", 30, G,
    "The first sample had been too small and impure, Ozzie said. The troggs were not irradiated enough. He wanted green glow straight from the tap, from the irradiated slimes, lurkers and horrors of Gnomeregan. It might take several tries with the phial, he warned.",
    "Ozzie's cure needed purer fallout than troggs could give. The slimes, lurkers and horrors in the city's depths were the source, and containing it was difficult.",
    "Ozzie looked the bearer over and was impressed that all the limbs were still attached. Now, he said, it was time to see what this stuff could do.",
    "The purer green glow reached Ozzie in Kharanos. He checked for missing limbs, found none, and turned to his test.")
q(2931, "Castpipe's Task", IF, 28, G,
    "Master Mechanic Castpipe was organizing bands to re-enter Gnomeregan on a data retrieval mission of top importance. He was no member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, but he was a smart gnome. The odds that it mattered were put at eighty-four percent.",
    "Castpipe needed adventurers for Gnomeregan. The errand came with a calculation, an eighty-four percent probability that the mission really was important.",
    "Castpipe was organizing data extraction missions into Gnomeregan, and told anyone there for that to listen up.",
    "In Ironforge, Master Mechanic Castpipe took on another volunteer for the data extraction and began his briefing.")
q(2930, "Data Rescue", "Gnomeregan", 30, G,
    "The gnomes had left vitally important data behind in Gnomeregan, Castpipe said. It sat on a prismatic punch card in a Matrix Punchograph 3005-D high security terminal, deep in the city. Reaching it meant clearance from the lower terminals, models A, B and C. Those needed punch cards the gnomes had also left behind, starting with white.",
    "Castpipe's data rescue began with a white punch card and climbed terminal by terminal to the 3005-D and its prismatic card.",
    "The prismatic punch card was found and the lost data recovered. Castpipe called it vitally, critically, immeasurably important, data the gnomes could not have lived another moment without. The service would be long remembered.",
    "The prismatic punch card reached Master Mechanic Castpipe, who declared the data recovered and the service to the gnomes unforgettable.", 4)
q(2925, "Klockmort's Essentials", IF, 30, G,
    "Mathiel in Darnassus had word from his gnome friend Klockmort Spannerspan in Ironforge. Klockmort needed help on a dangerous mission into Gnomeregan, the once great city now contaminated and full of mad gnomes and their devices. Mathiel could not leave his post.",
    "Mathiel's heart ached to help his friend Klockmort, and he asked someone to go in his stead to Tinkertown in Ironforge.",
    "Klockmort did need help with a mission into Gnomeregan, and declared the newcomer just the one to do it.",
    "In Tinkertown, Klockmort Spannerspan welcomed the help Mathiel had sent across the sea.")
q(2924, "Essential Artificials", "Gnomeregan", 30, G,
    "The essential artificial was a near-universal component, Klockmort Spannerspan said, and the tinkers and smiths of Gnomeregan had used it for everything. In the frantic exodus nobody had thought to take any. He needed a large supply from the artificial extrapolators deep in the city.",
    "Klockmort's new work needed essential artificials, and they were all still in Gnomeregan, in containers in its deeper halls.",
    "Klockmort had his essential artificials and could begin his experiments. The bravery had advanced gnomish research by a leap and a bound, he said.",
    "The artificials from Gnomeregan's extrapolators reached Klockmort Spannerspan in Ironforge, who could not thank the bearer enough.")
q(2928, "Gyrodrillmatic Excavationators", "Gnomeregan", 30, G,
    "Shoni the Shilent in Stormwind's Dwarven District did not have enough parts to get her fleet of gyrodrillmatic excavationators to Dun Morogh. Gnomeregan was full of bots and mechs roaming like cattle on an open range, she said. Two dozen of their robot guts would do.",
    "Shoni's excavationators needed spare parts, and Gnomeregan's robots had them. She wanted two dozen torn apart for their guts.",
    "The robot guts would do nicely, Shoni said. That made one gyrodrillmatic excavationator fixed, with three hundred and ninety-eight to go.",
    "Two dozen robots' worth of parts reached Shoni in the Dwarven District. It fixed one excavationator out of her fleet.")
q(2904, "A Fine Mess", "Gnomeregan", 30, G,
    "Kernobee came to among the troggs of Gnomeregan. The last thing he remembered was Dark Iron dwarves beating him within an inch of his life. He wanted to be led to the exit. Then Scooty in Booty Bay was to hear where he had gone. Kernobee meant to warn Tinkerwiz in Ratchet about the Dark Irons and the super rig.",
    "A battered gnome named Kernobee needed out of Gnomeregan. If he made it, Scooty in Booty Bay was to hear where he had gone and why.",
    "Scooty supposed a reward was in order for bringing Kernobee back in one piece. For anyone going back into Gnomeregan, he added something to give an edge against that backstabber Mekgineer Thermaplugg.",
    "Kernobee's message reached Scooty in Booty Bay. Scooty paid for the rescue and called Mekgineer Thermaplugg a good-for-nothing backstabber.", 4)
q(2951, "The Sparklematic 5200!", "Gnomeregan", 30, G,
    "Among the gnomes holding out against the madness in {p:Gnomeregan} stood a contraption with a plaque, the Sparklematic 5200. For a grime-encrusted item and three silver coins in the slot, it promised to put the shine back in shine-tastic.",
    "The Sparklematic 5200 wanted two things, something grimy to clean and three silver coins.",
    "The grime-encrusted item and three silver went in, and the Sparklematic 5200 surged to life. Loud, violent churning came from its heart and its frame creaked and lurched from side to side as it purged the grime.",
    "Three silver coins and a filthy object set the Sparklematic 5200 churning and groaning and lurching, hard at work on the grime.")
P.questIDs[2930].highlight = {"The prismatic punch card came out of Gnomeregan's 3005-D terminal. Castpipe called the data immeasurably important and the service unforgettable.", "Master Mechanic Castpipe had his lost data back from Gnomeregan on a prismatic punch card."}
P.questIDs[1142].highlight = {"Heralath Fallowbrook's pendant went home to his wife Treshala in Darnassus with word of his death in Razorfen Kraul. She asked to mourn alone.", "Treshala in Darnassus received her husband's pendant and the news of his death in the Kraul, and asked for solitude."}
P.questIDs[286].highlight = {"The Menethil Statuette, a silver paladin with hammer raised, came out of a murloc's barrel and back to Karl Boran in Menethil.", "Karl Boran had the Blind Princess's statuette back from the murloc hovels, and paid for dependable work."}

-- Compact outcomes remain attached to exact quest stages.
P.questIDs[463].highlight = {"The feared Greenwarden offered the name Rethiel. He said the roots and ferns spoke well of his visitor, and asked for help healing the land.", "Fitzsimmons's warning led to Rethiel in the marsh. He welcomed his visitor on the word of the roots and ferns, then asked that the land's wounds be healed."}
P.questIDs[276].highlight = {"The hunt reduced the Mosshides trampling the fen. Rethiel saw hope that his strained faith in his visitor's people might return.", "Fewer Mosshide gnolls and mongrels remained near Algaz. Rethiel praised the help for the Wetlands and cautiously hoped to trust the hunter's people again."}
P.questIDs[277].highlight = {"Rethiel received the Mosshides' fire-making flints. He meant to smash them and cast them into the sea to spare living wood.", "The captured flints reached Rethiel, who promised to break them and throw them into the sea, beyond further use against living trees."}
P.questIDs[275].highlight = {"The fen creepers were put down along the waterways. Rethiel judged the land soothed and granted a boon in thanks.", "Rethiel rewarded the hunt against the fevered fen creepers. He said the work had eased the land's suffering."}

-- Forever additions outside Zephras carry the Forever label in the compendium
-- (factcheck lane, 2026-11-05; explicit list, never inferred from the ID range).
for _, id in ipairs({98046, 98065, 98403}) do
    if P.questIDs[id] then P.questIDs[id].setting = "Forever" end
end

-- The character's side of a stage (DESIGN §3.0; format in JournalBook.lua, QD.Story):
-- `act` folds into a grouped line, the numbered lines tell the moment. Written from each
-- stage's quest text and its fact-checked why/after (pov-alliance lane, 2026-11-07),
-- starting zones first in level order, then the routes out of them.
local POV = {
    -- Northshire (novice: everything new and big).
    [783] = {act = "answered the abbey's call for volunteers", giver = "Deputy Willem",
        "Deputy Willem met {me} outside the abbey and told {me} to strap {my} belt on tight, because the work here was not farming. Inside, Marshal McBride welcomed {us} as volunteers and warned of a long campaign ahead.",
        "With so much of Stormwind's army in distant lands, the abbey's guards were asking anyone willing to defend their home. {We} answered the call, and Marshal McBride only hoped there would be enough of {us}."},
    [7] = {act = "thinned the kobold camp in the woods north of the abbey", giver = "Marshal McBride",
        "Marshal McBride gave {us} {our} first task, a clan of kobolds infesting the woods north of the abbey. {We} thinned their numbers, and he called them thieves and cowards who were still a threat in large numbers.",
        "In the woods north of the abbey {we} fought kobolds, small thieves with candles on their heads. McBride gave {us} his gratitude and hoped to drive them out of the valley one day."},
    [33] = {act = "traded wolf meat to Eagan Peltskinner", giver = "Eagan Peltskinner",
        "Eagan Peltskinner hated the timber wolves but loved a wolf steak, so {we} hunted them across the valley for their tough meat. He could hardly wait to cook it, and let {us} pick from his goods.",
        "{We} brought Eagan the meat of the young wolves and timber wolves that roamed the countryside around the abbey. Already hungry for his steaks, he offered {us} a pick of the things he had to trade."},
    [5261] = {act = "went around the abbey to meet Eagan Peltskinner", giver = "Deputy Willem",
        "Deputy Willem said there were more wolves in the valley lately, and sent {me} around the side of the abbey to Eagan Peltskinner. Eagan looked {us} over and asked whether {we} would hunt his wolves.",
        "Around the side of the abbey {we} found Eagan Peltskinner, the man Deputy Willem had spoken of. He wanted wolves hunted and had work for anyone willing to do it."},
    [15] = {act = "struck the kobold workers at the Echo Ridge Mine", giver = "Marshal McBride",
        "McBride's scouts had found more kobolds than anyone thought, workers camped by the Echo Ridge Mine to the north. {We} killed ten of them and came back to report, and he paid {us}, uneasy at the news.",
        "{We} went north to the Echo Ridge Mine, where kobold workers had camped, and cut down ten of them. McBride paid {us} for it, but he did not like hearing of so many kobolds in his mine."},
    [18] = {act = "took bandanas from the Defias across the river", giver = "Deputy Willem",
        "{We} crossed the river east of the abbey, where a new gang calling itself the Defias Brotherhood had gathered. {We} took their bandanas back to Deputy Willem, and the Stormwind Army paid {us} with a weapon.",
        "Deputy Willem did not know what the Defias were up to, only that it was no good. {We} brought him their bandanas from across the river, and he gave {us} the weapon he had promised."},
    [3903] = {act = "went to help Milly Osworth by her wagon", giver = "Deputy Willem",
        "Deputy Willem called {me} dependable and not afraid to get {my} hands dirty, and sent {us} to his friend Milly Osworth by the stable. Her trouble was more than his duties at the abbey would let him handle.",
        "{We} found Milly Osworth with her wagon on the far side of the abbey, near the stable. Willem was a brave man, she said, but her problem was beyond him, and she asked {us} for help instead."},
    [3904] = {act = "carried Milly's grapes out of the Defias-held vineyards", giver = "Milly",
        "The Defias had moved into the vineyards while Milly was still harvesting, and her buckets of grapes sat among them. {We} carried the crates back to her, and she called {us} heroes she was lucky to have, with guards so short.",
        "Milly feared the Defias would steal her grapes, or the guards would trample them chasing the thugs away. {We} went into the vineyards southeast of the abbey and brought her harvest back safe."},
    [3905] = {act = "brought Milly's grape manifest to Brother Neals", giver = "Milly",
        "{We} climbed the bell tower of the abbey with Milly's manifest, up to where Brother Neals liked to taste his wine. He had nearly despaired over the vineyards, he said, and he blessed {us} in the Light for the grapes.",
        "Brother Neals kept the abbey's food and drink, and Milly's manifest meant fresh grapes and more wine. His faith in the Light had never wavered, he told {us}, and he asked it to keep {us} safe."},
    [6] = {act = "took the head of Garrick Padfoot at his shack", giver = "Deputy Willem",
        "Garrick Padfoot had plagued the farmers and merchants for weeks, and his thugs guarded his shack across the bridge near the vineyards. {We} got past his gang and brought his head to Deputy Willem, who paid the bounty.",
        "The bounty was on a cutthroat named Garrick Padfoot, hiding with a gang of thugs at a shack east of the abbey. {We} came back with his head, and Willem said {we} had done the whole forest a great service."},
    [21] = {act = "fought the kobolds deep in the Echo Ridge Mine", giver = "Marshal McBride",
        "McBride sent {us} back into the Echo Ridge Mine before the kobolds could dig a deeper foothold in the valley. It was bloody work in the tunnels, and he gave {us} his respect and the army's gratitude.",
        "{We} went down into the Echo Ridge Mine, dark and full of kobolds, and fought them through its tunnels. McBride said he would send others against the ones left, and that he had further tasks for {us}."},
    [54] = {act = "carried McBride's papers south to Marshal Dughan", giver = "Marshal McBride",
        "Marshal McBride trusted {me} now with the safety of the wider forest, and gave {me} papers for Marshal Dughan down the southern road. In the town Dughan read them and named {me} an Acting Deputy of the Stormwind Marshals.",
        "{We} left the valley by its border gates and took the southern road with McBride's papers. Marshal Dughan made {me} an Acting Deputy, and warned that keeping the forest safe was no picnic with the army away."},
    -- Goldshire and the forest.
    [2158] = {act = "found a seat by the fire at the Lion's Pride Inn",
        "Told there was no finer place to rest than the Lion's Pride Inn, {we} followed the road south and found Innkeeper Farley. He offered {us} a seat by the fire and a sampling of the inn's food and drink.",
        "{We} rested by the fire at the Lion's Pride, where a friend of Farley's had sent {us} for his discounted rates. The innkeeper greeted {us} with his motto, rest and relaxation for the tired and cold."},
    [85] = {act = "asked Billy Maclure about a widow's lost necklace", giver = "Bernice",
        "An old widow, Bernice, had lost her necklace and blamed Billy Maclure from the vineyards next door. {We} found the boy, who swore he was no thief, then grinned that he was too hungry to remember.",
        "{We} went to the Maclure vineyards to ask young Billy about the widow's necklace. He denied taking it, but said he might know who did, if only he were not so hungry."},
    [86] = {act = "hunted boar meat for Bernice's pie",
        "Billy would talk for a pork belly pie, so {we} hunted the boars around the farms and brought the meat to old Bernice. She did not like feeding the boy who had taken her necklace, but she started the pie.",
        "{We} carried tough boar meat to Bernice for the pie Billy wanted. Simmered long enough, she told {us}, it made a tasty pie, even for a boy she believed had stolen from her."},
    [84] = {act = "brought Bernice's pie to Billy", giver = "Bernice",
        "Bernice handed {us} the pie with a message for Billy, that she hoped he choked on it. {We} carried it to the vineyards, and the boy ate it and said his memory was coming back.",
        "{We} brought Billy his pork belly pie, the widow's curse still on it. He called it the best pie there was, and said his memory was coming back to him."},
    [106] = {act = "carried Maybell Maclure's letter to Tommy Joe", giver = "Maybell Maclure",
        "Maybell Maclure loved Tommy Joe Stonefield, but their families were bitter enemies. {We} took her letter to the river west of the Stonefield farm, where Tommy Joe read it and swore he had to see her.",
        "{We} carried a love letter across a family feud, from Maybell at the vineyards to Tommy Joe by the river. He called her the light of his dull life and could not bear being apart from her."},
    [111] = {act = "asked Gramma Stonefield to help the young lovers", giver = "Tommy Joe Stonefield",
        "Tommy Joe sent {us} into the Stonefield house to his Gramma, sure that she could find a way. She doubted the pair had much future while the families feuded, but thought they might meet for a little while.",
        "Inside the Stonefield farmhouse {we} told Gramma about Tommy Joe and Maybell. She began to puzzle over how to bring them together, for a little while at least, with the feud still on."},
    [107] = {act = "took Gramma Stonefield's note to William Pestle", giver = "Gramma Stonefield",
        "Gramma Stonefield was sure William Pestle had a potion to unite the young lovers, and sent {us} to the inn with her note. William had not seen Mildred in years, and his heart went out to Maybell and Tommy Joe.",
        "{We} brought Gramma's note to William Pestle at the Lion's Pride Inn. He remembered being young and in love once, he said, and set to thinking how he might help."},
    [47] = {act = "sold kobold gold dust to Remy Two Times",
        "Remy Two Times, who liked to say everything twice, wanted the gold dust the kobolds carried and promised the best price in town. {We} took it from the kobolds of the mines, and with his coin came a token from his associates.",
        "{We} sold Remy Two Times the gold dust from the kobolds of the Fargodeep and Jasperlode mines. He paid, then added a token from his associates, something he said might be useful, useful."},
    [60] = {act = "gathered kobold candles for William Pestle", giver = "William Pestle",
        "William Pestle ran an apothecary in Stormwind with his brother and wanted kobold candles for their wax. {We} took them from the kobolds of the mines, and he paid {us}, remarking that {we} had been busy.",
        "{We} brought William Pestle a load of large candles, taken from the kobolds who wore them in the mines. The wax was bound for his family's apothecary in Stormwind."},
    [62] = {act = "scouted the Fargodeep Mine for Marshal Dughan", giver = "Marshal Dughan",
        "Marshal Dughan had reports that the Fargodeep Mine south of town had become a haven for kobolds. {We} went in between the Stonefield and Maclure farms and found the reports true, and he spoke of more patrols.",
        "{We} explored the Fargodeep Mine, its tunnels full of kobolds, and brought the news back to Marshal Dughan. It was bad news, he said, and he wondered aloud whether dragons would be next."},
    [112] = {act = "took crystal kelp from the murlocs of Crystal Lake", giver = "William Pestle",
        "William needed crystal kelp for an invisibility liquor that would let Maybell slip away, and the murlocs of Crystal Lake sometimes gathered it. {We} hunted them along the lake east of town and brought him the kelp.",
        "{We} fought the murlocs at Crystal Lake for the ocean kelp they had collected. William called it good work and set to mixing the potion meant for Maybell."},
    [114] = {act = "brought the invisibility liquor to Maybell", giver = "William Pestle",
        "{We} carried William's invisibility liquor back to Maybell at the vineyards. She felt guilty deceiving her family, but her feelings for Tommy Joe were too strong to ignore, and she gave {us} a gift for the help.",
        "Maybell took the liquor and meant to drink it at her first chance and sneak away to Tommy Joe. {We} had carried the last piece of a plan to get two young lovers past a feud, and she thanked {us} with a gift."},
    [87] = {act = "took Bernice's necklace back from Goldtooth in the Fargodeep Mine", giver = "Billy Maclure",
        "Billy swore a gold-toothed kobold had run off into the Fargodeep Mine with the necklace, though not how it got there. {We} went into the mine, found Goldtooth, and brought the necklace home to Bernice.",
        "Deep in the Fargodeep Mine {we} found the kobold Goldtooth with Bernice's necklace. She thanked {us} with a sniff and gave {us} her husband's lucky keepsake, the one he had forgotten on his last campaign."},
    [83] = {act = "brought Defias bandanas to Sara Timberlain", giver = "Sara Timberlain",
        "The Defias of the forest wore red linen, finer than the burlap masks of the gang near the abbey, and Sara Timberlain at Eastvale wanted the cloth. {We} raided their camps for bandanas, and she made {us} something from them.",
        "{We} carried a stack of red linen bandanas to Sara Timberlain's workbench at the logging camp. A little rough, she said, but good cloth, and she paid {us} with her own work."},
    [88] = {act = "killed Princess, the Brackwells' prize sow",
        "Princess, the Brackwells' prize-winning sow, had grown huge on her neighbors' vegetables. {We} found her at the pumpkin patch east of the Maclure farm, killed her, and took her collar back as proof.",
        "{We} hunted down Princess at the Brackwell Pumpkin Patch before she could come eating another farm's crop. The farmer was relieved that the crop was safe, and offered {us} a choice of reward."},
    [5545] = {act = "recovered bundles of wood for Supervisor Raelen", giver = "Supervisor Raelen",
        "Wolves and bears had chased Supervisor Raelen's workers away from the wood they had already cut, and the lumber order was due. {We} went north of the camp and gathered eight bundles, and Raelen paid {us}, sure now of the deadline.",
        "{We} hauled eight bundles of chopped wood back to the Eastvale camp from the woods where the animals prowled. Raelen expected to finish the order in time and gave {us} coin for the trouble."},
    [11] = {act = "brought Riverpaw armbands to Deputy Rainer", giver = "Deputy Rainer",
        "Gnolls had come over the border in a pack too big for Westbrook's guards, in the woods south of the tower and by Stone Cairn Lake. {We} took their painted armbands to Deputy Rainer, and the army gave {us} its thanks.",
        "The Riverpaw gnolls were brutes with no business in the forest, Deputy Rainer said, and too many for his garrison. {We} brought him a stack of their painted armbands, and he thanked {us} for being busy."},
    -- Eastvale's murlocs.
    [40] = {act = "carried Remy's murloc warning to Marshal Dughan",
        "Remy Two Times swore murlocs were swimming up the eastern streams, scaring the fish and attacking gentle folk. {We} carried his worry to Marshal Dughan, who respected Remy as a merchant but wanted a military report first.",
        "{We} tried to persuade Marshal Dughan to send troops east on Remy's word. The marshal was more worried about the gnolls and the bandits, and called the murloc reports sketchy at best."},
    [35] = {act = "asked Guard Thomas at the eastern bridge for his report", giver = "Marshal Dughan",
        "Dughan would not believe in Remy's murlocs without a soldier's word, so {we} went to Guard Thomas at the eastern bridge. He had watched the area for a week, and he told {us} the murlocs had settled in the streams.",
        "{We} found Guard Thomas at the eastern bridge, posted there a week. The murlocs were real, he told {us}, aggressive and at least half clever, and nobody knew why they had come."},
    [37] = {act = "found Footman Malakai Stone's body by the river", giver = "Guard Thomas",
        "Two of Guard Thomas's men, Rolf and Malakai, had gone up the river days before and not returned. {We} followed the river north and found a stripped body, and beside it a medallion that read Footman Malakai Stone.",
        "Searching the river for Thomas's lost guards, {we} came on a corpse stripped of almost everything. A medallion lay nearby with a name etched on it, Footman Malakai Stone."},
    [45] = {act = "found Footman Rolf Hartford near the murloc village",
        "Webbed footprints led {us} east along the shore of Stone Cairn Lake, toward a murloc village in the distance. There {we} found the second body, with a medallion around its neck inscribed Footman Rolf Hartford.",
        "{We} tracked the murlocs' footprints along the lake to their village, and found Rolf at the end of them. Around the dead guard's neck hung his medallion, Footman Rolf Hartford."},
    [71] = {act = "brought both medallions back to Guard Thomas", giver = "Guard Thomas",
        "{We} brought the medallions of Rolf and Malakai back to Guard Thomas at the bridge. They confirmed his fears, he said, and the murlocs were now a threat no one could ignore.",
        "Guard Thomas had waited at the bridge to learn what became of his men, and {we} gave him their two medallions. The murlocs had killed them both, and he named them a danger the forest could not ignore."},
    [39] = {act = "carried Thomas's report of the murdered guards to Dughan", giver = "Guard Thomas",
        "{We} carried Guard Thomas's report to Marshal Dughan, the deaths of Rolf and Malakai and the warning that his few guards could not hold the murlocs. Dughan feared there would be fighting in town by the week's end.",
        "Thomas needed more soldiers in the east, and {we} brought his plea to Marshal Dughan with the news of the two dead guards. His defenses were already stretched thin, the marshal said, and this made them worse."},
    [46] = {act = "hunted murlocs for their fins at Stone Cairn Lake", giver = "Guard Thomas",
        "The army had put a bounty on murloc lurkers and foragers, and {we} hunted them in their villages at Stone Cairn Lake and the fork of the southern stream. Guard Thomas took the torn fins gladly.",
        "{We} brought Guard Thomas a pile of torn murloc fins from the villages north and south of his bridge. He meant to tell the anxious marshal that the murlocs were coming under control, thanks to {us}."},
    [52] = {act = "hunted the wolves and bears around the Eastvale camp", giver = "Guard Thomas",
        "The farther from town, the bolder the beasts, and the Eastvale Logging Camp suffered nearly constant attacks. {We} hunted the prowlers and young bears around it, and Guard Thomas wondered what in the forest made them so bold.",
        "{We} thinned the wolves and bears that kept falling on the loggers of Eastvale. Something in the forest must be driving them, Thomas said, and he hoped it stayed there."},
    [59] = {act = "traded Dughan's marker for armor from Sara Timberlain", giver = "Marshal Dughan",
        "For {our} work in the east Marshal Dughan gave {us} a marker good for one piece of armor, and sent {us} to Sara Timberlain at the logging camp. She let {us} pick, and wished {us} luck with it.",
        "Sara Timberlain made cloth and leather armor for the army, and Dughan's marker bought {us} a piece of it. {We} chose {our} armor at the Eastvale camp, meant for the defense of the forest."},
    [76] = {act = "scouted the Jasperlode Mine past the Tower of Azora", giver = "Marshal Dughan",
        "Dughan needed a scout for the more distant Jasperlode Mine, so {we} followed the road east to the Tower of Azora and north into the foothills. Kobolds were there too, and he cursed at the news.",
        "{We} found kobolds in the Jasperlode Mine as well, in the foothills north of the Tower of Azora. Dughan thanked {us} for the scouting, wishing only that {we} had brought good news."},
    -- The Collector and the western border.
    [123] = {act = "took the Collector's pickup schedule to Dughan",
        "A schedule came into {our} hands, days and times when someone called the Collector would receive gold from the forest's mines. {We} took it to Marshal Dughan, whose people had not worked those mines in months.",
        "{We} showed Marshal Dughan a pickup schedule naming the Collector, who seemed to live near the Brackwell Pumpkin Patch. He had heard the name but not whom the man worked for, and thanked {us} for the lead."},
    [147] = {act = "brought the Collector to justice at the Brackwell Pumpkin Patch", giver = "Marshal Dughan",
        "Dughan called the Collector a thief stealing from the kingdom, and {we} found him at the Brackwell Pumpkin Patch and brought him to justice. On him was a ring of the old Stonemasons' Guild of Stormwind.",
        "{We} hunted down the Collector at the pumpkin patch and brought his ring to Marshal Dughan. The marshal could not say why a thief wore a stonemason's guild ring, or why the Defias were collecting from the mines, and hoped for answers one day."},
    [239] = {act = "went to Deputy Rainer at the Westbrook Garrison", giver = "Marshal Dughan",
        "The Westbrook Garrison wanted more soldiers against gnolls and thieves, and Dughan had none to spare, so he sent {us} down the western road. Deputy Rainer saw that {we} came from no army, but Dughan's word was good enough for him.",
        "{We} crossed the bridge over the brook to the Westbrook Garrison and offered Deputy Rainer {our} help. His situation was stressed, to say the least, and he was glad to have it."},
    [176] = {act = "brought down Hogger, the huge gnoll of the southwestern woods",
        "Hogger, a huge gnoll, had overpowered everyone sent to capture him in the southwestern woods. {We} hunted him down and brought proof to Marshal Dughan, who laughed that he had started to think no one would.",
        "{We} faced Hogger in the woods near Westbrook, the gnoll the army had failed to bring down. Dughan paid {us} the bounty and said the beast had given him a headache the size of Blackrock Spire."},
    -- Later errands back in the forest.
    [118] = {act = "carried Verner Osgood's note to Smith Argus", giver = "Verner Osgood",
        "Verner Osgood in Lakeshire had spent his iron outfitting the guards and had none left for horseshoes, so {we} carried his note back to Smith Argus in Goldshire. Argus told {us} to speak up, then laughed that old Verner needed shoes.",
        "{We} brought Verner's request for a shipment of horseshoes to Smith Argus, a long way back from Redridge. The old smith was hard of hearing, and amused that Verner needed shoes."},
    [178] = {act = "brought a speaking Shadowhide pendant to Theocritus",
        "A Shadowhide pendant spoke to {me} in a stranger's voice, Theocritus, High Mage of the Tower of Azora, who had learned to talk through the gnolls' link to Morganth. {We} took it to his tower, on a road {we} knew well by then.",
        "{We} carried the gnoll pendant to the Tower of Azora. Theocritus had sent his message weeks before and thought the spell had failed, and he hoped one day to strike the Shadowhide through their own pendants."},
    [344] = {act = "found the Stresses of Iron with Brother Paxton",
        "The Stresses of Iron, written by the dwarven miner Margulf Blaggon, had gone to the abbey months before so Brother Paxton could copy it. {We} went up to the abbey and found Paxton, a little embarrassed, still at his copy.",
        "{We} asked Brother Paxton at the abbey for the Stresses of Iron on Mr. Sheaf's behalf. He still had it, he admitted, and was not ready to give up the original before his copy was done."},
    [347] = {act = "took Rethban ore from the gnoll drudgers",
        "Paxton needed Rethban ore for the dark dye of his ink, and the gnoll drudgers of the Rethban Caverns north of Lakeshire were mining it themselves. {We} took it from them and brought it to the abbey, and he could finish his copy.",
        "{We} went into the Rethban Caverns, where Redridge gnolls dug the ore named for Bart Rethban, and came out with enough for Paxton. He was delighted, and could finish copying the Stresses of Iron at last."},

    -- Coldridge Valley and Dun Morogh (novice).
    [179] = {act = "traded wolf meat for a pair of warm gloves",
        "An outfitter of Anvilmar looked at {my} hands and offered a pair of warm gloves, on one condition. {We} hunted the valley's wolves for their meat, and he kept his side of the bargain so {we} would lose no fingers to frostbite.",
        "{We} brought the outfitter the wolf meat he wanted, keeping clear of the fangs and claws as best {we} could. He had not forgotten his part of the bargain, and found {us} gloves that fit."},
    [170] = {act = "drove back the troggs in the valley's hills", giver = "Balir Frosthammer",
        "Balir Frosthammer was shorthanded after the last trogg attack, and the troggs had overrun the camp to the west only nights before. {We} drove them back through the hills to the southeast and around the frozen lake.",
        "{We} fought {our} first troggs in the hills of the valley, tenacious little buggers just as Balir Frosthammer said. If the rest of the dwarven lands fared the same, he swore by Magni's beard, there was trouble ahead."},
    [183] = {act = "thinned the angry boars for Talin Keeneye", giver = "Talin Keeneye",
        "There were so many angry boars in the valley that even Talin Keeneye's daily hunt had become dangerous. {We} thinned them for him, and he thanked {us} and went back to his leisurely hunting.",
        "{We} hunted the boars around the frozen lake, already angry and charging without any help. Talin Keeneye could go back to his daily hunt without danger, and he was grateful."},
    [233] = {act = "carried the mail through the valley to Talin Keeneye", giver = "Sten Stoutarm",
        "A stack of letters had come through the pass with nobody free to carry them, so {we} took them down the road to Talin Keeneye's camp by the frozen lake. He had waited a long time for them.",
        "{We} played postman in the valley, carrying a stack of letters west to Talin Keeneye. Not all of them were his, and one still had to go on to Grelin Whitebeard."},
    [3361] = {act = "took Felix Whindlebolt's belongings back from the trolls", giver = "Felix Whindlebolt",
        "Felix Whindlebolt had fled Gnomeregan's radiation and lost everything to the trolls on the way. {We} went into their camps southwest of Anvilmar and brought back his chest, his box and his bucket of bolts.",
        "No adventurer himself, Felix told {us} that the valley had as many nasty creatures as his ruined city. {We} recovered his things from the Frostmane camps, and he called {us} an absolute savior."},
    [182] = {act = "cleared the Frostmane trolls from the southern cave", giver = "Grelin Whitebeard",
        "Grelin Whitebeard had been sent to look into the trolls of Dun Morogh, and judged that a few strong arms would do for the ones in the valley's southern cave. {We} took up the work, and the Frostmane fell back before {us}.",
        "{We} went into the southern cave and fought the Frostmane trolls for Grelin Whitebeard. When {we} came back he was cursing them, for a group of trolls had stolen his notebook in the night."},
    [234] = {act = "brought Grelin Whitebeard his letter from Ironforge",
        "One of Talin's letters belonged to Grelin Whitebeard, so {we} carried it down the road to his camp in the southeast. It had been a while since he had heard from Ironforge.",
        "{We} brought the last of the valley's mail to Grelin Whitebeard's camp. He was glad of it, word from Ironforge after a long wait."},
    [218] = {act = "took Grelin's notebook back from the trolls' cave", giver = "Grelin Whitebeard",
        "A big troll with odd markings on his skin had carried Grelin's notebook into the cave. {We} went back in after him and brought the notebook out, and Grelin judged the troll trouble in the valley under control.",
        "{We} hunted the marked troll through the cave and took back Grelin Whitebeard's notebook. Now he could finish his report for his brother Senir, and he needed someone to carry it."},
    [282] = {act = "took Grelin's report to Mountaineer Thalos at the tunnel", giver = "Grelin Whitebeard",
        "Grelin trusted {me} with his report rather than his apprentice, and sent {me} toward Kharanos through a tunnel full of troggs. Mountaineer Thalos stood guard before it, and he would not stop a courier on Whitebeard's business.",
        "{We} followed the road past Anvilmar to the tunnel, where Mountaineer Thalos warned that troggs infested it. Since Whitebeard had sent {us}, he gave {us} advice and directions instead of turning {us} back."},
    [420] = {act = "carried Grelin's report through the tunnel to Senir", giver = "Mountaineer Thalos",
        "{We} went through the tunnel past its hostile troggs and followed the road on into Kharanos. Senir Whitebeard read his brother's report and laughed that its use of the king's name would ruffle some feathers in the Senate.",
        "The troggs in the tunnel attacked anyone who passed, but {we} came out the far side and found Senir in Kharanos. He took his brother's report, admitted he was behind on his own, and promised {us} work later."},
    [2160] = {act = "carried Hands Springsprocket's package to the Kharanos inn", giver = "Hands Springsprocket",
        "Hands Springsprocket could not get through the trogg-held pass, so {we} carried his package to Tannok Frosthammer at the inn. Tannok had begun to worry, and offered {us} a seat by the fire.",
        "{We} brought supplies from Hands to the inn at Kharanos, where there had been scarce word from Anvilmar since the troggs took the pass. Tannok Frosthammer told {us} to get comfortable after such a journey."},
    [3364] = {act = "rushed a scalding mornbrew to Durnan Furcutter", giver = "Nori Pridedrift",
        "Nori Pridedrift had a cup of scalding mornbrew that would only stay hot five more minutes, and Durnan Furcutter had not ordered it chilly. {We} hurried it into Anvilmar, and Durnan took a break to enjoy it.",
        "{We} ran a steaming mug of mornbrew up to Durnan Furcutter in Anvilmar, the settlement dug into the mountain, before it could go cold. He said it hit the spot."},
    [3365] = {act = "brought Durnan's empty mug back to Nori", giver = "Durnan Furcutter",
        "Durnan drained his mornbrew and handed {us} the empty mug for Nori. {We} brought it back, and Nori said few couriers ever remembered something so simple, since mugs did not grow on trees.",
        "{We} remembered the mug, which by Nori's account put {us} ahead of most couriers. Nori paid {us} a little for carrying it back from Anvilmar."},
    [400] = {act = "delivered a parcel of tools to Beldin Steelgrill", giver = "Tharek Blackstone",
        "Beldin Steelgrill broke arclight spanners almost faster than they could be made, and {we} lugged his latest order of tools to his depot. He had broken his last fang-ratchet only an hour before, and paid {us} for it.",
        "{We} carried a crate of tools to Steelgrill's Depot, a haunt of siege engine pilots, where Beldin thought {us} a little young to be one. The tools let him finish Pilot Stonegear's engine."},
    [310] = {act = "switched a barrel in the Thunderbrew cellar for Marleth", giver = "Marleth Barleybrew",
        "Marleth Barleybrew wanted the Thunderbrews to learn that theirs was not the only decent brew. {We} crept into the basement of their distillery and set Marleth's barrel of Barleybrew Scalder among the Thunder Ale.",
        "{We} slipped a barrel of Barleybrew Scalder into the Thunderbrew Distillery's cellar, where it would soon be tapped. It was a small prank in an old brewing rivalry, and {we} had a hand in it."},
    [317] = {act = "hunted fur and meat to stock Jetsteam", giver = "Pilot Bellowfiz",
        "Pilot Bellowfiz needed a month of supplies for a long Siege Brigade mission in his engine, Jetsteam. {We} hunted the snow fields south of the Grizzled Den for bear fur and boar meat, and he swore by Magni's beard at how much {we} brought.",
        "{We} stocked a siege engine for a month on the road, bear fur for bedding and boar meat for food. Bellowfiz thanked {us}, ready for his mission while Steelgrill finished work on the tank."},
    [5541] = {act = "recovered Rumbleshot's lost crate of ammunition",
        "A courier had fled from wendigo near the Grizzled Den and left Hegnar Rumbleshot's ammunition behind. {We} found the crate and carried it to his gun shop, where he laughed that late was better than never.",
        "{We} brought Hegnar Rumbleshot a crate of ammunition he had given up for lost. The riflemen practicing near his shop had nearly emptied him, and he already had buyers waiting."},
    [311] = {act = "brought a barrel of Thunder Ale back to Marleth", giver = "Marleth Barleybrew",
        "{We} took a barrel of Thunder Ale from the Thunderbrew cellar as proof of the switch and carried it to Marleth, who asked whether the guard had given {us} trouble, then thanked {us} warmly.",
        "Marleth had her proof when {we} came back with the Thunderbrews' own barrel. If {we} ever needed a stout with a kick, Marleth told {us}, the Barleybrews would be waiting."},
    [313] = {act = "brought wendigo manes from the Grizzled Den to Pilot Stonegear", giver = "Pilot Stonegear",
        "Pilot Stonegear wanted a rug for the inside deck of his siege engine, Trollplow, and dared {us} to prove {our} mettle at the Grizzled Den. {We} came back with a heap of wendigo manes, and he wagered {we} would do great things.",
        "{We} fought the wendigo of the Grizzled Den, west of the town, for their shaggy manes. Stonegear took them for Trollplow's deck and said {we} showed a lot of grit."},
    [318] = {act = "asked Rejold Barleybrew for a cask of Evershine", giver = "Pilot Bellowfiz",
        "Bellowfiz wanted Evershine, a brew so hot he could throw it in Jetsteam's furnace for a burst of power. {We} went west to Brewnall Village and asked Rejold Barleybrew, who agreed after a moment's thought.",
        "{We} found Rejold Barleybrew at Brewnall Village, a brewer whose drinks could lay all but the stoutest dwarf flat. He allowed that Bellowfiz could have some of his Evershine."},
    [384] = {act = "gathered boar ribs and Rhapsody Malt for Ragnar Thunderbrew", giver = "Ragnar Thunderbrew",
        "The trapper who supplied the tavern had gone off to the king's army, so {we} hunted crag boars for their ribs and fetched a Rhapsody Malt. In return {we} had the family recipe for Beer Basted Boar Ribs and a sample to taste.",
        "{We} brought six crag boar ribs and a mug of Rhapsody Malt to Ragnar Thunderbrew, who answered with a rhyme about fighting for first dibs. The secret, it turned out, was in the malt."},
    [319] = {act = "cleared the beasts around Brewnall Village", giver = "Rejold Barleybrew",
        "Rejold would part with his Evershine if {we} helped the village with the bears, cats and boars that wandered close. {We} hunted them in the hills around the village, and Brewnall could work its crafts in peace.",
        "{We} hunted the animals around Brewnall Village so the dwarves could get back to their brewing. No dwarf was afraid of them, Rejold said, but he was glad of fewer growls and snorts outside."},
    [320] = {act = "brought the cask of Evershine to Bellowfiz", giver = "Rejold Barleybrew",
        "{We} carried Rejold's cask of Evershine back to Pilot Bellowfiz at the depot. He decided to open a bottle right away and have a taste.",
        "Bellowfiz had his Evershine at last when {we} brought the cask from Brewnall, warmth for the cold road and fuel for Jetsteam's furnace. He opened a bottle before {we} had even left."},
    [287] = {act = "scouted Frostmane Hold for Senir Whitebeard", giver = "Senir Whitebeard",
        "Senir Whitebeard had found where the trolls were holed up but saw too many to go in himself. {We} followed his directions past Brewnall Village to Frostmane Hold, killed a few trolls inside, and he finished his report at last.",
        "{We} went down into Frostmane Hold, southwest of Brewnall, a cave crowded with trolls. Senir praised his own directions when {we} came back, then laughed and asked for one last favor."},
    [315] = {act = "gathered Frostmane shimmerweed for Rejold Barleybrew", giver = "Rejold Barleybrew",
        "Rejold Barleybrew was on a quest for the perfect stout, and wanted to try the shimmerweed the Frostmane trolls grew in the hills to the east. {We} took it from their seers and baskets, and he could not wait to brew with it.",
        "{We} brought Rejold a bundle of shimmerweed, a plant the trolls used in their rituals and the dwarves had never found a use for. He already had a recipe in mind for it."},
    [432] = {act = "killed the troggs wrecking Foreman Stonebrow's quarry",
        "The troggs were turning Gol'Bolar Quarry into a wreck, and Foreman Stonebrow was too angry and too poor a shot to stop them. {We} went down among them and killed a good many, and it made him feel a little better.",
        "{We} fought the troggs in the quarry where Stonebrow had watched his barrels of powder go to waste. He would not be happy until every one was dead, he told {us}, but it was a start."},
    [412] = {act = "took cogs and gears from the leper gnomes outside Gnomeregan", giver = "Razzle Sprysprocket",
        "The gnomes had failed to clear the troggs from Gnomeregan and turned most of their own people into leper gnomes. {We} took the cogs and gears that Ozzie and Razzle's Recombobulator needed from the lepers outside the city's gates.",
        "{We} stood before the gates of Gnomeregan, among leper gnomes who had once been its people, and took the parts the Recombobulator needed. Razzle found them in perfect accordance with Ozzie's schematics."},
    [413] = {act = "carried Rejold's Shimmer Stout to his brother Wellart", giver = "Rejold Barleybrew",
        "Rejold's new Shimmer Stout was for his brother Wellart, a mountaineer at the southern guard tower on the border with Loch Modan. {We} carried the barrel out to him, and one taste put a shine in his eyes.",
        "{We} brought a barrel of Shimmer Stout to Mountaineer Wellart Barleybrew, who had not had a good fight in days. He tasted it and swore he could see in the dark."},
    [415] = {act = "went back to Brewnall to taste Rejold's new brew",
        "Word reached {us} that Rejold Barleybrew wanted to see {us} about a new drink, with free booze in it perhaps. {We} went back to Brewnall, where the shimmerweed {we} had brought him had turned into one great recipe.",
        "Rejold had used {our} shimmerweed in a few recipes, and one had turned out great. {We} went back to Brewnall Village to taste it, and he wanted to know what {we} thought."},
    [419] = {act = "found the body of the lost pilot Mori Hildelve", giver = "Pilot Hammerfoot",
        "Pilot Hammerfoot's friend Mori Hildelve had gone into the hills on foot looking for a rare ore, and days had passed with beasts growling at night. {We} found him at last, mauled and frozen, with his notes still clutched in his hand.",
        "{We} searched the hills for Mori Hildelve and found only his body, picked clean by scavengers, a Brigadier's Vest still on its frame. It was a grim end to the search, and Hammerfoot would have to hear of it."},
    [417] = {act = "avenged Mori Hildelve on the bear Mangeclaw", giver = "Pilot Hammerfoot",
        "Hildelve's notes told of Mangeclaw, a huge ice claw bear that had mauled him, and ended with one wish, revenge. {We} hunted the bear down and killed it, and Hammerfoot said the Siege Brigade would remember the deed.",
        "{We} granted a dead pilot his last wish and killed Mangeclaw, the bear that had come back for Hildelve. Hammerfoot grieved for a good friend and wished he could have been there with {us}."},
    [433] = {act = "fought the troggs in Gol'Bolar Quarry for Senator Stonehallow", giver = "Senator Mehr Stonehallow",
        "The troggs had poured out of the earth at Gol'Bolar Quarry, destroyed the miners' equipment and driven them out. {We} fought them for Mehr Stonehallow, who called it a start and hoped to bring mountaineers in.",
        "{We} went into Gol'Bolar Quarry against the troggs that had driven the miners away. The senator thanked {us} and spoke of the long work ahead, securing the quarry and getting the miners back."},
    [312] = {act = "took Tundra MacGrann's meat locker from Old Icebeard's cave", giver = "Tundra MacGrann",
        "Old Icebeard had carried off Tundra MacGrann's thorium meat locker, a month of salted meat for the cold season. MacGrann's bad leg kept him from the cave, so {we} went in, got the stash, and came out again.",
        "{We} slipped into Old Icebeard's cave for Tundra MacGrann's meat locker, which the yeti could not smash open. MacGrann called {us} a kind soul, for now he would not starve when the cold season came."},
    [314] = {act = "slew Vagash, the beast preying on the Amberstill herd", giver = "Rudra Amberstill",
        "Vagash had taken two rams from the Amberstill herd in the night, and with Magni's army far away no one kept him at bay. {We} climbed above the ranch, killed the beast, and brought Rudra Amberstill one of his fangs.",
        "{We} hunted Vagash in the hills above the Amberstill ranch, a deadly beast just as Rudra had warned. Rudra pictured {us} one day fighting beside Magni's soldiers on the Alliance Front."},
    [2927] = {act = "carried Gnoarn's hope for Gnomeregan to Ozzie Togglevolt", giver = "Gnoarn",
        "Gnoarn had once had the only gnomefro in Azeroth, before the radiation in Gnomeregan took it, and he still shook his fist at the troggs. {We} knew those roads well by now, and went to Ozzie Togglevolt in Kharanos as he asked.",
        "{We} brought Gnoarn's hope for his city to Ozzie Togglevolt in Kharanos. Ozzie had been beside Gnoarn when the radiation bolt hit him, and he told {us} of the brown locks falling in clumps and the look of revenge in his eyes."},
    [467] = {act = "answered Pilot Stonegear's call for an ore hunter",
        "Pilot Stonegear was always looking for more firepower for his tank, and word reached {us} that he wanted a rare ore found. {We} went back to Steelgrill's Depot, roads {we} had long since learned, and he was glad to see someone eager for adventure.",
        "At Steelgrill's Depot, Pilot Stonegear was glad to see blood that burned at the prospect of adventure. He had heard rumors of a rare ore, and explained the search he had in mind for {us}."},
    [466] = {act = "brought incendicite ore from the Wetlands to Stonegear", giver = "Pilot Stonegear",
        "Stonegear had heard of incendicite in a cave northwest of Algaz Gate, a volatile ore he thought would make cannon shells with a mighty punch. {We} went down into the Wetlands, took the ore from its cave, and brought it back to his depot.",
        "{We} carried volatile incendicite ore all the way from the Wetlands to Pilot Stonegear. He meant to find someone to work it right away, and hoped they would not blow themselves up."},

    -- Shadowglen and Teldrassil (novice).
    [458] = {act = "sought out the dryad Tarindrella southwest of Aldrassil", giver = "Melithar Staghelm",
        "Melithar Staghelm had heard strange news in the whisperings of the forest spirits. The dryad Tarindrella, unseen in Kalimdor's forests for years, had come back to the glade, and {we} went southwest of Aldrassil to find her.",
        "{We} found Tarindrella, the woodland protector, in the woods southwest of Aldrassil, where a Sentinel had seen her. She called Melithar wise for sending {us}, and something was surely amiss if she had come back."},
    [456] = {act = "thinned the young nightsabers and thistle boars", giver = "Conservator Ilthalaine",
        "Conservator Ilthalaine kept the balance of nature in the glade, and the glade now held more nightsabers and thistle boars than it could feed. {We} went into the forest and thinned the young ones, and he judged the work well done.",
        "A hard lesson waited in the glade, that keeping nature in balance sometimes meant killing its beasts. {We} thinned the young nightsabers and thistle boars as Conservator Ilthalaine asked."},
    [457] = {act = "went back for the mangy nightsabers and grown boars", giver = "Conservator Ilthalaine",
        "Thinning the young beasts was only a start, Ilthalaine said, and the forest's food would run short unless {we} went further. {We} hunted mangy nightsabers and thistle boars, a necessary evil, and he saw a promising future in {me}.",
        "{We} went back into the forest after the mangy nightsabers and the grown thistle boars, eight of each. Ilthalaine said {we} had proven {our} dedication to nature."},
    [459] = {act = "gathered Fel Moss from the grells for Tarindrella", giver = "Tarindrella",
        "Tarindrella believed something evil was brewing in the forest, for the peaceful furbolgs had left their homes and gathered as the Gnarlpine tribe. {We} fought the grells and grellkin in the hills and found the Fel Moss she feared on them.",
        "{We} brought Tarindrella Fel Moss taken from the grells, proof that the wicked moss had tainted them. If even the grells were tainted, she said, one could only imagine what had become of the Gnarlpine, and she sent {us} on to Athridas Bearmantle in Dolanaar."},
    [4495] = {act = "went looking for Dirania's friend Iverron", giver = "Dirania Silvershine",
        "Dirania Silvershine's friend Iverron visited her at the same time every day, and today he was hours late. {We} went north toward the cave where spiders were everywhere, and found him there.",
        "{We} searched the hills near the spider cave for Iverron, who had not come by Dirania's that day. He was very glad to be found, and wondered how {we} had known where to look."},
    [3519] = {act = "carried word of Iverron's poisoning to Dirania", giver = "Iverron",
        "Iverron had been bitten very badly by a spider named Githyiss the Vile, and he was dizzy with the poison. {We} hurried back to Dirania Silvershine, who had always warned him about those spiders.",
        "Poisoned and dizzy, Iverron begged {us} to tell Dirania Silvershine. {We} ran the word back to her, and she wondered aloud why she had not seen him all day."},
    [3521] = {act = "gathered the ingredients for Iverron's antidote", giver = "Dirania Silvershine",
        "Dirania knew an antidote for Iverron's poison, and {we} gathered what it needed, hyacinth mushrooms, moonpetal lilies from the pools, and ichor from the very spiders that had bitten him. She thanked Elune for {our} speed.",
        "{We} took webwood ichor from the spiders, found mushrooms among the grells and lilies by the water, and brought them all to Dirania. In a moment, she said, the antidote would be ready."},
    [3522] = {act = "rushed Dirania's antidote to Iverron", giver = "Dirania Silvershine",
        "Dirania's antidote would only last five minutes, and {we} ran it to Iverron in time. He drank it and felt much better, and admitted he was always getting into trouble and Dirania always got him out.",
        "{We} raced the fading antidote back to Iverron before it lost its strength. He was recovering, but he meant to sit a while longer, and he hoped {we} would clear a path through the spiders for him."},
    [916] = {act = "gathered webwood venom sacs for Gilshalan Windwalker", giver = "Gilshalan Windwalker",
        "Gilshalan Windwalker believed the World Tree had changed the webwood spiders from their smaller cousins. {We} fought them in and around Shadowthread Cave, dark and full of webs, and brought him their venom sacs.",
        "{We} brought Gilshalan Windwalker the venom of the giant spiders of Shadowthread Cave. He would compare it with other spiders' in Darnassus, sure it would show something of the new tree's growth."},
    [917] = {act = "brought a webwood egg out of the depths of Shadowthread Cave", giver = "Gilshalan Windwalker",
        "A living giant spider was more than Gilshalan could ask of {us}, so he wanted an egg instead. {We} went deep into Shadowthread Cave to the nest and brought one back, and he called {us} a great help.",
        "Deep in Shadowthread Cave {we} found the spiders' nest and took an unhatched egg for Gilshalan. It would go to Darnassus with the venom, and he expected to learn a great deal from it."},
    [920] = {act = "answered Tenaron Stormgrip's summons atop Aldrassil", giver = "Gilshalan Windwalker",
        "Gilshalan told {me} that Tenaron Stormgrip had been asking for {me}, and that it was best not to keep him waiting. {We} climbed to the highest room of Aldrassil, where Tenaron was pleased by {our} promptness.",
        "{We} climbed Aldrassil to its highest room, where Tenaron Stormgrip had sent for {me} by name. He had an important task in mind, and was glad {we} had not kept him waiting."},
    [921] = {act = "brought Tenaron water from the moonwell north of Aldrassil", giver = "Tenaron Stormgrip",
        "Before {I} could set out into the world, Tenaron said, {I} had to learn what had become of {my} people since the Battle of Mount Hyjal. {We} brought him a phial from the moonwell north of Aldrassil, and he spoke of the Well of Eternity.",
        "{We} filled a phial at the moonwell north of Aldrassil, a shrine to Elune whose waters came from the Well of Eternity. Tenaron told {us} how Nordrassil's power had been spent to defeat Archimonde."},
    [928] = {act = "carried Tenaron's vessel of moonwell water to Corithras", giver = "Tenaron Stormgrip",
        "Tenaron poured {our} water into a vessel for Corithras Moonrage and sent {us} out of the glade. {We} followed the cobblestones south and west to the moonwell in Dolanaar, minding the beasts beyond the road.",
        "{We} left the glade with Tenaron's vessel and followed the road to Dolanaar. Corithras Moonrage saw who had sent {us}, and said there was much to do and little time."},
    [2159] = {act = "carried Porthannius's herbs to the inn at Dolanaar", giver = "Porthannius",
        "Porthannius still had business with the druids of the glade, so {we} carried his package of herbs south to Innkeeper Keldamyr in Dolanaar. Keldamyr told {us} to rest, for heroes had to keep their strength.",
        "{We} brought Innkeeper Keldamyr the herbs from the glade, a shame Porthannius could not deliver himself, he said. He bid {us} rest at his inn, for neglecting one's peace was a sure path to failure."},
    [929] = {act = "filled a phial at the moonwell outside Starbreeze Village", giver = "Corithras Moonrage",
        "The druids of Darnassus drew on the water of the moonwells, and {we} filled Corithras's phial at the well outside Starbreeze Village. He told {us} of the years after Hyjal, when the night elves lost their immortality.",
        "{We} brought Corithras water from the moonwell by Starbreeze, and he went on where Tenaron had left off. After Hyjal, he said, the Betrayer had gone free and Shan'do Stormrage had vanished."},
    [997] = {act = "carried a package of rare earth to Denalan's camp", giver = "Syral Bladeleaf",
        "A package of rare earth for Denalan had arrived late in Dolanaar, and {we} carried it to his camp at the eastern end of Lake Al'Ameth. He had waited so long he hoped it was still fresh.",
        "{We} brought Denalan the rare earth he had sent to Darnassus for, to the camp where he studied the plants of the tree. He thanked {us} for being generous with {our} time."},
    [488] = {act = "fetched fangs, feathers and silk for Zenn Foulhoof",
        "A satyr named Zenn Foulhoof promised {us} things {we} had never dreamed of for a few reagents, nightsaber fangs, owl feathers and spider silk. {We} brought them, and he laughed and gave three cheers for the naive and gullible.",
        "{We} did Zenn Foulhoof's bidding in the woods, hunting nightsabers, owls and spiders for his reagents and keeping it a secret, as he asked. When {we} came back he crowed that he had a fledgling to do his work."},
    [475] = {act = "went to Starbreeze to find the warden Gaerolas Talvethren", giver = "Athridas Bearmantle",
        "Athridas Bearmantle felt a troubling breeze, for Gaerolas Talvethren, the Great Warden of the sleeping Druids of the Talon, had sent no word. {We} went east to Starbreeze Village and found the warden there.",
        "{We} went to Starbreeze to find Gaerolas Talvethren for Athridas, who could not rest until he knew his dreaming brethren were safe. Gaerolas thanked the forest spirits {we} had come."},
    [476] = {act = "carried Gaerolas's warning of the Gnarlpine to Athridas", giver = "Gaerolas Talvethren",
        "The Gnarlpine had ambushed Gaerolas and pillaged Starbreeze, driven mad by Ursal the Mauler and the Fel Moss. He was too wounded to go himself, so {we} carried the grave news back to Athridas in Dolanaar.",
        "{We} brought Athridas Bearmantle word that the once peaceful Gnarlpine had turned on the forest's protectors. He called it disturbing indeed, and feared for the sleeping druids of Ban'ethil."},
    [2438] = {act = "recovered Tallonkai's emerald dreamcatcher from Starbreeze", giver = "Tallonkai Swiftroot",
        "Tallonkai Swiftroot had left his emerald dreamcatcher, a gift from the warden Gaerolas, in a dresser in Starbreeze Village. {We} went into the corrupted village among the furbolgs and brought it back to him.",
        "{We} found Tallonkai's dreamcatcher in his old home in Starbreeze, where the furbolgs now ruled. It drew luck from the Emerald Dream, he said, a gift given to very few."},
    [489] = {act = "fed Zenn Foulhoof a handful of fel cones",
        "The Council of the Forest had heard that {I} had helped Zenn Foulhoof, an enemy of the forest, and {I} had to make amends. {We} gathered fel cones that billowed green smoke and gave them to the satyr as a snack.",
        "To win back the council's trust {we} took Zenn Foulhoof a gift of fel cones, corrupted seeds smoking green. He took them gladly, sure {we} had brought him a harmless treat."},
    [4161] = {act = "gathered seven spider legs for Zarrin's lesson", giver = "Zarrin",
        "Zarrin taught {me} that the kaldorei, the children of the stars, took only what nature could spare. {We} gathered seven small spider legs, no more, and he told {me} to remember {my} own part in the balance.",
        "{We} brought Zarrin exactly seven spider legs for his recipe, as the lesson required. Taking no more than needed, he said, was how the night elves kept faith with the living forest."},
    [918] = {act = "gathered timberling seeds around Lake Al'Ameth", giver = "Denalan",
        "Denalan was troubled to see the timberlings, elementals of nature, grown so angry, and blamed the soil. {We} gathered seeds from the timberlings around Lake Al'Ameth, and he planted them in special soil, hoping for gentler creatures.",
        "{We} brought Denalan the timberling seeds he wanted for his prepared soil. He hoped they would sprout into docile timberlings, and thought {we} might see the results later."},
    [919] = {act = "pulled up timberling sprouts around the lake", giver = "Denalan",
        "Small timberlings were sprouting around the lake, and Denalan feared they were beyond help. {We} pulled up every sprout {we} found, and he was alarmed at how many there were.",
        "{We} cleared the timberling sprouts from the shores of Lake Al'Ameth before they could grow into trouble. Denalan thanked {us} for a cleaner land, and hoped to solve the riddle of what tainted them."},
    [487] = {act = "cut down Gnarlpine ambushers on the road to Darnassus", giver = "Moon Priestess Amara",
        "The road from Dolanaar to Darnassus carried news and trade every day, and Gnarlpine furbolgs were ambushing travelers on it. {We} went down into their den and slew six of them, and the Sentinel saluted {us}.",
        "{We} fought the Gnarlpine ambushers below the road to Darnassus, corrupted furbolgs who had once been peaceful. The road was safer for it, and the Sentinels of Teldrassil gave {us} their salute."},
    [932] = {act = "took the head of the satyr Lord Melenas in Fel Rock", giver = "Tallonkai Swiftroot",
        "Tallonkai Swiftroot wanted it kept quiet, for the satyr were an embarrassment to the night elves and this one was too close to home. {We} went into the cave of Fel Rock, past his grell warriors, and brought back the head of Lord Melenas.",
        "{We} found Lord Melenas in Fel Rock, north of Dolanaar, among the grells he had gathered for some foul plot. Tallonkai took his head with relief and could finally turn to other matters."},
    [2459] = {act = "took Tallonkai's emerald back from Ferocitas the Dream Eater", giver = "Tallonkai Swiftroot",
        "The emerald was gone from Tallonkai's dreamcatcher, and Ferocitas the Dream Eater, leader of the Gnarlpine mystics, wore a necklace that glowed green at night. {We} went north of Starbreeze, killed him and his mystics, and brought the jewel home.",
        "{We} hunted Ferocitas the Dream Eater among his mystics for the emerald he had stolen, useless to him though it was. Tallonkai could mend his dreamcatcher at last."},
    [2541] = {act = "took a Gnarlpine charm for the sleeping druid", giver = "Oben Rageclaw",
        "In the Ban'ethil Barrow Den {we} met the spirit of a sleeping druid, trapped in the Emerald Dream while the Gnarlpine shamans used his body against intruders. {We} took a charm from the shamans so he could study their ritual.",
        "{We} brought the trapped druid a charm from the Gnarlpine shamans of the barrow den. He could sense the vile aura on it, and knew it held a very powerful enchantment."},
    [483] = {act = "recovered the Relics of Wakening from the Ban'ethil Barrow Den", giver = "Athridas Bearmantle",
        "Gnarlpine invaders were ravaging the Ban'ethil Barrow Den, and the slumbering druids would never wake without the Relics of Wakening. {We} went down among the sacred chests and brought out all four, just in time, Athridas said.",
        "{We} searched the Ban'ethil Barrow Den for the Raven Claw Talisman, the Black Feather Quill, the Sapphire of Sky and the Rune of Nesting. Athridas could prepare the awakening ritual now."},
    [933] = {act = "fetched water from the moonwell by the Pools of Arlithrien", giver = "Corithras Moonrage",
        "The Gnarlpine were troubling the Sentinels around the moonwell by the Pools of Arlithrien, and {we} went there with weapons close at hand. Corithras told {us} how Fandral Staghelm led the druids to grow Teldrassil after Malfurion vanished.",
        "{We} brought Corithras water from the well southeast of Darnassus, past the crazed furbolgs. With Shan'do Stormrage still missing, he said, Staghelm and the most powerful druids had grown the new World Tree."},
    [2498] = {act = "took Rellian's word back to Denalan at the lake", giver = "Rellian Greenspyre",
        "Rellian Greenspyre had heard that Denalan might have found the cause of the timberlings' tumors, and sent {us} to the lake in haste. Denalan was glad {we} came so soon, for he had discovered something disturbing.",
        "{We} hurried back to Lake Al'Ameth for Rellian, who said Denalan needed help. Denalan met {us} with news of something quite disturbing."},
    [2499] = {act = "killed Oakenscowl and took its great tumor", giver = "Denalan",
        "Oakenscowl had once been a grand leader of the timberlings, and now a gargantuan tumor poisoned it and spread corruption through the lake. {We} hunted it down in its cave on the southern bank and brought the tumor to Denalan.",
        "{We} went into the cave on the lake's southern bank and killed Oakenscowl, poisoned by the largest tumor Denalan had ever seen. Corruption did not care whether its victim was lowly or noble, he said."},
    [930] = {act = "brought a glowing fruit to Denalan",
        "{We} found a glowing plant with a large, round fruit hanging under its fronds, and took it to Denalan. He thought its seeds might have come from far away, even from Azeroth, and that it had reacted strangely with the tree's soil.",
        "Denalan was intrigued by the glowing fruit {we} brought him, something exotic growing where it should not. He excused himself at once to study it further."},
    [931] = {act = "brought a shimmering frond to Denalan",
        "{We} cut a specimen from a plant whose fronds shimmered and pulsed in the forest light, and brought it to Denalan. He had not seen its like since a visit to the Swamp of Sorrows decades before.",
        "Denalan could hardly believe the shimmering frond {we} brought him had made its way to the tree and grown so large. He thanked {us} in few words and hurried off to test it."},
    [2561] = {act = "freed the sleeping druid from the Gnarlpine's spell", giver = "Oben Rageclaw",
        "The only way to free the druid's spirit was to kill his own body, and he regretted asking it of {us}. {We} went to the deepest part of the barrow den, struck down his soulless form, and used the charm on it.",
        "{We} found the druid's body in the depths of the Ban'ethil Barrow Den, enchanted and dangerous, and freed his spirit as he asked. He could rest in peace in the Emerald Dream now, and hoped {we} might meet one day."},
    [6341] = {act = "took Nessa's fish samples to the hippogryph master", giver = "Nessa Shadowsong",
        "Nessa Shadowsong wanted to know why the fish around Rut'theran were so large and so plentiful, and gave {us} her collection of bones and scales for a colleague in Auberdine. {We} took it to Vesprystus, the hippogryph master, for the crossing.",
        "{We} carried Nessa's box of fish bones and scales to the hippogryph master Vesprystus, bound for Laird in Auberdine. It was {our} way off the great tree, toward the mainland."},
    [6343] = {act = "brought Laird's reply back to Nessa in Rut'theran", giver = "Laird",
        "Laird suspected the World Tree itself was changing the wildlife around it, and sent {us} back across the water with his answer. Nessa had not thought the difference so great, and meant to tell the villagers.",
        "{We} crossed back to Rut'theran with Laird's reply for Nessa Shadowsong. Whatever made the island's fish so large, she said, the village would enjoy it until they knew."},
    [937] = {act = "took harpy belts at the Oracle Glade for Arynia Cloudsbreak", giver = "Sentinel Arynia Cloudsbreak",
        "Harpies nesting around the Oracle Glade had killed the Oracle Tree's runner to Darnassus. {We} went among the nests with talons and beaks all around {us}, and Sentinel Arynia Cloudsbreak was impressed by how quickly {we} brought back their belts.",
        "{We} fought the Bloodfeather harpies in their nests around the Oracle Tree, where Arynia's Sentinels were slowly pushing them back. She wished {we} could stay, but saw greater tasks ahead for {us}."},
    [7383] = {act = "fetched water from the moonwell under the Oracle Tree", giver = "Corithras Moonrage",
        "The last moonwell lay in the Oracle Glade, the first and most powerful of them all, under the boughs of the Oracle Tree. {We} brought its water to Corithras, who told {us} that Nozdormu and Alexstrasza had refused Staghelm their blessing.",
        "{We} filled the last phial beneath the Oracle Tree, a place where wisdom almost seemed to take form. Without the dragons' blessing, Corithras said, the tree's growth had been flawed and unpredictable."},
    [486] = {act = "slew Ursal the Mauler in Gnarlpine Hold", giver = "Athridas Bearmantle",
        "The ritual to wake the Druids of the Talon would only work once the beast who meddled with them was dead. {We} went to Gnarlpine Hold in the southwest and slew Ursal the Mauler, and Athridas called {me} worthy and honorable.",
        "{We} fought through Gnarlpine Hold to Ursal the Mauler, the chieftain whose Fel Moss had driven the furbolgs mad. With him dead Athridas could finish his ritual, and he asked the forest spirits to protect {us}."},
    [927] = {act = "brought the beating heart of Blackmoss the Fetid to Denalan",
        "The heart of Blackmoss the Fetid was covered in dark, oily moss, and it was still beating. {We} carried it to Denalan, who was shocked to find a timberling's heart under the foul growth.",
        "{We} brought Denalan a heart that still beat slowly under its moss, taken from Blackmoss the Fetid. He meant to examine it and, with luck, learn what the moss was."},
    [941] = {act = "planted the timberling heart in Denalan's soil", giver = "Denalan",
        "Denalan had scraped the moss from the heart, but it was still tainted, so {we} placed it in his planter of prepared soil. It dug itself in, then wriggled back out a few seconds later, cleansed and pulsing.",
        "{We} set the tainted heart in Denalan's planter and watched it burrow into the nourishing soil. When it came back out it was clean, pulsing slightly as if asking {us} to take it."},
    [938] = {act = "brought the wounded sabercat Mist home to Arynia",
        "{We} found a gray sabercat lying wounded in the forest, deep cuts across her back, who raised her head and wanted to follow {us}. {We} led Mist home to Sentinel Arynia Cloudsbreak, who had feared she would never see her again.",
        "Arynia Cloudsbreak blamed herself for letting the harpy witches take Mist. When {we} brought the wounded sabercat back to her, she gave {us} her eternal gratitude."},
    [2518] = {act = "ended the suffering of Lady Sathrah", giver = "Priestess A'moora",
        "Lady Sathrah had once been beloved of Elune, a spider whose silver threads caught dew that healed, but she had gone mad. {We} found her near Wellspring Lake and ended her suffering, and Priestess A'moora said the forest mourned her.",
        "{We} brought Priestess A'moora the silvery spinnerets of Lady Sathrah, meant as a sacrifice so Elune might let the spider be reborn at peace. It had to be done, A'moora said, but she regretted asking it."},
    [98403] = {act = "struck at Xethorr the Wicked in the Cleft", giver = "Tallonkai Swiftroot",
        "Lord Melenas had not acted alone, Tallonkai said, but at the behest of Xethorr the Wicked, who was twisting the spiders of the tree. {We} went into the Cleft northwest of Dolanaar and destroyed his brood, and brought back what {we} found of his work.",
        "{We} faced Xethorr the Wicked's brood in the Cleft and came back with a sample of the substance he used to twist the spiders. Tallonkai wanted it kept quiet for Dolanaar's sake, and trusted {us} to do the same."},

    -- Westfall (novice into seasoned).
    [184] = {act = "returned the Furlbrows' stolen deed",
        "Among the Defias {we} found the deed to the Furlbrows' farm, with a note on the back boasting how they had leaned on the farmer for it. {We} took it to Theodore and Verna, stranded by the road with a broken wagon, and he had thought it gone for good.",
        "{We} brought Farmer Furlbrow the deed the Defias had stolen from him. The fields were no place for honest folk now, he said, but if things got better the papers would let them claim their land."},
    [36] = {act = "carried Verna Furlbrow's stew recipe to Salma Saldean", giver = "Verna Furlbrow",
        "Verna Furlbrow never thought she would leave her farm, but thieves overran the fields. While her husband fixed the wagon she scribbled down her stew recipe, and {we} carried it past the fork in the road to Salma Saldean.",
        "{We} brought Verna's recipe to Salma Saldean, who would miss her neighbor terribly. Verna was a city girl at heart, Salma said, and Stormwind would suit her fine."},
    [109] = {act = "reported to Gryan Stoutmantle at Sentinel Hill",
        "By then {we} had seen enough fighting that a friend of Gryan Stoutmantle's sent {us} to Sentinel Hill. In the stone tower Stoutmantle told {us} the Stormwind monarchy had abandoned the farmlands, and that his People's Militia would keep them free.",
        "{We} climbed Sentinel Hill to the stone tower where Gryan Stoutmantle led the People's Militia. If the cause interested {us}, he said, he could put {our} skills to use in the name of freedom."},
    [6181] = {act = "carried Quartermaster Lewis's armor order to Thor", giver = "Quartermaster Lewis",
        "The militia got little aid from Stormwind, and its armor was running low, so Quartermaster Lewis wrote to his contact Osric Strang in the city. {We} took the note down the hill to Thor, the gryphon master, who offered {us} a gryphon at once.",
        "{We} carried Lewis's urgent note to Thor at the foot of Sentinel Hill. The gryphon master saw {our} hurry and put {us} on a gryphon bound for Stormwind."},
    [6285] = {act = "flew Osric's crate of armor back to Sentinel Hill", giver = "Dungar Longdrink",
        "Dungar Longdrink taught {us} how the gryphons worked, always flying home to the capital but only to roosts {we} had already seen. {We} flew Osric's crate of armor back to Westfall, and Quartermaster Lewis handed it out at once.",
        "{We} came back over the forest on a gryphon with Osric's crate of armor for Quartermaster Lewis. Now that gryphons were nothing new to {us}, he hoped {we} would come to Sentinel Hill's aid often."},
    [12] = {act = "fought the Defias trappers and smugglers for the militia", giver = "Gryan Stoutmantle",
        "The price of peace was often blood, Gryan Stoutmantle said, and his scout had seen Defias trappers near the Jangolode Mine and the northern farms. {We} slew fifteen trappers and fifteen smugglers, and his scout watched {us} do it.",
        "{We} hunted the Defias trappers and smugglers around the Molsen Farm, Furlbrow's Pumpkin Farm and the Jangolode Mine. Stoutmantle's scout had seen it all, and he judged that {we} had done well so far."},
    [22] = {act = "brought Salma Saldean goretusk livers for her pie", giver = "Salma Saldean",
        "Salma Saldean's onions were peeled, her crust baked and her gravy simmering, and all she lacked was eight goretusk livers. {We} hunted the boars of the fields for them, and she and her husband would feast that night.",
        "{We} brought Salma eight goretusk livers for her famous meat pie. She would not let {us} go hungry either, and paid {us} for the hard work."},
    [64] = {act = "recovered Farmer Furlbrow's wedding pocket watch", giver = "Farmer Furlbrow",
        "The Furlbrows had fled their farm in the night with the fields full of thieves, and Farmer Furlbrow had left his pocket watch in the wardrobe, a wedding gift from Verna's father. {We} went into the farmhouse at the pumpkin field and brought it back.",
        "{We} slipped into the Furlbrow farmhouse, now held by thieves, and found the watch in the wardrobe. They were poor farmers who had lost their land, Furlbrow said, but he gave {us} a token of thanks."},
    [38] = {act = "gathered the makings of Salma's stew", giver = "Salma Saldean",
        "Salma wanted vulture meat, goretusk snouts, murloc eyes and okra for her stew, and {we} gathered them from the fields and the coast. The okra thickened the broth, and she gave {us} the first batch of the day.",
        "{We} hunted vultures, boars and murlocs and picked okra for Salma's stew. When it was done she gave {us} the first bowl, a good meal in a hard land."},
    [13] = {act = "fought the Defias pillagers and looters around Moonbrook", giver = "Gryan Stoutmantle",
        "Defias pillagers were plundering the Gold Coast Quarry, Moonbrook and the Alexston Farmstead, and Gryan Stoutmantle sent {us} to make the Light's presence known. {We} killed fifteen pillagers and fifteen looters, and he counted {us} worthy of the militia.",
        "{We} fought the Defias through the quarry by the shore and the ruins of Moonbrook as the next step of {our} training. Stoutmantle said {our} worth to the People's Militia was proven."},
    [102] = {act = "patrolled the grasslands for gnoll paws", giver = "Captain Danuvin",
        "Captain Danuvin had farmed these plains before the thieves came, and he would not turn his back on the people who stayed. {We} patrolled the grasslands and brought him eight paws from the gnolls who worked with the Deadmines thieves.",
        "{We} hunted the gnolls of the grasslands for Captain Danuvin and brought back their paws. With help like that, he said, the land might be the breadbasket it once was."},
    [143] = {act = "carried Magistrate Solomon's plea to Gryan Stoutmantle", giver = "Magistrate Solomon",
        "The Stormwind Army should have reached Lakeshire long before, and Magistrate Solomon would not watch his people die while he waited. {We} carried his plea for help across the kingdom to Gryan Stoutmantle at Sentinel Hill.",
        "{We} brought Solomon's letter to the leader of the People's Militia, hoping his men could hold Redridge until the king sent reserves. Stoutmantle said the messenger had served his master well."},
    [151] = {act = "gathered oats for Poor Old Blanchy", giver = "Verna Furlbrow",
        "Poor Old Blanchy, the Furlbrows' tired mare, had not been fed since they left the farm, and the broken wagon kept them on the road. {We} gathered oats from the farms to the southwest, steering clear of the machines in the fields.",
        "{We} brought back handfuls of oats for Blanchy, who was on her last legs by the Furlbrows' broken wagon. Verna was grateful, sure the old mare would be happy."},
    [9] = {act = "broke twenty Harvest Watchers in the Saldean fields", giver = "Farmer Saldean",
        "The thieves had driven off all the good farm folk except Farmer Saldean, and now Harvest Watchers had taken over his fields. {We} smashed twenty of them, his and his neighbors', and he paid {us} for honest work.",
        "{We} went out into the fields against the Harvest Watchers, machines that had turned on the farmers they once served. Saldean paid {us}, and wondered if the land might prosper as it had before."},
    [117] = {act = "gathered hops for Grimbooze Thunderbrew",
        "Grimbooze Thunderbrew spoke only in rhyme, and his rhyme said his lager would taste like stew without hops. {We} gathered them for him, and he paid {us} in Thunderbrew Lager, with another rhyme for the trouble.",
        "{We} brought Grimbooze Thunderbrew the hops his lager needed. He praised hops, barley, yeast and malt in rhyme and handed {us} a keg."},
    [153] = {act = "brought red leather bandanas to Scout Galiaan", giver = "Scout Galiaan",
        "Scout Galiaan had followed the shifting Defias front a long time, and tracked its members by their red leather bandanas. {We} took fifteen of them from the gang, and he let {us} pick {our} payment.",
        "{We} brought Scout Galiaan a pile of red leather bandanas from the Defias across the land. He paid {us} as he had promised, glad of the hard work."},
    -- The lighthouse and Captain Sanders.
    [103] = {act = "brought oil from the harvest machines for the lighthouse flame", giver = "Captain Grayson",
        "Old Murk-Eye's murlocs had killed the lighthouse keeper's family, and Captain Grayson now tended the flame alone. {We} took flasks of oil from the harvest machines in the fields, and he told {us} he had died needlessly on that shore.",
        "{We} kept the lighthouse burning for the sailors on the Great Sea, bringing Captain Grayson five flasks of oil. He was a ghost, {we} learned then, bound to see that no one else died as he had."},
    [136] = {act = "found Captain Sanders's footlocker by the rusty anchor",
        "A battered map promised Captain Sanders's treasure to whoever followed his clues, since he was in a watery grave. {We} found the one rusty anchor on the western coast and his footlocker half buried in sand beside it.",
        "{We} dug out Captain Sanders's footlocker on the beach near the shipwrecks. It held only sand and water, until a small crab scurried out with the next clue in its claws."},
    [138] = {act = "followed Sanders's clue to a barrel by the chimney ruins",
        "The crab's clue sent {us} due east, up the bluffs to the road and the old chimney ruins beside it. {We} found a barrel there with the captain's next clue inside.",
        "{We} climbed the bluffs from the shore, following a dead pirate's directions, and found his barrel by a ruined chimney near the road. Another piece of parchment waited in it."},
    [139] = {act = "found the captain's whiskey jug by the lone windmill",
        "From the barrel {we} walked straight north, as the crow flies, to an empty jug beside the lone windmill on the sea bluffs. Deep inside it was another clue, smelling of whiskey.",
        "{We} followed the captain's parchment north to a windmill standing alone above the sea. His old whiskey jug lay beside it, and the end of his trail was near."},
    [140] = {act = "swam west to Captain Sanders's treasure chest",
        "The last clue sent {us} west to the shore and then straight into the water, swimming until the island came into sight. Captain Sanders's chest stood there with rusty hinges, and {we} forced it open and took his booty.",
        "{We} swam out from the coast to a small island at the end of Captain Sanders's trail. The old chest still opened, and the dead pirate's treasure came away with {us}."},
    -- The People's Militia and the Defias Brotherhood.
    [14] = {act = "hunted the Defias in the Dagger Hills", giver = "Gryan Stoutmantle",
        "Some Defias had slipped away into the Dagger Hills in the south, plotting their next move. {We} went after them and slew them, and Gryan Stoutmantle inducted {me} into the People's Militia with the Light's blessing.",
        "{We} cleared the Defias out of the Dagger Hills, the last test Gryan Stoutmantle had set. He had come home from Lordaeron to a grim land, he said, but there was hope for it yet, and he welcomed {me} into the militia."},
    [132] = {act = "carried Wiley the Black's warning to Stoutmantle", giver = "Wiley",
        "Wiley the Black said his words could cost him his life. The Defias were working with gnolls, kobolds and even goblins, and {we} carried his note to Gryan Stoutmantle, who wished he had let the scoundrel rot but called it crucial.",
        "{We} brought Stoutmantle a note from Wiley, a scoundrel he had once spared. The Defias were up to something big, and now the militia had more than rumors to go on."},
    [141] = {act = "brought Mathias Shaw's account of VanCleef to Stoutmantle", giver = "Mathias Shaw",
        "In Stormwind Mathias Shaw told {us} about the Stonemasons' Guild and its master, Edwin VanCleef, who had rebuilt the city after the First War and turned bitter at the king. {We} carried his account to Stoutmantle, who knew the name well.",
        "{We} brought Gryan Stoutmantle the name Edwin VanCleef, from Mathias Shaw's own hand. It unnerved him that so gifted a man could become such a scoundrel, and he wanted more proof."},
    [142] = {act = "took the papers of the Defias messenger", giver = "Gryan Stoutmantle",
        "A Defias messenger rode the roads between Moonbrook, the quarry and the Jangolode Mine. {We} caught him and took what he carried, and it was the firm proof Stoutmantle needed that VanCleef led the Defias.",
        "{We} brought Stoutmantle the Defias messenger's papers, proof that VanCleef was in charge. Meanwhile his men had caught a thief stealing Saldean's wagon, who offered to lead them to the hideout for his life."},
    [155] = {act = "guarded the Defias traitor to the hideout in Moonbrook", giver = "Defias Traitor",
        "The captured thief thought {me} scrawny, but he would take {us} to the Defias hideout if {we} kept him alive. {We} stayed close at his side as the Defias tried to kill him, and he led {us} to Moonbrook and their secret.",
        "{We} watched the back of a Defias traitor all the way to Moonbrook, where the gang's hideout lay. Stoutmantle said VanCleef was as good as his now that they knew where he was hiding."},
    [152] = {act = "cleared the murlocs from the beaches for Captain Grayson", giver = "Captain Grayson",
        "Shipwrecks lined the coast, and sailors who reached the beaches found murlocs waiting. {We} killed tidehunters, warriors, oracles and coastrunners along the shore, and Captain Grayson said {we} had a knack for combat.",
        "{We} fought the murlocs up and down the beaches so castaways could come ashore safely. The coast was safer thanks to {us}, Grayson said, and he saw to {our} reward."},
    [104] = {act = "slew Old Murk-Eye for Captain Grayson", giver = "Captain Grayson",
        "{We} knew the coast well by then, and went looking for Old Murk-Eye, the murloc who had led both raids on the lighthouse. {We} killed him and brought Captain Grayson a scale, and the ghost said the Great Sea would be a little safer that night.",
        "Old Murk-Eye had killed the keeper's family before Grayson's eyes, and the dead captain wanted him slain. {We} found him on the shore and ended him, one life laid to rest, Grayson said, so that many more might be saved."},
    [166] = {act = "killed Edwin VanCleef in the Deadmines",
        "There was one task left, Stoutmantle said, and it saddened him to sentence any man to death. {We} went down into the Deadmines beneath Moonbrook, fought through the Defias to Edwin VanCleef, and brought his head back to Sentinel Hill.",
        "{We} faced Edwin VanCleef in the depths of the Deadmines and ended the man who had built the Defias Brotherhood. Gryan Stoutmantle saluted {us} and called it the beginning of the end for the gang."},

    -- Loch Modan (novice into seasoned).
    [414] = {act = "carried Shimmer Stout to Mountaineer Kadrell", giver = "Mountaineer Wellart Barleybrew",
        "Wellart Barleybrew wanted a fellow mountaineer to try his brother's Shimmer Stout, so {we} carried a cask southeast through the tunnel and along the road into Thelsamar. Mountaineer Kadrell took one taste and swore he could fly.",
        "{We} brought a cask of Shimmer Stout to Mountaineer Kadrell, who patrolled the road through Thelsamar. By Magni's beard, he said, it set his head turning and lightened his limbs."},
    [6387] = {act = "took Brock Stoneseeker's list of mining students to the gryphon master", giver = "Brock Stoneseeker",
        "Brock Stoneseeker's best mining students had earned honorary picks, and his list had to reach Golnir Bouldertoe in Ironforge. {We} took it to Thorgrum Borrelson, the gryphon master, who put {us} on a gryphon for a small fee.",
        "{We} carried Brock's list of honor students to the gryphon master of Thelsamar. Thorgrum Borrelson asked if {we} had had {our} fill of the town so soon, then offered {us} a gryphon to Ironforge."},
    [6392] = {act = "flew the honorary picks back to Brock in Thelsamar", giver = "Gryth Thurden",
        "In Ironforge Gryth Thurden explained that gryphons only flew to roosts {we} had already seen, and Thelsamar was one. {We} flew back with the honorary picks, and Brock paid {our} travel costs.",
        "{We} brought Brock Stoneseeker the picks for his mining students, eager to use them on the ore of the loch. He said he was in {our} debt."},
    [418] = {act = "gathered bear meat, boar casings and spider ichor for Vidra", giver = "Vidra Hearthstove",
        "In Thelsamar you had to work for your meals, Vidra Hearthstove said, fancy adventurer or not. {We} brought her bear meat, boar intestines and spider ichor for her famous blood sausages, and she gave {us} the recipe, telling {us} to eat them fresh.",
        "{We} hunted bears, boars and spiders around the loch for Vidra's blood sausages, the meal that fed the town's children and the diggers from the excavation. She was surprised anyone cared how they were made."},
    [224] = {act = "fought the Stonesplinter troggs for Mountaineer Cobbleflint", giver = "Mountaineer Cobbleflint",
        "With so many of the king's soldiers on remote battlefields, the troggs were tunneling up from every crevice around the loch. {We} killed ten Stonesplinter troggs and ten scouts, and Mountaineer Cobbleflint said {we} had served King Magni well.",
        "{We} answered Mountaineer Cobbleflint's call to defend the loch and went out against the Stonesplinter troggs. He praised {our} courage and sent {us} on to Mountaineer Gravelgaw inside the tower."},
    [267] = {act = "brought Captain Rugelfuss eight trogg stone teeth", giver = "Captain Rugelfuss",
        "The Ironforge Reserve had gone to the Alliance Front, and Captain Rugelfuss's regiment could not leave the gate. {We} carried the fight to the troggs in the hills and brought him eight stone teeth, and he said King Magni himself would be proud.",
        "{We} hunted the troggs lurking in the hills above the gate and came back with their stone teeth. Captain Rugelfuss was impressed, and thanked {us} for defending the dwarven lands."},
    [1578] = {act = "made copper axes and belts for the mountaineers' smith Thorvald", giver = "Tormus Deepforge",
        "The mountaineers were wearing through their gear against the troggs, and Tormus Deepforge sent {me} to make copper axes and chain belts for them. {I} brought them to Thorvald at the southern guard tower, and he shared plans for armor.",
        "Thorvald had no time to chat until he saw the copper axes and chain belts {I} had made. They would be a big help to the troops, he said, and he gave {me} plans of his own.", solo = true},
    [237] = {act = "fought the Stonesplinter skullthumpers and seers", giver = "Mountaineer Gravelgaw",
        "Mountaineer Cobbleflint had good things to say about {me}, and Gravelgaw trusted {us} with the southern hills. {We} killed ten skullthumpers and ten seers to buy time, but the reinforcements he hoped for never came.",
        "{We} kept the pressure on the troggs of the southern hills for Mountaineer Gravelgaw. The Alliance front was a sea of crimson, he told {us} grimly, and he sent {us} to Mountaineer Wallbang."},
    [263] = {act = "slew Stonesplinter shamans and bonesnappers for Mountaineer Wallbang", giver = "Mountaineer Wallbang",
        "The mountaineers had told Wallbang about {me}, and he called {me} Trogg-Slayer and wanted to see if {I} lived up to it. {We} went into the valley and killed ten shamans and ten bonesnappers, and he saluted {us}.",
        "{We} fought the Stonesplinter shamans and bonesnappers while the reserves were at the front and the loch's defenders stood alone. Mountaineer Wallbang said he knew from the first that {we} would make Ironforge proud."},
    [298] = {act = "carried Ironband's progress report to Jern Hornhelm", giver = "Prospector Ironband",
        "Prospector Ironband wanted a progress report sent to Thelsamar with a fresh request for blastpowder. {We} carried it to Jern Hornhelm, who was puzzled, since he had sent plenty of powder weeks before.",
        "{We} brought Jern Hornhelm the report from the excavation, troubles with troggs and a plea for powder. Powder well spent either way, Jern said, but he wanted to know where the last shipment had gone."},
    [436] = {act = "asked Magmar Fellhew why the excavation had slowed", giver = "Jern Hornhelm",
        "Jern Hornhelm had sent Ironband supply after supply, yet the dig had slowed, and he feared something was working against the honest prospector. {We} went around the southern tip of the loch to the excavation, where Magmar Fellhew gave {us} the short answer.",
        "{We} went east to Ironband's Excavation to ask about the slowdown for Jern. Magmar Fellhew said a full report was coming, but for now he could tell {us} plainly that it was the troggs."},
    [302] = {act = "brought Stormpike's approval for new blastpowder to Jern", giver = "Prospector Stormpike",
        "Prospector Stormpike swore by Magni that Ironband would have his powder, and wanted {us} to see the shipment through, since the last one had vanished. {We} went back to Jern Hornhelm, only to hear the porters had already left.",
        "{We} carried Stormpike's order to watch the blastpowder all the way to Ironband. Jern had sent Huldar with the porters Miran and Saean a short while before, so {we} had just missed them."},
    [273] = {act = "caught up with Huldar's porters after a Dark Iron ambush", giver = "Jern Hornhelm",
        "{We} followed the curve of the loch south after Huldar and his porters, and found them just after a Dark Iron ambush. Huldar swore it would take more than that to stop the deliveries, but Saean had been one of their sympathizers all along.",
        "Huldar had worked beside Saean for almost a year and never suspected him. {We} reached the porters on the road around the loch after the Dark Irons struck, and Huldar wondered whether he had missed the signs."},
    [454] = {act = "agreed to guard Miran on his next trip", giver = "Huldar",
        "Huldar would not let Miran haul the rest of the powder alone, not after Saean. {We} offered to escort him, and Miran was glad, since nobody knew what else the Dark Irons had up their sleeves.",
        "{We} found Miran making his last checks before the haul to the excavation. With Saean and his cronies about, he was relieved to have {us} along."},
    [309] = {act = "escorted Miran's powder to Ironband's Excavation", giver = "Miran",
        "{We} walked beside Miran and his barrels of powder through dangerous country to Ironband's Excavation. The prospector thanked the Light for the powder, though he was troubled that the Dark Irons had sympathizers among his own people.",
        "Miran felt a lot better with {us} beside him on the road to the dig. {We} brought the powder safely to Prospector Ironband, who finally had what he needed."},
    [307] = {act = "recovered the Miners' League gear from Silver Stream Mine",
        "The Silver Stream Mine had run dry long ago and become a store for the Miners' League, until kobolds moved in and put their filthy paws on good dwarven tools. {We} went in and brought out the crates before the warriors could tromp in and break things.",
        "{We} delved into the Silver Stream Mine, full of kobolds, for the League's mining gear. The mountaineer could not wait for the order to clear them out, and the thought of their grimy hands turned his stomach."},
    [353] = {act = "delivered Grimand Elmore's axe to Mountaineer Stormpike", giver = "Grimand Elmore",
        "Grimand Elmore in Stormwind had finished an axe for Mountaineer Gringer Stormpike, and {we} carried it all the way north to the northern guard tower. Stormpike could not wait to try it on troggs and kobolds, and paid {us} for the long road.",
        "{We} brought Mountaineer Stormpike his new axe from Stormwind. He had heard the human lands were getting dicey, a fine place to prove {our} worth, he said."},
    [1339] = {act = "answered Mountaineer Stormpike's call for a runner", giver = "Mountaineer Kadrell",
        "Mountaineer Kadrell heard that Stormpike wanted a runner and asked if {I} wanted the job. {We} climbed to the top of the northern guard tower, where Stormpike had a task he could not do on watch, one that would take {us} far from the loch.",
        "{We} went up the northern guard tower to Mountaineer Stormpike, who needed someone to travel for him. It would take {us} far from the loch, he said, the perfect chance for adventure."},
    [385] = {act = "hunted crocolisks on the loch's islands for Marek Ironheart", giver = "Marek Ironheart",
        "Marek Ironheart traded in crocolisk skins, but the beasts had dug in on the islands of the loch and were ferocious. {We} waded out and hunted them, while he told {us} how one had nearly taken his hand.",
        "{We} wrestled the crocolisks of the loch for their skins, teeth like knives just as Marek had said. He called them excellent specimens, good money for quality goods."},
    [2039] = {act = "went looking for Bingles by the loch", giver = "Gnoarn",
        "Gnoarn had lost contact with Bingles, sent over Gnomeregan on reconnaissance a week before, and feared he had blown himself up. {We} searched the shore where he was last seen, and found him alive and offended that Gnoarn doubted him.",
        "{We} found Bingles Blastenheimer on the shore of the loch, crashed but very much alive. He had no time for Gnoarn's worries, for the whole movement needed {our} help."},
    [2038] = {act = "took back Bingles' tools and explosives from the troggs", giver = "Bingles Blastenheimer",
        "Bingles had crashed into the loch, and troggs from the nearby island had stolen his tools and his Blastenheimer Blastencapper explosives. {We} took them back, and he promised the troggs of Gnomeregan a gnomish air assault.",
        "{We} went out to the trogg island for Bingles' stolen tools and explosives. Without them, he said, the movement had no chance, and he shouted for Gnomeregan when {we} returned."},
    [257] = {act = "met Daryl the Bold's buzzard challenge", giver = "Daryl",
        "Daryl the Bold looked {me} over and set a challenge he was sure {I} would fail, buzzards in fifteen minutes. {We} brought them down in time, and he grumbled that any boy with a bow could do it, but he kept his word.",
        "{We} shot down the buzzards of the loch against Daryl's clock, while he talked of his own greatness. Never let it be said, he admitted, that Daryl the Bold would not hold to his word."},
    [217] = {act = "slew Grawmug and his guards Gnasher and Brawler", giver = "Captain Rugelfuss",
        "The scouts had found the chieftain behind the trogg incursion, Grawmug, who never left the side of his guards Gnasher and Brawler. Captain Rugelfuss asked {us} to lead the strike, and {we} killed all three in Stonesplinter Valley.",
        "{We} went into Stonesplinter Valley after Grawmug and his two thugs and came back with the trogg leaders dead. Captain Rugelfuss said {we} had brought hope to the loch, and a better chance of driving the troggs back underground."},
    [258] = {act = "took down Daryl's elder boars against the clock", giver = "Daryl",
        "Daryl swore his boar hunt was no Coldridge Valley outing and gave {me} twelve minutes, already telling how he got his famous scar. {We} came back with the boars dead, and he suddenly could not remember any bet.",
        "{We} hunted the elder mountain boars for Daryl the Bold's second test while he got {my} name wrong. He was not surprised at all, he said, and asked what bet."},
    [250] = {act = "found a barrel near the dam's eastern ramp", giver = "Chief Engineer Hinderweir",
        "The Thandol Span had fallen and Dun Modr had been pillaged, and Chief Engineer Hinderweir had no doubt his dam was next. Most of his guards had gone to the Alliance Front, so {we} searched the eastern ramp where Dark Iron sappers had been seen.",
        "{We} went to the eastern ramp of the Stonewrought Dam, where Hinderweir had spotted Dark Iron sappers milling about. Among their things was a suspicious barrel, full of a strange powder."},
    [199] = {act = "took a sample of the strange powder to Hinderweir", giver = "Chief Engineer Hinderweir",
        "{We} took a sample of the strange smelling powder from the sappers' barrel and carried it back to Chief Engineer Hinderweir. He called it an alarming discovery, to say the least.",
        "The powder in the Dark Iron barrel smelled wrong, and {we} brought a handful back to the dam. Hinderweir was alarmed by what {we} had found."},
    [274] = {act = "brought Ashlan Stonesmirk's disarming colloid to the dam", giver = "Ashlan Stonesmirk",
        "Ashlan Stonesmirk knew the silver crystals and the smell at once, Seaforium, harmless dry but able to blow Ironforge out of the mountain once wet. {We} carried his disarming colloid back to Hinderweir, and the engineer called on the heavens.",
        "{We} learned from Ashlan Stonesmirk what the Dark Irons meant for the dam, and what it would take to stop it. {We} hurried his colloid and his list of ingredients back to Hinderweir."},
    [278] = {act = "gathered lurker venom, a crocolisk tear and a Mo'Grosh crystal", giver = "Chief Engineer Hinderweir",
        "Hinderweir's mixture needed lurker venom from the spiders, a crocolisk tear from the loch, and a Mo'Grosh crystal the ogres rarely let go. {We} gathered all three, just in time, he said.",
        "{We} hunted spiders and crocolisks and took a rare crystal from the Mo'Grosh ogres for the disarming mixture. Hinderweir had what he needed, with time running short."},
    [280] = {act = "stirred the disarming mixture into the Seaforium keg", giver = "Chief Engineer Hinderweir",
        "Dark Iron insurgents had swum a keg to the base of the dam while no mountaineers were there to stop them. {We} took Hinderweir's mixture down, twisted the keg open and stirred it in, and it fizzled as it settled.",
        "{We} found the Dark Iron keg at the foot of the dam and poured in the mixture before it could blow. It fizzled slightly, and {we} breathed out."},
    [283] = {act = "told Hinderweir the dam was safe", giver = "Chief Engineer Hinderweir",
        "With the keg fizzling quietly behind {us}, {we} went back up to Chief Engineer Hinderweir. He said {we} had saved the Stonewrought Dam and made the kingdom and the Alliance proud.",
        "{We} brought Hinderweir word that the Seaforium was disarmed. The dam was safe, he said, for the time being at least, and the Dark Iron terrorists had failed."},
    [297] = {act = "took the carved idols from the troggs at the dig", giver = "Magmar Fellhew",
        "Just before the troggs drove them from the ruins, Magmar Fellhew's diggers had found strange carved idols that drove the troggs berserk. {We} took eight of them back from the frenzied troggs, and he said he would keep his eye on {us}.",
        "{We} fought berserk troggs at the excavation for the idols they carried. Magmar was surprised {we} did not look worse for wear, and saw promise in {us}."},
    [255] = {act = "fought the ogres northeast of the loch for Magistrate Bluntnose", giver = "Magistrate Bluntnose",
        "Ironforge had promised Thelsamar a handful of soldiers, months away, and Magistrate Bluntnose needed hired arms now. {We} went to the ogre camp northeast of the loch and broke its strength, and he thanked {us} on behalf of the whole town.",
        "{We} took up the magistrate's offer and fought the ogres camped on the far side of the loch. With them dealt with, Bluntnose hoped to turn to the troggs at last."},
    [468] = {act = "joined Mountaineer Rockgar at Dun Algaz", giver = "Mountaineer Kadrell",
        "Mountaineer Rockgar wanted volunteers for a mission into the Wetlands, and {we} took the road north past the guard tower to Dun Algaz. He hoped {our} gear was sound, because his scouting mission had become something messier.",
        "{We} went up to Dun Algaz to join Mountaineer Rockgar's scouts, ready to get {our} boots wet in the soggy country to the north. He welcomed {us}, but warned that scouting was no longer the word for it."},
    [256] = {act = "brought Magistrate Bluntnose the head of Chok'sul",
        "The magistrate's wanted poster named Chok'sul, the ogre behind the attacks on the town, the dam and the excavation. {We} found him at the ogre camp northeast of the loch, and Bluntnose recoiled at the head before he paid the bounty.",
        "{We} went back to the ogre camp for Chok'sul himself and brought his head to Thelsamar. Light burn him, the magistrate said, it was quite a catch, and the town thanked {us}."},

    -- Darkshore (novice into seasoned).
    [6342] = {act = "flew Nessa's fish samples to Laird in Auberdine", giver = "Vesprystus",
        "Vesprystus advised {us} to fly rather than take the ferry, since a hippogryph master once met would always carry {us} back. {We} flew across the water to Auberdine, and Laird found a jawbone in Nessa's box nearly twice the size of his own fish.",
        "{We} brought Nessa's collection to Laird, the fish vendor of Auberdine, carried over the water on a hippogryph's back. He marveled at scales as big as a closed fist."},
    [953] = {act = "read the tablets of fallen Ameth'Aran", giver = "Sentinel Tysha Moonblade",
        "Sentinel Tysha Moonblade had found two tablets in the ruins of Ameth'Aran but fled from its Highborne spirits before she could read them. {We} went among the restless dead and read how the city had fallen, and she could finish her report to the Circle of Ancients.",
        "{We} deciphered the tablets of Ameth'Aran, a city where Azshara's servants once worked their magic freely. Tysha had few accounts from the War of the Ancients, and was grateful for this one."},
    [954] = {act = "found the spectral prisoner of Bashal'Aran's shrine", giver = "Thundris Windweaver",
        "Thundris Windweaver had noticed a shrine in Bashal'Aran that the satyrs and grells would not approach, wrapped in a strange blue aura. {We} climbed the bluff to it and found a ghost there, sharp of tongue and glad of civil company after decades.",
        "{We} went into the ruins of Bashal'Aran, overrun with demonic minions, to the shrine they avoided. A spectral night elf greeted {us} with irony, saying even {our} company was an improvement on the grells."},
    [955] = {act = "gathered earrings from the grells of Bashal'Aran", giver = "Asterion",
        "The ghost of the shrine was bound by a seal, and he thought the earrings of the grells and sprites might hold a trace of it. {We} gathered them, and his spell showed the grells had touched the seal recently, by {our} reckoning if not his.",
        "{We} took the earpieces of the grells and sprites for the shrine's prisoner, who had thought for centuries about the freedom the seal's destruction would bring. They did not have it, but they had been near it."},
    [956] = {act = "took the Ancient Moonstone Seal from the satyrs", giver = "Asterion",
        "If the grells had touched the seal, the satyrs who led them must hold it. {We} hunted the satyrs of Bashal'Aran and found it, and the prisoner could hardly believe he held the thing that had bound him so long.",
        "{We} brought the ghost of Bashal'Aran the seal of his prison, taken from a satyr. For a thousand years he had stared at the pillars around him, and now he urged {us} to waste no time."},
    [957] = {act = "burned the moonstone seal in Ameth'Aran's blue flame", giver = "Asterion",
        "Only the ancient blue flame in Ameth'Aran, the twin of his ruins, could destroy the seal. {We} carried it south and cast it in, and the prisoner was free to see a world that had changed since Azshara held court.",
        "{We} destroyed the seal in Ameth'Aran's blue flame and set the ghost of Bashal'Aran free. He sensed that his jailor and former master, Athrikus, still lived, and his hopelessness was turning to thoughts of vengeance."},
    [958] = {act = "took the Highborne spirits' magical implements",
        "The spirits of the Highborne in Ameth'Aran still wielded their ancient implements, and the Sentinels wanted them destroyed. {We} took them from the restless dead, and the night elf who asked meant to have them destroyed so their evil could never wake.",
        "{We} brought back the magical tools of Ameth'Aran's Highborne, relics of the magic that had once ruined the world. They would be destroyed, so the horrors of the past would not come back."},
    [1001] = {act = "fed thresher eyes to Buzzbox 411",
        "A tiny voice crackled out of a machine on the beach, a gnome named Wizbang who hiccuped between his words. Buzzbox 411 needed thresher eyes, so {we} hunted the threshers just off the coast and put three in the hatch.",
        "{We} fixed Buzzbox 411 on the beach north of Auberdine with three thresher eyes. Wizbang was busy praising crawler wine, and seemed surprised to find it fixed so fast."},
    [1579] = {act = "fished up Wizbang's lost gaffer jacks", giver = "Wizbang Cranktoggle",
        "Wizbang Cranktoggle had come to Auberdine for quiet after the noise of Ironforge, drunk too much on the voyage and dropped his gaffer jacks overboard. {We} fished the sea for them, and he called {us} the luckiest adventurers in Kalimdor.",
        "{We} fished up a box of gaffer jacks from somewhere off the coast, without which Wizbang could not tune his stintle pegs. He could not believe {our} luck."},
    [1580] = {act = "fished Wizbang's electropellers out of the streams", giver = "Wizbang Cranktoggle",
        "Wizbang had tested an exploding duck decoy while tipsy and woken in Auberdine with his hair singed and his electropellers gone. {We} fished the lakes and streams of the coast for them, and he named {us} the best fishermen he had ever seen.",
        "{We} found Wizbang's electropellers in the water, and his research into duck decoys could go on. He gave {us} fishing gear, though he was sure {we} hardly needed it."},
    [2178] = {act = "hunted strider meat for Alanndarian's stew", giver = "Alanndarian Nightsong",
        "Alanndarian Nightsong would teach her secret strider stew only to those who could handle the beasts. {We} hunted the foreststriders of the coast and filled her empty pot with their meat, and she let {us} taste it.",
        "{We} brought Alanndarian a load of strider meat, and the delicious aroma of her stew filled the camp. She shared her recipe and asked what {we} thought."},
    [3524] = {act = "took bones from a beached creature for Gwennyth", giver = "Gwennyth Bly'Leggonde",
        "Sea creatures were beaching themselves on the coast in growing numbers, and Gwennyth Bly'Leggonde had come from the Temple of the Moon to find out why. {We} drove off the Greymist murlocs around the giant south of Auberdine and brought back its bones.",
        "{We} fought the murlocs ringing a great beached creature south of town and took bones for Gwennyth's study. She feared the strandings were an ill omen, and the temple paid {us} for the help."},
    [4722] = {act = "took a sample from a beached sea turtle",
        "{We} found a sea turtle that had beached itself long ago, scavenged by the murlocs camped around it. Enough remained for a sample, and Gwennyth Bly'Leggonde sent it on to Darnassus with an honorarium for {us}.",
        "Murlocs had picked at the beached sea turtle, but {we} took what samples were left back to Gwennyth in Auberdine. Another discovery for the temple, she said."},
    [4723] = {act = "took a sample from the giant thresher at the Mist's Edge",
        "A giant thresher lay on the shore at the Mist's Edge, far larger than any thresher of these waters, with murlocs feasting on it who could never have brought it down. {We} took a sample, and Gwennyth hoped one day to save these creatures.",
        "{We} brought Gwennyth a piece of the great thresher stranded at the Mist's Edge, though no one knew how it got there. She paid {us} and sent it on for study."},
    [730] = {act = "went to Auberdine to look for Greywhisker's crew", giver = "Chief Archaeologist Greywhisker",
        "Chief Archaeologist Greywhisker in Darnassus had heard nothing from his crew in weeks, and spoke of a great power, found in Khaz Modan, that threatened all of Azeroth. {We} crossed to Auberdine and found his archaeologist Hollee, relieved that help had come.",
        "{We} took Greywhisker's worry across the sea to Auberdine, where Archaeologist Hollee was glad he had sent for help. Her crew needed it."},
    [984] = {act = "scouted a furbolg camp for signs of corruption", giver = "Terenthis",
        "Terenthis had vowed to stop the furbolg corruption after his brethren were rescued from it on Teldrassil. {We} found a camp south of Auberdine, and the signs were there, terrible news, he said.",
        "{We} scouted the Blackwood furbolgs near Auberdine for Terenthis and found them corrupted. With the furbolgs this close, he said, the town would have to prepare."},
    [985] = {act = "fought the Blackwood pathfinders and windtalkers", giver = "Terenthis",
        "Terenthis asked whether {we} could fight the furbolgs as well as scout them. {We} went into the Blackwood camp and killed eight pathfinders and five windtalkers, and he told {us} to wash the blood away and not mourn it.",
        "{We} struck the Blackwood camp south of Auberdine, the greatest threat to the town. Terenthis gave thanks, though the fel moss still endangered the whole coast."},
    [1002] = {act = "fed moonstalker fangs to Buzzbox 323",
        "Wizbang's voice slurred out of Buzzbox 411 with directions to the next one, near a bridge north of town. {We} hunted moonstalkers for six fangs, and the machine ground them to dust.",
        "{We} found Buzzbox 323 by the bridge and fed it six moonstalker fangs while Wizbang mumbled about ale. He offered {us} another job before {we} could leave."},
    [1141] = {act = "caught Darkshore grouper for Gubber Blump", giver = "Gubber Blump",
        "Gubber Blump fished, and his family was known for fishing, but the murlocs kept the boats ashore. {We} caught him the Darkshore grouper he liked, and he judged {us} as good as his cousin Graun and gave {us} a Blump Family Fishing Pole.",
        "{We} fished the coast for Darkshore grouper for Gubber Blump, who thought catching them more fun than eating them. He reckoned {we} had what it took to use his family's pole."},
    [2118] = {act = "brought a rabid thistle bear back to Tharnariun alive", giver = "Tharnariun Treetender",
        "A sickness gripped the thistle bears, and Tharnariun Treetender hoped he had a cure. {We} laid his trap in the forest until a rabid bear crossed its light and grew docile, and led it back to him alive.",
        "{We} brought a sick thistle bear back to Tharnariun, calmed for a while by his trap. His work had only just begun, he said, and he asked whether {we} could take on the next task."},
    [4681] = {act = "searched a sunken creature west of Auberdine", giver = "Gwennyth Bly'Leggonde",
        "The first beached creature was not the only one, and Gwennyth sent {us} into the water west of Auberdine, near a sunken ship. {We} brought back what {we} found, and she began to wonder if the creatures were fleeing the waters around Teldrassil.",
        "{We} swam out to the dead creature by the sunken vessel west of town for Gwennyth. With it she could file a proper report, though she said the research was only in its infancy."},
    [4728] = {act = "took a sample from the sea mammal the Explorers' League abandoned",
        "A giant sea mammal lay half gutted on the beach, a wheelbarrow and tools left beside it as if someone had begun to study it. {We} took a sample past the murlocs, and Gwennyth said the Explorers' League had been chased off it.",
        "{We} succeeded where both the Explorers' League and Gwennyth had failed, and brought her a sample from the great beached mammal. She paid {us} on behalf of the Temple of the Moon."},
    [4811] = {act = "found the red crystal in the eastern mountains", giver = "Sentinel Glynda Nal'Shea",
        "Hostile moonkin were gathering in the east, drawn by reports of a large red crystal that nobody was sure existed. {We} climbed into the eastern mountains and found it, and Sentinel Glynda Nal'Shea was fascinated and full of questions.",
        "{We} found the red crystal where the moonkin gathered along the eastern mountains. It was real, {we} told Glynda, and she wondered whether it was benign or something more sinister."},
    [4812] = {act = "poured moonwell water over the red crystal", giver = "Sentinel Glynda Nal'Shea",
        "Glynda gave {us} a vial to fill at Auberdine's moonwell, warning that the crystal might be tied to Felwood above. {We} carried the water back to it and poured it over the top, and its clouded surface turned clear.",
        "{We} went back to the humming red crystal and poured moonwell water down its lattices. As it ran, the opaque surface turned transparent before {our} eyes."},
    [4813] = {act = "reported the bones inside the red crystal to Glynda", giver = "Sentinel Glynda Nal'Shea",
        "Inside the cleared crystal {we} saw small fragments of bone and half a jaw that looked humanoid, sealed where no magic could easily reach. {We} took word back to Glynda, who said every answer only raised more questions.",
        "{We} reported the bones inside the red crystal to Sentinel Glynda Nal'Shea. She would take it to the council of Auberdine, and thought the threat far enough east for now."},
    [4725] = {act = "found a naga box on a beached sea turtle",
        "This sea turtle had an abandoned carriage strapped to its shell, as if something had driven it ashore. {We} took the box with strange markings from the carriage, and Gwennyth said the carriages and the markings were naga work.",
        "{We} brought Gwennyth a marked box from a carriage on a dead turtle's back. It explained the naga in the far north of the coast, she said, and she sent it to Darnassus."},
    [4727] = {act = "took a sample from a turtle the murlocs avoided",
        "{We} found the bones of a sea turtle on the northern beaches with no murlocs near them, whether they had not found it or shied away. {We} took a sample for Gwennyth, who noted the oddity.",
        "The northern beaches held another dead sea turtle, strangely left alone by the murlocs. {We} brought its bones to Gwennyth, and the temple paid {us} for {our} time."},
    [4761] = {act = "brought the furbolg news to Thundris Windweaver", giver = "Terenthis",
        "Terenthis sent {us} to share what {we} had seen of the furbolgs with Thundris Windweaver, the elder of Auberdine. Thundris welcomed {us}, for the forest's people and the forest itself were turning hostile.",
        "{We} told Thundris Windweaver what {we} had found among the furbolgs, news that came at a fortunate time. He had ideas of his own about their corruption, and hoped {we} could help."},
    [4762] = {act = "drew a sample of the fouled Cliffspring River", giver = "Thundris Windweaver",
        "The Cliffspring River was turning foul, and Thundris feared it would reach Auberdine. {We} went inland from its mouth to the first waterfall under the bridge and filled his tube, and the water was putrid.",
        "{We} brought Thundris a sample from the pool below the falls, and it was turning putrid. The true source, he said, was Felwood to the east, a corruption he had seen before."},
    [5713] = {act = "defended Sentinel Aynasha from Marosh the Devious", giver = "Sentinel Aynasha",
        "Sentinel Aynasha had been poisoned by the furbolg Marosh and his trackers, barely able to stand, and needed time to mix her antidote. {We} stood over her while she helped with her bow, and she lived to carry her message on.",
        "{We} defended a poisoned Sentinel on the road until her antidote was ready, then took word to Onaeya at Maestra's Post. Onaeya asked Elune to watch over {us}."},
    [963] = {act = "freed the spirit of Anaya Dawnrunner in Ameth'Aran", giver = "Cerellean Whiteclaw",
        "Cerellean Whiteclaw had lost his love Anaya when Ameth'Aran fell, thousands of years before, and had found her haunted spirit in the ruins. He could not raise his hand against her, so {we} did it for him, and he asked to be left alone with his grief.",
        "{We} went into Ameth'Aran and freed Anaya's spirit, as Cerellean begged but could not bear to do. He wondered if he should have done it himself, then turned away to mourn."},
    [1003] = {act = "fed grizzled thistle bear scalps to Buzzbox 525",
        "Wizbang sang drunkenly about thistle bear beer from inside Buzzbox 525, hidden in some bushes by a fence far down the road. {We} brought it four grizzled scalps, and he confessed his machines brewed liquor as well as carrying messages.",
        "{We} found the last Buzzbox south of town and fed it the scalps of grizzled thistle bears. Wizbang admitted the night elves did not care for his liquor trade, and left {us} something special inside."},
    [2138] = {act = "put down twenty rabid thistle bears", giver = "Tharnariun Treetender",
        "Tharnariun's cure had failed, and it saddened him to order the death of nature's beasts. {We} went into the forest and put down twenty rabid thistle bears, which would slow the plague's damage but not end it.",
        "{We} culled the sick thistle bears of the coast for Tharnariun, grim work that bought the forest a little time. He told {us} to rest, and to prepare {our} minds for more bloodshed."},
    [4730] = {act = "took bones from a half-devoured sea mammal",
        "Stronger murlocs than any near Auberdine had made their home around a half-eaten sea mammal on the beach. {We} fought them for its bones, and Gwennyth said these gentle creatures lived around Teldrassil and had never been known to beach themselves.",
        "{We} brought Gwennyth bones from a gentle sea mammal that had died on the shore. Why such creatures would do this, she wondered, and hoped their remains might tell her."},
    -- The Twilight's Hammer and the Grove of the Ancients.
    [947] = {act = "gathered mushrooms behind Cliffspring Falls and scouted the cave", giver = "Barithras Moonshade",
        "Barithras Moonshade needed rare mushrooms from the cave behind Cliffspring Falls, but the Ancients had warned him a new evil hid there. {We} went in, gathered the mushrooms, and saw enough to prove the Ancients right.",
        "{We} brought Barithras fine mushrooms from the cave behind the falls, and word that the Ancients' fears were true. He had hoped, this time, that they were wrong."},
    [948] = {act = "went to Onu at the Grove of the Ancients", giver = "Barithras Moonshade",
        "Onu, an Ancient of Lore, knew of {our} visit to the falls and wished to speak with {us}, and Barithras feared it was urgent. {We} went south to the grove, where the ancient said there were matters to discuss.",
        "{We} walked south to the Grove of the Ancients, where Onu waited among the trees. He had been expecting {us}."},
    [952] = {act = "carried Fandral Staghelm's message to Onu", giver = "Arch Druid Fandral Staghelm",
        "Arch Druid Fandral Staghelm pressed {us} into service with a message for Onu, the Ancient of Lore in Darkshore. {We} flew across and found the ancient, who thought the Arch Druid always seemed in such a hurry.",
        "{We} brought the Arch Druid's message to Onu in the Grove of the Ancients. All would come in its appointed time, the ancient said, as Shan'do Stormrage had understood."},
    [944] = {act = "searched the Master's Glaive and scried for Onu", giver = "Onu",
        "The naga in Darkshore were strange, Onu said, but the Twilight's Hammer stranger, a cult that worshiped old lords of the earth. {We} went to the Master's Glaive, where one such lord had fallen, found cultists there, and spoke to Onu through a scrying bowl.",
        "{We} searched the Master's Glaive in the south and called Onu through his bowl to tell him the Twilight's Hammer was there. The old lord was long dead, he said, but slivers of his power remained."},
    [949] = {act = "found the Twilight Tome in the cult's camp", giver = "Onu",
        "Onu needed to learn the Twilight's Hammer's intentions before he could plan, so {we} searched their camp at the Glaive. Among their things lay a tome hand printed in an ancient language and illustrated by a master's hand.",
        "{We} went through the cultists' camp at the Master's Glaive for anything that showed their purpose. What {we} found was an old tome, beautifully made and in a tongue {we} could not read."},
    [950] = {act = "tore a page from the Twilight Tome for Onu", giver = "Onu",
        "The text of the Twilight Tome swam and danced, and its scrollwork twisted into grotesque shapes. {I} tore out a single sheet before a swoon took {me}, and Onu sensed the work of the old ones in it.",
        "{We} brought Onu one sheet of insane scribbles from the Twilight Tome, all that could be taken before the madness of it overcame {us}. A chaotic, primal magic surrounded it, he said."},
    [951] = {act = "searched the ruins of Mathystra for relics", giver = "Onu",
        "The torn sheet came from an elven text, and the Twilight's Hammer seemed to be using ancient elven magic to bring their masters back. {We} searched the grass and broken stones of Mathystra in the northeast for relics, and Onu urged {us} to be vigilant.",
        "{We} brought Onu relics from the ruins of Mathystra, from a time when that bastion of the elves still shone. Shards of its magic remained, and he hoped to unlock them before the cult did."},
    [982] = {act = "recovered the sunken captains' lockboxes",
        "The Silver Dawning and the Mist Veil had sunk off the coast after the murlocs struck, and neither captain made it out. {We} dove to the wrecks and brought up their lockboxes, a great service to Auberdine, the crew said.",
        "{We} swam down to two wrecked ships north of Auberdine and recovered the captains' logs and effects. The crews could tend to them now, and perhaps put their captains' spirits to rest."},
    [1138] = {act = "gathered crab chunks for Gubber Blump", giver = "Gubber Blump",
        "Gubber Blump loved crab and listed every way to cook it, twice. {We} picked fine crab chunks from the reef crawlers for him, and he gave {us} something he had fished up long ago that made no good crab dishes.",
        "{We} brought Gubber a pile of crab chunks from the tide crawlers while he recited his crab dishes again. He asked if he had told {us} all about crabs."},
    [945] = {act = "led Therylune out of the Master's Glaive", giver = "Therylune",
        "Therylune, a dryad, had wandered into the Master's Glaive and hidden from the cultists who surrounded her. {We} led her out and carried word to her sister Therysil at the Shrine of Aessina, far to the south.",
        "{We} got Therylune away from the cultists of the Master's Glaive and brought word south to Therysil that she was safe. That was a long way to wander, her sister said, to such an unwholesome place."},
    [965] = {act = "found Balthule Shadowstrike watching the Tower of Althalaxx", giver = "Elissa Starbreeze",
        "Elissa Starbreeze had sent Balthule Shadowstrike to watch the Tower of Althalaxx, and he was overdue. {We} went northeast and found him well, with troubling news and no way to send it.",
        "{We} found Balthule Shadowstrike keeping watch on the tower northeast of Auberdine. He was glad {we} had come, for he had news for Elissa he could not leave his post to bring."},
    [966] = {act = "took scraps of parchment from the Dark Strand warlocks", giver = "Balthule Shadowstrike",
        "Warlocks had taken up residence around the Tower of Althalaxx, and Balthule needed more of their parchment to piece them together. {We} took the scraps from the fanatics outside, keeping clear of the deadlier ones within, and he named them the Cult of the Dark Strand.",
        "{We} brought Balthule the warlocks' scrolls, and they gave him a name, the Cult of the Dark Strand, though nothing of its plans. Delgren had to be warned at once."},
    [2139] = {act = "slew the Den Mother near Bashal'Aran", giver = "Tharnariun Treetender",
        "Tharnariun had one last task, and it meant killing again. {We} went to the cave near Bashal'Aran and slew the Den Mother, and he said many hid or fled in such times, but {we} had fought for Auberdine.",
        "{We} ended the Den Mother in her cave northeast of town, the last of Tharnariun's grim work. He hoped one day to fight beside {us} as comrades against another foe."},
    [4740] = {act = "claimed the bounty on Murkdeep",
        "The council of Auberdine wanted Murkdeep dead, the murloc blamed for a Sentinel's death and two sunken cargo ships. {We} found him guarding the huts south of town and killed him, and Sentinel Glynda Nal'Shea called {us} the town's executioners of justice.",
        "{We} brought Glynda proof that Murkdeep was dead. The people of Auberdine would sleep more soundly that night, she said, and named {us} heroes of the town."},
    [4763] = {act = "drew out and slew the satyr corrupting the Blackwood", giver = "Thundris Windweaver",
        "The satyrs held the Blackwood furbolgs through their talismans, and Thundris had a plan to lure one out. {We} mixed the furbolgs' food with moonwell water by their bonfire, and when the satyr came {we} killed it and took its talisman.",
        "{We} cleansed the furbolgs' food at their northern camp and slew the satyr corruptor who came to see why. Thundris called it a battle won in a long war, and hoped the lesson might one day free the Blackwood."},
    [4731] = {act = "found a second naga box on a beached turtle",
        "Another sea turtle lay beached with a carriage half buckled to its shell, guarded by powerful murlocs. {We} took the marked box from it, and Gwennyth said it was naga again, perhaps killed while heading south toward Ashenvale.",
        "{We} brought Gwennyth a second naga box from a dead turtle's carriage. She sent it to Darnassus with the rest of {our} finds."},
    [4732] = {act = "took a sample from a picked-clean sea turtle",
        "The Greymist murlocs had picked this sea turtle nearly clean, but {we} took what was left for Gwennyth. Sea turtles had once played around the base of Nordrassil, she said, and grew fewer since Teldrassil was born.",
        "{We} brought one more sea turtle's remains to Gwennyth, and she thanked {us} for the help. Perhaps it would unlock the mystery of why they came here to die."},
    [4733] = {act = "took a sample from the colossal thresher on the Twilight Shore",
        "On the rocky Twilight Shore lay a thresher several times larger than any in these waters. {We} took a sample, and Gwennyth found its size mind-boggling and wondered whether the dwindling threshers near Teldrassil were part of it.",
        "{We} brought Gwennyth bones from a thresher too large to belong to the coast. Even the eldest here grew to a fraction of that size, she said."},
    -- Remtravel, Volcor and the Tower.
    [729] = {act = "found Prospector Remtravel at his overrun dig", giver = "Archaeologist Hollee",
        "Golems had sprung from the ground and overrun Prospector Remtravel's dig, and he had never seemed to notice. {We} went south and found him asking for his stone brush, his fossil and Hollee, though nobody there was Hollee.",
        "Hollee had run to Auberdine for help, worried for the oblivious Prospector Remtravel. {We} found him at the dig among the golems, cheerful, confused, and glad of any help."},
    [731] = {act = "guarded Remtravel's search for the mysterious fossil", giver = "Prospector Remtravel",
        "Remtravel would not leave without his mysterious fossil, or perhaps his brush, for the Explorers' League. {We} guarded him through the golems while he searched, and Hollee thanked the stars he was safe.",
        "{We} kept Prospector Remtravel alive at his dig, though he kept mixing up his fossil and his brush. Hollee could not believe he had insisted on staying among those creatures."},
    [986] = {act = "hunted fine moonstalker pelts for Terenthis's cloak", giver = "Terenthis",
        "Grimclaw's master Volcor was missing, and Terenthis could make a cloak to let {us} pass Darkshore's creatures unseen. {We} hunted moonstalker sires and matriarchs near Wildbend River for five fine pelts, and he set to work.",
        "{We} brought Terenthis the pelts he needed for an enchanted cloak, so {we} could search for Volcor. He warned that doing much more than speaking would break its illusion."},
    [993] = {act = "found the wounded scout Volcor in his cave", giver = "Terenthis",
        "With Terenthis's moonstalker cloak around {us}, {we} found Grimclaw by the road, and he showed the way to his master's cave. Volcor was there, wounded by the furbolgs, and glad that Terenthis had sent help.",
        "{We} followed Grimclaw to the cave south of Auberdine and found Volcor coughing and hurt. He admired {our} cloak and needed a moment before he could talk."},
    [995] = {act = "slipped out of the furbolg cave with Volcor", giver = "Volcor",
        "Volcor chose to sneak out rather than fight, and {we} slipped away past the furbolgs together. He went on ahead to Auberdine, and Terenthis took the news as a sign that Darkshore could overcome its troubles.",
        "{We} crept out of the cave with Volcor and made {our} own way back to Terenthis. The rescue gave him faith, he said."},
    [994] = {act = "fought out of the furbolg cave with Volcor", giver = "Volcor",
        "Volcor chose force, and {we} fought beside him down through the furbolgs to the road where Grimclaw waited. Back in Auberdine, Terenthis said the rescue gave him faith that Darkshore's troubles could be overcome.",
        "{We} cut a way out of the furbolg cave with Volcor and parted at the road by Grimclaw. Terenthis wanted to hear {our} side of it at once."},
    [2098] = {act = "recovered the pieces of Gelkak's broken key", giver = "Gelkak Gyromast",
        "Gelkak Gyromast's ship had been sunk by threshadons, and the key to his mechanical first mate broke on the rocks when he washed ashore. {We} took the pieces back from the crawlers, foreststriders and murlocs, and he roared that the beasts would not know what hit them.",
        "{We} brought a pirate gnome the three pieces of his first mate's key, scattered among the beasts of the coast. Gelkak cheered, then asked if {we} had seen his first mate."},
    [2078] = {act = "wound up Gelkak's mechanical first mate", giver = "Gelkak Gyromast",
        "Gelkak sent {us} to put the key in his first mate's head and bring the machine back to serve him. {We} wound up the Threshwackonator 4100 and led it home, and Gelkak said {we} had proven more than a yellow sea dog.",
        "{We} found Gelkak's mechanical first mate and wound it with the mended key, ready for his revenge on the murlocs. He talked of promoting {us} to poop deck swabby."},
    [1442] = {act = "brought a Kor gem out of Blackfathom Deeps for Stilwell", giver = "Thundris Windweaver", solo = true,
        "Thundris Windweaver remembered the blacksmith Jordan Stilwell and trusted that his wish for a Kor gem was noble. {I} went down into Blackfathom Deeps, where the naga still used the gems, and brought one back for Thundris to purify.",
        "{My} search for a Kor gem led into the ruins of Blackfathom Deeps and its naga. Thundris cleansed the stone of their corruption and warned {me} it was no simple thing to carry."},
    [3765] = {act = "answered Argos Nightwhisper's call to Auberdine", giver = "Argos Nightwhisper",
        "Argos Nightwhisper had come all the way to Stormwind looking for a seasoned adventurer to help his brother. {We} made the long journey north to Auberdine, and Gershala Nightwhisper had much to talk about.",
        "{We} crossed the sea to Auberdine on Argos Nightwhisper's word, to his brother Gershala. Gershala knew {we} must be weary from the road, but there was much to discuss."},
    [1167] = {act = "went back to Balthule before the strike on Athrikus", giver = "Delgren",
        "Before {we} faced Athrikus, Delgren advised {us} to consult Balthule, who had kept watch on the Tower of Althalaxx all along. Balthule told {us} of a blinding flash from the upper room, then screams and lightning striking the ground.",
        "{We} went back north to Balthule Shadowstrike at the Tower of Althalaxx. He was glad to see {us}, for the strangest things had been happening there."},
    [1143] = {act = "slew Athrikus Narassin atop the Tower of Althalaxx", giver = "Balthule Shadowstrike",
        "{We} knew the way to the Tower of Althalaxx by then, and climbed it past warlocks deadlier than any before. Athrikus Narassin, the ancient warlock, died at the top, and Balthule hoped the demons would be driven back.",
        "On Balthule's word {we} struck at last and ended Athrikus Narassin, an ancient and powerful warlock of the Dark Strand. Balthule expected the demonic forces to regroup, but meant to be ready when they did."},

    -- Redridge Mountains (novice into seasoned).
    [120] = {act = "carried Magistrate Solomon's plea to General Marcus Jonathan", giver = "Magistrate Solomon",
        "Lakeshire was under constant siege, and Magistrate Solomon said that without reinforcements it would fall. {We} carried his report to General Marcus Jonathan in Stormwind, who called Solomon a noble leader and promised to take it to the king.",
        "{We} brought Solomon's report on the state of Lakeshire to General Marcus Jonathan. The army would support the town, he said, as soon as His Majesty gave the word."},
    [121] = {act = "brought General Jonathan's letter back to Solomon", giver = "General Marcus Jonathan",
        "While he waited on the king, General Jonathan dismissed {us} with a letter for Solomon. {We} carried it back to Lakeshire, and the magistrate found it a mystery, and feared this was the beginning of a conflict, not its end.",
        "{We} brought the general's answer back to Magistrate Solomon, a letter and no soldiers. Something was amiss in the kingdom, Solomon said, and paid {us} for the long road."},
    [144] = {act = "brought Stoutmantle's answer back to Lakeshire", giver = "Gryan Stoutmantle",
        "Solomon's note pained Gryan Stoutmantle, who had no men to spare in a war Solomon knew nothing about. {We} carried his refusal back to Lakeshire with word that his heart was heavy over good men lost.",
        "{We} brought Magistrate Solomon the news that the People's Militia could send no help. He had not known Stoutmantle's plight was so like his own, and wondered aloud what could call the army away from its people."},
    [116] = {act = "fetched four kinds of drink for Barkeep Daniels", giver = "Barkeep Daniels",
        "The orc invasion had stopped Lakeshire's booze shipments, and Barkeep Daniels's bottles were nearly dry. {We} fetched lager from Grimbooze Thunderbrew, Merlot from Stormwind, moonshine from Darkshire and rum from Goldshire, and his wife's cloak paid for the trip.",
        "{We} traveled the roads of half the kingdom to restock the inn at Lakeshire, lager, wine, moonshine and rum. Daniels knew well what those roads were like, and his patrons would be happy again."},
    [129] = {act = "brought Darcy's lunch to Guard Parker on the southern road", giver = "Darcy",
        "Darcy had made lunch for Guard Parker, but the road he patrolled toward Duskwood was too dangerous for townsfolk. {We} carried it out to him, and he thanked her kind heart and ate gladly.",
        "{We} found Guard Parker on his patrol of the southern road and handed him Darcy's lunch. Guarding the town from orcs and gnolls was tough work, he said, and he could really use the meal."},
    [130] = {act = "bought flowers for Darcy at Martie's shop", giver = "Guard Parker",
        "Parker wanted flowers sent back to Darcy, from the herbalist at the west end of town, and asked {us} not to say whom they were from or for. Martie Jainrose wondered whether {we} had already found a sweetheart in town.",
        "{We} went to Martie's herbalist shop for a bouquet, keeping Parker's secret as he asked. Martie could not help prying, glad to see love in the air in such dangerous times."},
    [131] = {act = "delivered a bouquet of daffodils to Darcy", giver = "Martie Jainrose",
        "Martie chose daffodils, her own favorite, and {we} carried them to Darcy, who loved them until she recognized them. She suspected her rival might have poisoned them, but gave {us} the lunch she had promised.",
        "{We} brought Darcy the daffodils from Parker and walked straight into her rivalry with Martie. Darcy blamed Martie, not {us}, and paid with a free lunch."},
    [3741] = {act = "found Hilary's necklace at the bottom of the lake", giver = "Shawn",
        "Hilary had lost the necklace her daddy gave her while fishing off the dock, and the children were not allowed to swim. {We} dove into the lake past the mean things underwater and found it, and Hilary thanked {us} for herself and her kitty.",
        "{We} searched the bottom of Lake Everstill for a little girl's necklace. Hilary was very glad to have it back, and wanted to know if {we} had beaten up any monsters."},
    [125] = {act = "raised Foreman Oslow's toolbox from the lake", giver = "Foreman Oslow",
        "Foreman Oslow's tools had come by wagon until the bridge was blown, then by boat until the orcs hit it with a catapult. {We} dove for his toolbox at the bottom of Lake Everstill, and he never thought he would see it again.",
        "{We} brought Oslow's toolbox up from the bed of the lake, sunk by an orc catapult. With the town under siege he needed every tool, and he paid well for it."},
    [244] = {act = "warned Deputy Feldon of the gnoll camps near the border", giver = "Guard Parker",
        "Guard Parker had seen gnoll camps north and east of his road and wanted Lakeshire warned. {We} found Deputy Feldon south of the bridge, who was alarmed to hear of gnolls so close to Elwynn and paid {us} a scout's wage.",
        "{We} carried Parker's warning to Deputy Feldon, dire news at a bad time. Soon, Feldon feared, Lakeshire might not be the only town under siege."},
    [246] = {act = "counted and harried the gnolls of the southern road", giver = "Deputy Feldon",
        "Feldon had no men to spare, so {we} went along the southern road and harried the gnolls, killing what {we} could and counting the rest. It was a sizable, tough force, he said, and it could not have been easy.",
        "{We} brought Deputy Feldon a count of the gnolls camped along the southern road, and the marks of the fighting it took. He sent {us} on to Marshal Marris and Magistrate Solomon, since things were growing desperate."},
    [65] = {act = "went to Lakeshire to find Wiley for Stoutmantle", giver = "Gryan Stoutmantle",
        "Gryan Stoutmantle needed to know who led the Defias and where they hid, and a rogue in Lakeshire owed him a favor. {We} found Wiley at the inn, who admitted the debt as soon as he heard who had sent {us}.",
        "{We} traveled east to the inn at Lakeshire to find Wiley for Stoutmantle. {Our} first lead on the Defias Brotherhood was a rogue who owed the militia a favor."},
    [92] = {act = "gathered meat for Chef Breanna's goulash", giver = "Chef Breanna",
        "Chef Breanna had fed a whole brigade of Stormwind troops during the orc uprising, and her cupboard was bare. {We} hunted condors, goretusks and spiders for her, and she served {us} a bowl of Redridge Goulash.",
        "{We} brought Breanna condor meat, goretusk snouts and spider meat, fine specimens, she said. Her bare cupboard filled again, and she cooked {us} a hot meal."},
    [119] = {act = "carried Argus's horseshoes back to Verner", giver = "Smith Argus",
        "Argus boxed up fifty horseshoes and told {us} to make sure Verner read the note on the crate. {We} carried it to Lakeshire, and Verner was grateful until he read that Argus wanted to be paid.",
        "{We} brought Verner Osgood his horseshoes from Goldshire, and the bill that came with them. Verner grumbled at the note, but thanked {us} for the help."},
    [122] = {act = "hunted black whelps for their underbelly scales", giver = "Verner Osgood",
        "Verner meant to pay Argus in black dragon whelp scales, and the whelps flew south of Lakeshire when they did not wander off. {We} hunted six of them, enough to get Verner out of debt with some left to make something for {us}.",
        "{We} brought Verner the underbelly scales of black whelps before greedy Argus could send someone to collect. The leftovers became a gift for {us}."},
    [146] = {act = "carried Lord Ebonlocke's refusal back to Lakeshire", giver = "Lord Ello Ebonlocke",
        "Lord Ello Ebonlocke would not send the Night Watch, for it existed because Stormwind had abandoned Darkshire, and without it the town would fall. {We} carried his letter to Solomon, who suspected treachery in Stormwind.",
        "{We} brought Solomon word that Darkshire could not help either. The army had left Westfall and the guard no longer protected Darkshire, and he meant to get to the bottom of what was wrong in Stormwind."},
    [124] = {act = "drove the gnolls from the ridge above Verner's stable", giver = "Verner Osgood",
        "Gnoll brutes and mystics prowled the ridge north of Verner Osgood's stable, taking his horses when they strayed. {We} climbed the ridge and drove them off, and Verner and his horses were grateful.",
        "{We} thinned the gnolls on the ridge above Lakeshire's stable, whose cries kept Verner's horses skittish. He thanked {us} for all {our} help."},
    [150] = {act = "took murloc fins for Dockmaster Baren", giver = "Dockmaster Baren",
        "Murlocs were fishing the shores of Lake Everstill in larger and larger groups, and Dockmaster Baren feared they would eat all the fish. {We} hunted them for eight fins, and he wondered whether they had come inland running from something.",
        "{We} drove murlocs from the shores of the lake for Dockmaster Baren. It was strange to see them so far from the sea, he said."},
    [20] = {act = "brought Marshal Marris ten Blackrock axes", giver = "Marshal Marris",
        "{We} knew the roads around the lake by then, and the Blackrock orcs who kept Lakeshire penned in like cattle. {We} hunted them north toward Stonewatch Keep and in the southeastern hills, and brought Marshal Marris ten battleworn axes.",
        "The Blackrock orcs had come from the Burning Steppes and taken Stonewatch Keep. {We} killed enough of them to bring Marshal Marris ten of their axes, and he said that made for a lot fewer orcs to worry about."},
    [94] = {act = "set Theocritus's glyph on the lion statue by Ilgalar", giver = "Theocritus",
        "Theocritus could spy on his rival Morganth through the Eye of Azora, but wanted to see his thoughts. {We} carried the Glyph of Azora to the old lion statue by the Tower of Ilgalar and set it in place, and his voice spoke from it in thanks.",
        "{We} placed Theocritus's glyph in the hollow at the base of a lion statue that had watched the Tower of Ilgalar for decades. Now, his disembodied voice said, he could speak with {us} through it."},
    [127] = {act = "brought spotted sunfish to Dockmaster Baren", giver = "Dockmaster Baren",
        "The lake was famous for its spotted sunfish, and Baren was running low. {We} brought him a batch of ten, by line or taken from the murlocs, and he called it a pleasure doing business.",
        "{We} restocked Dockmaster Baren's catch with spotted sunfish from Lake Everstill, some of them taken from the murlocs. He bartered well for them, as he had promised."},
    [248] = {act = "hid a second glyph atop the Stonewatch tower", giver = "Theocritus",
        "Theocritus had seen that Morganth was fighting the orcs of Stonewatch Keep, but not why. {We} climbed the intact watch tower beside the keep and hid his glyph in an empty liquor jar, where nobody would notice it.",
        "{We} slipped a Glyph of Azora into a forgotten jar at the top of the tower beside Stonewatch Keep. Through it Theocritus could reach into the minds within."},
    [91] = {act = "brought Bailiff Conacher ten Shadowhide pendants", giver = "Bailiff Conacher",
        "Morganth, an enemy of Stormwind, used the Shadowhide gnolls to spread terror on the town, and by Lakeshire's law aiding a criminal was death. {We} carried out the sentence and brought Bailiff Conacher ten pendants.",
        "{We} hunted the Shadowhide gnolls who served Morganth and brought their pendants to the court of Lakeshire. Bailiff Conacher said {we} had upheld the justice of the land."},
    [115] = {act = "took midnight orbs from the Blackrock shadowcasters", giver = "Marshal Marris",
        "The Blackrock shadowcasters carried midnight orbs, demon-tainted devices that had struck hard at the town's defenders. {We} killed the shadowcasters and took the orbs, and Marshal Marris sent them away to be destroyed.",
        "{We} brought Marshal Marris the midnight orbs of the Blackrock shadowcasters. The world would be better without them, he said, and had them destroyed at once."},
    [34] = {act = "killed Bellygrub, the boar in Martie's garden", giver = "Martie Jainrose",
        "Martie Jainrose's garden had been trampled again by the boar Marshal Marris called Bellygrub, and her daffodils were ruined. {We} found him foraging in the field southwest of town and brought her his tusk.",
        "{We} put an end to Bellygrub, the boar who kept raiding Martie's garden. She was sure her garden would be in full bloom this season."},
    [345] = {act = "asked Foreman Oslow for Rethban ore for Paxton's ink", giver = "Brother Paxton",
        "Brother Paxton made his own ink, too quick to dry, and his last batch had dried before he finished copying the Stresses of Iron. {We} went to Foreman Oslow in Lakeshire for Rethban ore, but he was too busy fortifying the town.",
        "{We} brought Paxton's request for ore to Foreman Oslow, who had orc damage to repair. If {we} wanted Rethban ore, he said, {we} would have to fetch it without his help."},
    [19] = {act = "brought Marshal Marris the head of Tharil'zun", giver = "Marshal Marris",
        "Blackrock outrunners and renegades were ambushing the road to Stonewatch Keep, and Marris wanted their leader. {We} hunted down Tharil'zun and brought back his head, and the marshal called him a vicious, crafty orc.",
        "{We} ended Tharil'zun, the orc who led the ambushes on the Stonewatch road. Marris was sure he had not gone down easy, and paid {us} for it."},
    [126] = {act = "killed Yowler, the leader of the gnoll pack", giver = "Verner Osgood",
        "The gnolls still bayed in the hills above Lakeshire, and Yowler's cry rose above the rest. {We} hunted him down and sent his pack scattering, and Verner thanked {us}, since the army had no troops for gnolls.",
        "{We} brought Verner Yowler's paw, the gnoll leader he had warned was no mongrel. The town had to face such threats alone, he said, with the army busy with the orcs."},
    [128] = {act = "slew fifteen Blackrock Champions north of Lakeshire", giver = "Guard Howe",
        "The leaders of each Blackrock unit were called Champions, and they camped north of town by the road to the Burning Steppes. {We} slew fifteen of them, and Guard Howe called it a great service to the township.",
        "{We} struck at the Blackrock Champions in their encampment, as Magistrate Solomon wanted. Guard Howe said {we} had fought valiantly."},
    [219] = {act = "escorted Corporal Keeshan out of the Blackrock cave", giver = "Corporal Keeshan",
        "The orcs had overrun Corporal Keeshan's regiment and killed most of his men, and he woke a captive in a cave, badly hurt. {We} found him there, his last hope, and brought him home to Lakeshire alive.",
        "{We} led Corporal Keeshan out of the Blackrock cave and down to Lakeshire, fighting off the orcs on the way. Marshal Marris rewarded {us} for bringing him back."},
    [169] = {act = "took the head of Gath'Ilzogg in Stonewatch Keep",
        "Gath'Ilzogg had led the Blackrock assault on Stonewatch Keep and the raids on Lakeshire, and he was holed up in the keep he had taken. {We} stormed it and brought his head to Magistrate Solomon, who called it vindication.",
        "{We} went into Stonewatch Keep after Gath'Ilzogg, the orc behind its fall, and came back with his head. Solomon called it the first step in taking the keep back for Stormwind."},
    [180] = {act = "brought Magistrate Solomon the paw of Lieutenant Fangore",
        "Lieutenant Fangore led the Shadowhide gnolls in Morganth's service, and Magistrate Solomon wanted the betrayer dead. {We} hunted him down and laid his paw before the court.",
        "{We} ended Lieutenant Fangore, Morganth's gnoll lieutenant, and brought his paw to Solomon. Good riddance, the magistrate said, and Lakeshire thanked {us}."},
    [249] = {act = "defeated Morganth in the Tower of Ilgalar", giver = "Theocritus",
        "Theocritus had learned that Morganth sought the Scythe of Elune and might have found it, and he would not face the warlock himself. {We} climbed the Tower of Ilgalar, defeated Morganth, and brought back his Pendant of Shadow.",
        "{We} faced Morganth at the top of the Tower of Ilgalar and took his Pendant of Shadow to Theocritus. Stormwind had been saved from a grave peril, the high mage said, and he wished {us} victory in the conflicts ahead."},

    -- Duskwood (seasoned).
    [145] = {act = "carried Solomon's plea for the Night Watch to Darkshire", giver = "Magistrate Solomon",
        "Magistrate Solomon wrote to Lord Ello Ebonlocke asking for the Night Watch, and warned {us} not to stray from the roads. {We} kept to them through the dark forest to Darkshire, and Ebonlocke thanked {us} for the long journey.",
        "{We} brought Solomon's letter into the heart of Duskwood, to the mayor of Darkshire. Ebonlocke could see {we} had traveled far, and called the message important."},
    [163] = {act = "found out what haunted Raven Hill", giver = "Elaine Carevin",
        "Calor swore something haunted the empty houses of Raven Hill, shadows moving two nights running and a light in a window. {We} went west to find the monster, and found a terrified man begging {us} not to kill him.",
        "{We} searched the ghost town of Raven Hill for whatever Calor had seen in its windows. It was only Jitters, he swore, harmless Jitters, hiding from things he said were everywhere."},
    [5] = {act = "took Jitters' order for crab cakes to Chef Grual", giver = "Jitters",
        "Jitters had hidden in the ghost town for weeks on grubs and weeds, and would pay well for a real meal. {We} went back to the Scarlet Raven in Darkshire, where Chef Grual thought he might cook up some crab cakes.",
        "{We} took Jitters' order for Dusky Crab Cakes to Chef Grual at the Scarlet Raven Tavern. Grual allowed that he might manage a batch."},
    [93] = {act = "gathered gooey spider legs for Grual's crab cakes", giver = "Chef Grual",
        "Grual let {us} in on his secret, that his Dusky Crab Cakes were made from spider legs. {We} hunted the Venom Web Spiders north of town for gooey legs, and he set them skittering on a skillet with his secret spices.",
        "{We} brought Chef Grual a clutch of spider legs from the nests between the foothills and the river. He kept his crab cake recipe to himself, but gave {us} another nearly as good."},
    [240] = {act = "brought Grual's crab cakes to Jitters", giver = "Chef Grual",
        "{We} carried Grual's crab cakes back through the woods to Jitters at Raven Hill. After weeks of grubs and weeds they hit the spot, and he paid {us} as he had promised.",
        "Jitters met {us} desperate for his food. {We} handed him the cakes from the Scarlet Raven, and he ate gladly and paid."},
    [226] = {act = "thinned the dire wolves around Sven's camp", giver = "Lars",
        "Lars and Sven lived alone at their camp and hunted their own food, and starving dire wolves came at Lars every time he carried meat home. {We} thinned the pack by the river, and Lars paid {us} in flash bundles.",
        "{We} hunted the rabid dire wolves north and east of Sven's camp. With them gone, Lars said, the camp could turn its mind to Morbent Fel."},
    [245] = {act = "rooted out the spiders of the western border", giver = "Watcher Dodds",
        "Spiders had taken over the western border, too many for Watcher Dodds, and the Commander had no men to spare so far from Darkshire. {We} rooted them out, avoiding their venom where {we} could, and Dodds paid {us} for the Night Watch.",
        "{We} cleared the venom web spiders from the western border for Watcher Dodds. He was surprised {we} came back not much the worse for wear."},
    [164] = {act = "carried Elaine Carevin's supplies to Sven's camp", giver = "Elaine Carevin",
        "Sven and his few followers could not spare a man to fetch supplies, so Elaine Carevin sent them by {us}. {We} found the camp at the northwestern edge of the forest, and Sven asked whether {we} had come to join his fight.",
        "{We} brought supplies from the Carevin family to Sven, a man who did the work of the Light, Elaine said. Sven welcomed them and paid {us} for the trouble."},
    [56] = {act = "slew skeletons in Tranquil Gardens for the Night Watch", giver = "Commander Althea Ebonlocke",
        "Stormwind had pulled its guards out of Darkshire, and Commander Althea Ebonlocke's Night Watch stood alone. {We} went south into Tranquil Gardens and broke eight skeletal warriors and six mages among the graves.",
        "{We} fought the skeletons of Tranquil Gardens Cemetery, just south of town, for the Night Watch. Althea Ebonlocke called the work splendid and paid {us} in Darkshire's name."},
    [165] = {act = "checked on the old hermit above Raven Hill", giver = "Elaine Carevin",
        "An old man who used to come into town for supplies had not been seen in a long while, and Elaine Carevin asked {us} to see if something was amiss. {We} found him at his shack overlooking the Raven Hill cemetery, well enough.",
        "{We} walked out to the hermit's shack above Raven Hill Cemetery. Nothing was wrong, he chuckled, but the roads were dangerous for an old man, and he had a few favors in mind."},
    [148] = {act = "asked Madame Eva for Ghost Hair Thread", giver = "Abercrombie",
        "The hermit said he was too old and feeble for the walk to Darkshire, and sent {us} to Madame Eva on the town square for Ghost Hair Thread. Eva had none, but could make some if {we} brought her the hair.",
        "{We} went into Darkshire for the old man's thread. Madame Eva knew what he wanted, and the hair would have to be found first."},
    [149] = {act = "combed the ghost hair of Blind Mary", giver = "Madame Eva",
        "Madame Eva sent {us} to Blind Mary, a sad spirit who haunted an old farmhouse in the hills south of Darkshire. Mary begged {us} not to look at her, then took the Spectral Comb and found it lovely in her hair.",
        "{We} found Blind Mary's ghost in the farmhouse south of town, a spirit who had torn out her own eyes and still felt every gaze. The comb glided through her hair, and she wished for a mirror."},
    [154] = {act = "took the comb full of ghost hair back to Eva", giver = "Blind Mary",
        "Blind Mary's joy did not last, and she cried out to have the comb taken away, calling herself a monster. {We} carried it back to Madame Eva, full of ghost hair, enough for the thread and a few strands over.",
        "{We} brought Eva the comb from Blind Mary, who wanted nothing more to do with it. Eva had her ghost hair and paid {us} for the spare strands."},
    [157] = {act = "delivered the Ghost Hair Thread to the hermit", giver = "Madame Eva",
        "Eva gave {us} the spool and said it had a thousand uses, from binding evil spirits to sewing life into lifeless things. {We} carried it to the hermit, who wanted it strung along his door and windows, and he was delighted.",
        "{We} brought the old man his Ghost Hair Thread to keep unwanted spirits out of his shack. It would do splendidly, he said, and paid {us} for an honorable deed."},
    [158] = {act = "asked Tavernkeep Smitts for a bottle of Zombie Juice", giver = "Abercrombie",
        "The hermit said the nights were cold and he needed Zombie Juice to put fire in his veins. {We} went back to the Scarlet Raven, where Smitts called it strong stuff he was rarely asked for.",
        "{We} took the old man's request for Zombie Juice to Tavernkeep Smitts. It was strong stuff, Smitts said, and he did not usually get requests for it."},
    [156] = {act = "gathered rot blossoms from skeleton skulls for Smitts", giver = "Tavernkeep Smitts",
        "Rot blossoms grew in the skulls of the skeletal horrors and fiends, Smitts said, not that he had ever got close enough to look. {We} broke skeletons at Raven Hill and Tranquil Gardens for them, and he promised to tell the Night Watch.",
        "{We} brought Smitts the rot blossoms for his Zombie Juice, plucked from the skulls of Duskwood's dead. Any help against the fiends, he said, was welcome news in Darkshire."},
    [159] = {act = "carried the Zombie Juice to the hermit", giver = "Tavernkeep Smitts",
        "Smitts warned {us} to be careful, for the Zombie Juice was strong enough to raise the dead. {We} carried it to the hermit, who began to call {us} foolish, then thanked {us} for {our} kindness instead.",
        "{We} brought the old man his bottle to keep him warm on cold, dark nights. He gave a thousand thanks and a token of his gratitude."},
    [90] = {act = "brought Chef Grual lean wolf flanks", giver = "Chef Grual",
        "Grual's Stormwind herbs had arrived, and his seasoned wolf kabobs needed only ten lean wolf flanks. Duskwood had no shortage of wolves, and {we} brought them in short order.",
        "{We} hunted the forest's wolves for Chef Grual's house favorite. He served {us} his seasoned wolf kabobs at the Scarlet Raven."},
    [101] = {act = "gathered the makings of a Totem of Infliction", giver = "Madame Eva",
        "Madame Eva said the winds whispered of a great danger waiting for {me}. {We} brought her ghoul fangs, skeleton fingers and spider venom, and she enchanted a totem to harm anyone who struck at {me}, foreseeing much bloodshed ahead.",
        "{We} gathered fangs, fingers and venom from the dead and the spiders of the forest for Madame Eva's totem. She told {me} to hold it when danger came, and to be brave."},
    [174] = {act = "brought Viktori a bronze tube for his star device", giver = "Viktori Prism'Antras",
        "Viktori Prism'Antras believed a truth beyond magic could explain what had happened to the forest, and his gnome friend Cog had drawn him a device for looking at the stars. {We} found an engineer to make the bronze tube it needed first.",
        "{We} brought Viktori a bronze tube made by a skilled engineer, the first piece of Cog's blueprint. It was perfect, he said."},
    [175] = {act = "found Blind Mary and asked about her looking glass", giver = "Viktori Prism'Antras",
        "Viktori's device needed something to reflect light, and he remembered a woman named Mary who always carried a looking glass. {We} went to the farmhouse south of town where she lingered, and she admitted she had once owned one.",
        "{We} went to Mary in southern Duskwood about the looking glass Viktori remembered. Why yes, she said, she used to own one."},
    [177] = {act = "took Mary's looking glass from the Insane Ghoul", giver = "Blind Mary",
        "After the incident Mary had thrown her looking glass behind the barn, where an Insane Ghoul used to roam. {We} hunted the ghoul in Tranquil Gardens Cemetery and brought the glass to Viktori, who said it would work perfectly.",
        "{We} took Mary's old looking glass from the Insane Ghoul of Tranquil Gardens. Viktori had his reflector, and Cog had been impressed with the device so far."},
    [230] = {act = "dug a hidden notebook out of the mound at Sven's farm",
        "In the mound at Sven's ruined farm {we} dug up a small, dirt-stained notebook with no title. {We} brought it to Sven, who read it and slammed it shut, for the shadowy figure he had seen had watched his family die.",
        "{We} brought Sven the notebook from the mound by his barn. It told him there had been a witness to his family's death, and he had questions for that man."},
    [262] = {act = "showed the notebook from Sven's farm to Madame Eva", giver = "Sven Yorgen",
        "Sven had to know who had skulked in the shadows the night his family was killed, and he gave {us} the notebook as {our} only clue. Madame Eva felt someone driven by revenge had handled it, and that its first owner was no native of Darkshire.",
        "{We} took the notebook from Sven's farm into Darkshire, hoping someone could link it with its owner. Madame Eva could tell little from the faint traces, except that he was a stranger to the town."},
    [265] = {act = "asked Clerk Daltry who had bought the notebook", giver = "Madame Eva",
        "The notebook's author was a stranger, Eva said, but the notebook itself had been bought in town. {We} asked Clerk Daltry, who remembered selling it a month before to a nervous, jittery man always looking over his shoulder.",
        "{We} showed the notebook to Clerk Daltry, who sold blank notebooks to scholars and remembered every buyer. This one had been a shady sort who never gave his name."},
    [266] = {act = "asked at the Scarlet Raven about the notebook's owner", giver = "Clerk Daltry",
        "If the man had stayed in town, someone at the inn would have seen him. Smitts told {us} he remembered the notebook, a guest who wrote at the bar each night, then fled west muttering that something hunted him.",
        "{We} took the search to the Scarlet Raven Tavern. The writer had headed west out of town looking for a place to hide, Smitts recalled, and the first place to the west was Raven Hill."},
    [453] = {act = "found the shadowy figure at Raven Hill", giver = "Tavernkeep Smitts",
        "Smitts hoped {we} would find the man alive, for beyond the town he was prey to the beasts. {We} went west to Raven Hill, and the shadowy figure was Jitters, who sighed and admitted the notebook was his.",
        "{We} followed the trail of the frightened writer west to Raven Hill and found Jitters there. Anyone who had read his notebook, he said, knew only half of it."},
    [268] = {act = "carried Jitters' full account to Sven", giver = "Jitters",
        "Jitters gave up his finished account rather than face Sven's wrath, though it had been his only company for weeks. {We} carried it to Sven's camp, and it set him on the path against the dark riders and the wizard Morbent Fel.",
        "{We} brought Sven the account of what had happened at his farm. He had seen the dark riders speak with Morbent Fel at the Forlorn Rowe, and now he knew his enemies."},
    [57] = {act = "fought the skeletal fiends and horrors of Raven Hill", giver = "Commander Althea Ebonlocke",
        "The undead were rising all through the forest, and Althea Ebonlocke sent {us} to the Raven Hill graveyard and Tranquil Gardens. {We} broke fifteen fiends and fifteen horrors, and she named {us} great allies of the Night Watch.",
        "{We} went back among the graves, Raven Hill and the cemetery south of town, against the skeletal fiends and horrors. The people of Darkshire thanked {us} through their commander."},
    [133] = {act = "brought the hermit ghoul ribs for an effigy", giver = "Abercrombie",
        "Bone Chewers had pounded on the hermit's walls the day before, and he wanted ghoul ribs to build an effigy, a scarecrow for ghouls. {We} took them from the flesh eaters, brain eaters and rotted ones of the forest, and he said they would do the trick.",
        "{We} hunted the ghouls of Duskwood for their ribs while the old man listened for them scurrying behind his house. He was satisfied with what {we} brought."},
    [66] = {act = "took Madame Eva's question about Stalvan to the town hall", giver = "Madame Eva",
        "Madame Eva had felt a horrible disturbance and seen Death in her cards over her granddaughter Alyssa. A trance gave her one name, Stalvan, and {we} took it to the clerk at the town hall.",
        "{We} brought Eva's question to the town hall, a name she had found in a dark trance and nothing more. The clerk knew at once who had sent {us}."},
    [173] = {act = "hunted the Nightbane Shadow Weavers for Calor", giver = "Calor",
        "Calor had left the Night Watch for Master Carevin's fight against evil, and anyone who wished to join had to prove it against the worgen. {We} hunted the Nightbane Shadow Weavers in Brightwood Grove and the Rotting Orchard, and he was impressed.",
        "{We} tested {our} strength against the Shadow Weavers among the dark trees of Brightwood Grove. The worgen seemed to appear out of thin air, Calor said, one more strange thing on the borders."},
    [323] = {act = "fought Morbent Fel's minions for Sven Yorgen", giver = "Sven Yorgen",
        "Sven would not send {us} against Morbent Fel, a necromancer allied with the dark riders, without first knowing {our} strength. {We} fought his minions, and Sven no longer doubted {us}.",
        "{We} fought the necromancer's minions while Sven warned that despair was evil's greatest weapon. {Our} resolve, he said, might yet see Morbent Fel's end."},
    [1243] = {act = "went to Watcher Backus for Elling Trias", giver = "Elling Trias",
        "Elling Trias would use his own contacts and let {us} do the footwork to save coin. {We} went to Darkshire and found Watcher Backus on the north road, surprised that Trias had sent anyone.",
        "{We} told Watcher Backus that Trias wanted to know of any Defias in the woods. Backus laughed that adventurers always ignored his warnings and fought whatever came out of the dark anyway."},
    [221] = {act = "hunted Nightbane Dark Runners in the Rotting Orchard", giver = "Calor",
        "The larger worgen called Dark Runners made up most of the pack and had overrun the Rotting Orchard southwest of town. {We} fought them there, tougher than the Shadow Weavers, but Calor said more always came to fill their ranks.",
        "{We} thinned the Dark Runners in the Rotting Orchard. What evil power drew them to Duskwood, Calor could not say, and he put his faith in Master Carevin."},
    [325] = {act = "carried Morbent's Bane to Sven", giver = "Grimand Elmore",
        "Grimand Elmore in Stormwind finished the weapon made to break Morbent Fel's defenses and looked forward to hearing how it went. {We} carried it to Sven's camp, and he said Morbent Fel would fall.",
        "{We} brought Morbent's Bane from Grimand's forge to Sven Yorgen. Sven saw a fire in {our} eyes that had not been there before, and declared {us} ready."},
    [58] = {act = "cleared the Plague Spreaders from Raven Hill's eastern mausoleum", giver = "Commander Althea Ebonlocke",
        "Things were still grim at Raven Hill, and Althea Ebonlocke had too few Watchers to keep the town safe. {We} went into the eastern mausoleum and killed twenty Plague Spreaders, and she asked the Light to shine on {our} ways.",
        "{We} cleared twenty Plague Spreaders from the eastern mausoleum of Raven Hill, among the dead the Night Watch could not reach. Althea thanked {us} as leader of the Watch and in the name of Darkshire."},
    [134] = {act = "recovered the hermit's crate from the ogre mound", giver = "Abercrombie",
        "Ogres had chased the hermit off while he picked herbs and carried his crate of tools and herbs back to their mound in the south. {We} went to Vul'Gol and found it, and he began to thank the Nec, then thanked {us} instead.",
        "{We} brought the old man his crate from the ogre mound, and he was happy, happy, with happy nights ahead, he said. {We} had more than earned {our} reward, he said."},
    [181] = {act = "took Zzarc'Vul's monocle for Viktori's lens", giver = "Viktori Prism'Antras",
        "The last piece Cog's blueprint needed was a lens, and the only one large enough was the monocle of Zzarc'Vul, an ogre of the mound in the south. {We} took it from him, and Viktori's stargazing device was complete.",
        "{We} brought Viktori the ogre's monocle for his lens, the last part of his star device. At last, he said, he could go on with his research."},
    [160] = {act = "carried the hermit's note to Mayor Ebonlocke", giver = "Abercrombie",
        "The hermit called Mayor Ello Ebonlocke an old friend and laughed that he would be just as happy as he was. {We} carried the note into Darkshire, but Ello did not know the name Abercrombie and could not read the ancient script.",
        "{We} brought Abercrombie's letter to the mayor of Darkshire, who had never heard of him. The writing was in a language Ello could not read."},
    [251] = {act = "took the hermit's note to Sirra Von'Indi", giver = "Lord Ello Ebonlocke",
        "Nobody in town could read Abercrombie's note, so Ello sent {us} to Sirra Von'Indi, learned in languages and ancient arts. Sirra did not know the hermit, but thought anyone living by the graveyard had lost his wits, and began to translate.",
        "{We} brought the strange letter to Sirra Von'Indi, the one man in Darkshire learned enough to read it. He knew nothing of the hermit, but set to work on it at once."},
    [401] = {act = "waited while Sirra finished the translation", giver = "Sirra Von'Indi",
        "Sirra was almost done with the note, and {we} waited a few moments by his side. When he finished, the air grew heavy, as if a black curtain had been drawn over the land.",
        "{We} stood in Sirra's study while he wrote out the last words of the translation. Something dark settled over Darkshire as he finished."},
    [252] = {act = "brought the translation to Ello and learned what the hermit was", giver = "Sirra Von'Indi",
        "Sirra feared Abercrombie had done something unspeakable, and that a doom already lumbered toward the town. {We} hurried the translation to Ello, who went white and told {us} that {our} kindness to the hermit had doomed Darkshire.",
        "{We} carried Sirra's translation back to the mayor and watched his face drain as he read. Every errand {we} had run for the old man had helped bring that doom, and Ello fell silent."},
    [253] = {act = "took the Embalmer's beating heart from Eliza's grave", giver = "Lord Ello Ebonlocke",
        "The Embalmer had been a kindly alchemist once, Ello said, until grief drove him to put his own heart in his dead wife Eliza. {We} found her grave and took the heart while it still beat, and Ello said the town would remember {us} forever.",
        "{We} went to Eliza's grave and faced what the Embalmer had made of her to take back his living heart. With it Darkshire had an aegis against him, and some of the harm of {our} kindness to the hermit was undone."},
    [1041] = {act = "followed Velinde Starsong's trail to Darkshire", giver = "Caravaneer Ruzzgot",
        "Caravaneer Ruzzgot admitted he had been wrong about {us}, which did not happen every day. He remembered Velinde, a night elf priestess who rode his caravan until she turned north for Darkshire, and {we} followed, by then knowing the forest well.",
        "{We} carried the search for Velinde from Stranglethorn up to Darkshire, where Clerk Daltry kept notes on every stranger. It was seldom pleasant business when those notes were needed, he said."},
    [1042] = {act = "asked Jonathan Carevin about the worgen", giver = "Clerk Daltry",
        "Daltry had no Velinde in his ledgers, but the worgen {we} mentioned caught his ear, for Calor had come into town with a string of their heads. {We} went to Jonathan Carevin, who met {us} with open suspicion and wanted answers.",
        "{We} took the trail to the Carevin house, hunters of demons and undead. Jonathan asked no forgiveness for his suspicion of a stranger asking about worgen in such dark times."},
    [1043] = {act = "searched Roland's Doom, where the worgen first appeared", giver = "Jonathan Carevin",
        "Jonathan did not understand {our} motives, but fewer worgen was enough for him. {We} went into the mine south of town where they had first been found, and he set Calor to contain them after hearing what {we} learned.",
        "{We} searched the worgen-held mine of Roland's Doom and brought Jonathan an account he found interesting. His family could not reach the root of the trouble, but would hold the worgen's numbers down."},
    [1244] = {act = "searched Addle's Stead for Defias papers", giver = "Watcher Backus",
        "Defias agents had gathered at Addle's Stead a couple of weeks before, and Backus guessed something big had happened. {We} searched the farmstead and brought him papers that looked official, though he warned they might be a ruse.",
        "{We} went to Addle's Stead, south of the road from Westfall, and came back safe with Defias documents. Backus could not yet say whether they were real or a decoy."},
    [222] = {act = "fought the Vile Fangs and Tainted Ones by their bonfires", giver = "Calor",
        "The Vile Fangs and the Tainted Ones were the most dangerous worgen in the forest, settled by the caves and the mine to the south. {We} went where their bonfires showed and beat them, and Calor admitted he had not thought {we} would get this far.",
        "{We} took on the toughest worgen in Duskwood, as Calor judged {us} ready to. He offered to write {us} a recommendation to Master Carevin."},
    [223] = {act = "carried Calor's recommendation to Jonathan Carevin", giver = "Calor",
        "Calor handed {us} a faded parchment for Master Carevin, saying a few more like {us} and they would outnumber the Night Watch. Jonathan apologized for his cold welcome and accepted {us} into his struggle against demons and the undead.",
        "{We} brought Calor's letter to Jonathan Carevin, a busy man who said impressing Calor was no small feat. Trust none who would not aid the cause, he warned, and wished {us} glory under the Light."},
    [98] = {act = "executed Stalvan Mistmantle at his cottage", giver = "Commander Althea Ebonlocke",
        "The long inquiry had shown who Stalvan Mistmantle was, a man whose victims had died by his hand, and Commander Ebonlocke ordered him executed. {We} went to his cottage north of town, and Stalvan was dead when {we} carried his family ring to Madame Eva.",
        "{We} carried Stalvan's family ring to Madame Eva, whose premonition had begun it all. His killing days were over, and she mourned his victims even as she felt hope ripple through the forest."},

    -- The Wetlands (seasoned).
    [161] = {act = "carried Hinderweir's powder sample to Ashlan Stonesmirk", giver = "Chief Engineer Hinderweir",
        "Hinderweir wanted an explosives expert to name the sappers' powder, and the nearest was Ashlan Stonesmirk at Dun Modr. {We} went through the Algaz Gate and up the marsh road, stopping for nothing, and Stonesmirk could barely hear {us} for the ringing in his ears.",
        "{We} made the grave and perilous journey north with Hinderweir's sample, as the engineer put it. At Dun Modr old Stonesmirk peered at the powder and said Hinderweir was wise to be worried."},
    [942] = {act = "brought Remtravel's fossil to Flagongut in Menethil", giver = "Chief Archaeologist Greywhisker",
        "The fossil from Remtravel's dig looked like one Greywhisker had seen at an Explorers' League conference, brought by an archaeologist named Flagongut. {We} took the ship from Auberdine to Menethil Harbor and found him in the Deepwater Tavern.",
        "{We} crossed the sea with Remtravel's fossil and showed it to Flagongut in the Deepwater Tavern. Amazing, he said, simply amazing, that it came all the way from Kalimdor."},
    [455] = {act = "broke through the Dragonmaw at Dun Algaz to Menethil", giver = "Mountaineer Rockgar",
        "The Dragonmaw had pushed into Dun Algaz, and if they held it the loch would be cut off from Menethil Harbor. {We} broke through the pass, killing orcs as {we} went, and reported to Valstag Ironjaw, who found the news all bad.",
        "{We} fought down through Dun Algaz into the marshes and followed the road west to Menethil. Valstag Ironjaw could not say what had driven the Dragonmaw out of their hills, and expected to want {our} help against them."},
    [463] = {act = "sought out the Greenwarden in the marsh", giver = "First Mate Fitzsimmons",
        "First Mate Fitzsimmons called {us} fools for seeking the Greenwarden and told {us} to leave {our} money behind. {We} went into the marsh east of the Dun Modr fork among the crocolisks, and the bog beast said the roots and ferns spoke well of {us}.",
        "{We} found the Greenwarden in the marshes, not the beast Fitzsimmons promised but a being who asked {us} to call him Rethiel. The land wept from festered wounds, he said, and he charged {us} to heal them."},
    [469] = {act = "carried Einar's crocolisk skins to the tanner", giver = "Einar Stonegrip",
        "Einar Stonegrip had a bundle of crocolisk skins for the tanner in Menethil, but his wife had been in a mood and he was putting off going home. {We} took them to James Halloran, who guessed at once it was trouble with the wife.",
        "{We} brought Einar's skins into Menethil for him. Halloran had not seen Einar in person for nearly a week, and thought he might send his own wife to talk with Sida."},
    [276] = {act = "thinned the Mosshide gnolls near the gate of Algaz", giver = "Rethiel",
        "The Mosshide gnolls had lived peacefully in the marsh for years, but now they trampled the flowers and cut living wood for their fires. {We} went south toward Algaz and thinned them, and Rethiel said his faith in {our} people might yet return.",
        "{We} hunted Mosshide gnolls and mongrels for the Greenwarden, who wanted balance in the marsh. Rethiel's faith in {our} kind had been taxed before, and this work gave it reason to mend."},
    [279] = {act = "slew Gobbler and his Bluegill kin by the inlet",
        "Murlocs were crawling out of the deep to build villages on the coast, and one called Gobbler raided merchants on the road before slipping back to the hovels. {We} found him by the inlet north of town and brought back his head for the Merchant Marines.",
        "{We} hunted Gobbler and the Bluegill murlocs along the river inlet, a threat to every merchant on the road. The Merchant Marines paid {us} for the contract."},
    [484] = {act = "skinned young crocolisks for James Halloran", giver = "James Halloran",
        "James Halloran's cured skins shipped to ports all over the world, and he was short of the soft ones from young crocolisks. {We} hunted them in the waters just outside town, and he called the skins superb.",
        "{We} brought Halloran a stack of young crocolisk skins for top coin. He wanted them curing at once, and he already had more work in mind for {us}."},
    [277] = {act = "took the Mosshides' fire flints for Rethiel", giver = "Rethiel",
        "The Mosshides burned the trees of the marsh for warmth, and Rethiel could bear that pain no longer. {We} took the crude flints from every gnoll that carried one, and he swore to smash them and cast them into the sea.",
        "{We} brought Rethiel the flints the Mosshides used to burn living wood. He thanked {us} quietly, and they would never kindle another fire."},
    [305] = {act = "went looking for Merrin at the Whelgar Excavation", giver = "Tarrel Rockweaver",
        "Tarrel Rockweaver's wife Merrin had written every week from the Whelgar Excavation, then nothing for two weeks. He took {us} for the scout Longbraid had promised, and {we} went east and found her alive on a bluff above the ruined dig.",
        "{We} went east to the Whelgar Excavation for Tarrel, sick with worry over his wife. Merrin thanked the heavens when she saw {us}."},
    [306] = {act = "carried Merrin's note back to her husband Tarrel", giver = "Merrin Rockweaver",
        "Merrin told {us} how the dig had turned up great bones, how the raptors came, and how Ormer saved her and the Prospector while so many died. {We} carried her note to Tarrel, who took what comfort he could that three had lived.",
        "{We} brought Tarrel Rockweaver the letter from his wife, alive but trapped with two others above their ruined dig. He longed for the day King Magni's subjects could live without fear."},
    [294] = {act = "began Ormer's revenge on the mottled raptors", giver = "Ormer Ironbraid",
        "The raptors had come for the bones the diggers uncovered and killed Ormer Ironbraid's brethren. {We} went down below the bluff and killed ten mottled raptors and ten screechers, the start of his vengeance.",
        "{We} fought the raptors west of the bluff where Ormer sheltered with Merrin and the Prospector. Killing was dirty business, he said, and he wished he could shed blood beside {us}."},
    [470] = {act = "recovered Sida's bag from an ooze at Ironbeard's Tomb", giver = "Sida",
        "Oozes had attacked Sida on her weekly visit to Ironbeard's Tomb, and in her panic she threw her bag at one, which sucked it up. {We} went to the tomb near Dun Modr and searched the dripping oozes until {we} found it.",
        "{We} fought the oozes of Ironbeard's Tomb, all alike, until one gave up Sida's bag. She had feared it lost for good, and gave {us} something from it once {we} washed it off."},
    [943] = {act = "brought Flagongut the Stone of Relu and Whelgar's fossil", giver = "Archaeologist Flagongut",
        "Flagongut believed his Stone of Relu would unlock the fossils, but a raptor had swallowed it on the road to Whelgar's dig. {We} hunted the mottled raptors until one gave it up, fetched the original fossil from Prospector Whelgar, and brought both back to Menethil.",
        "{We} carried the Stone of Relu, cut from a raptor's belly, and Whelgar's fossil to Flagongut in the Deepwater Tavern. He meant to see at once whether the stone would decipher their powers."},
    [281] = {act = "searched the murloc hovels for the Menethil Statuette", giver = "Karl Boran",
        "Murlocs had raided the merchant ship Blind Princess and dragged its cargo overboard, among it a valuable statuette of Terenas Menethil. {We} searched the coastal hovels for it, and the first clawed crate held only straw and red bottles.",
        "{We} started at the first cluster of murloc hovels on the coast, looking for Karl Boran's lost statuette. A water-stained crate gave up an armload of red bottles instead."},
    [284] = {act = "searched another cluster of murloc hovels",
        "The first hovels held no trace of the statuette, so {we} moved on to the next to the north. An untouched barrel there burst with the pungent smell of cheese, a little wet but still tasty.",
        "{We} went on up the murloc coast, hovel by hovel. One barrel gave {us} wet cheese, and nothing of Terenas Menethil."},
    [285] = {act = "pressed north to the last murloc hovels",
        "Another group of hovels turned up nothing, but the next, {we} felt sure, would not. In the hovels to the north {we} found a barrel half buried in the mud and grass.",
        "{We} kept searching north along the coast, each empty hovel making the next one likelier. At the last of them a barrel lay sunk halfway into the muck."},
    [286] = {act = "returned the Menethil Statuette to Karl Boran",
        "{We} pulled the barrel free and found a silvery figure packed in straw, a young, long-haired paladin with his hammer raised. {We} carried it to Karl Boran in Menethil, who said the Blind Princess's captain would be relieved.",
        "The statuette of Terenas Menethil came out of a murloc's barrel and back to Karl Boran with {us}. It was good to see dependable folk in trying times, he said, and paid {us} well."},
    [472] = {act = "went to Dun Modr to find Longbraid alive",
        "A soldier in Menethil, struck in the back by an axe as Dun Modr fell, still hoped his commander Longbraid was alive. {We} went north and found Longbraid, who said {we} brought hope to a hopeless situation.",
        "{We} found Longbraid the Grim near fallen Dun Modr and told him young Harlo had survived. The regiment was a shadow of itself, he said, but the news from Menethil was good."},
    [275] = {act = "put down the fevered fen creepers", giver = "Rethiel",
        "A festering grew in the marsh, and the fen creepers had risen from it like fevered blisters. {We} put them down along the waterways so they could settle back into the land, and Rethiel granted {us} a boon.",
        "{We} hunted the fen creepers that shambled through the marsh for Rethiel. The land was soothed by it, he said."},
    [471] = {act = "skinned giant crocolisks for Halloran's maimed apprentice", giver = "James Halloran",
        "Halloran's apprentice had gone into the marshes for giant crocolisk skins and come back with one leg, and the tanner still needed the skins. {We} hunted the great crocs north up the coast, and he did not mind {us} killing a few extra.",
        "{We} brought Halloran the skins his apprentice, like a son to him, had paid so much for. He joked about taking {us} on as an apprentice, then admitted {we} had other ambitions."},
    [288] = {act = "bought First Mate Fitzsimmons a drink", giver = "First Mate Fitzsimmons",
        "First Mate Fitzsimmons had served on the Wave Mistress of the Kul Tiras Third Fleet, burned off this coast by red dragons ridden by orcs. He was its sole survivor, and his head pounded. {We} bought him a drink to loosen his tongue.",
        "{We} bought a fresh drink for the last man of the Third Fleet, who called himself a poor, pathetic fool. It hit the spot, and he was ready to go on."},
    [295] = {act = "slew the scytheclaws and razormaws below Ormer's bluff", giver = "Ormer Ironbraid",
        "Ormer wanted the raptors to regret their bloodthirst, and pointed {us} at the scytheclaws and razormaws that crowded the dig below. {We} killed ten of each, and he praised it as a bang-up job.",
        "{We} went back down among the raptors of the Whelgar dig for Ormer's revenge, against the bigger beasts this time. He was delighted."},
    [299] = {act = "found the four lost fragments of the Goaz Stone", giver = "Prospector Whelgar",
        "Prospector Whelgar had uncovered the Goaz Stone just before the raptors came, and its text broke off where four pieces were missing. {We} searched the overrun dig for Ados, Modr, Golm and Neru, and he began to read of Old Gods chained beneath the land.",
        "{We} scoured the raptor-held excavation for the fragments of a Titan tablet that spoke of a divine plan and a doomed prophecy. Whelgar fitted them together and called it the beginning of something epic."},
    [473] = {act = "reported to Captain Stoutfist in Menethil Keep", giver = "Valstag Ironjaw",
        "The Dragonmaw were showing their strength beyond Algaz, and Valstag Ironjaw sent {us} to Captain Stoutfist in the war room of the keep. Stoutfist had heard of {our} fighting at Dun Algaz and had a task ready.",
        "{We} went into Menethil Keep to Captain Stoutfist, who had been briefed by Valstag. He named {us} worthy and put {us} to work against the Dragonmaw."},
    [464] = {act = "took war banners from the Dragonmaw camp", giver = "Captain Stoutfist",
        "The Dragonmaw had nearly died out when their red dragons turned on them, and the survivors had fled Grim Batol into the mountains. {We} attacked their camp northeast of Menethil and brought back their war banners.",
        "{We} brought Captain Stoutfist the Dragonmaw's war banners, and he told {us} of their chieftain, Nek'rosh, son of Nekros. His father had tamed the red dragons until the magic failed and the dragons killed him."},
    [270] = {act = "followed Bishop Farthing's trail to Glorin Steelbrow", giver = "Bishop Farthing",
        "To face Morbent Fel {we} would need a weapon of Lightforge Iron, Bishop Farthing said, a metal that struck with holy truth, and a load of it had sunk with the Third Fleet. {We} traveled north to Menethil and found his colleague Glorin Steelbrow, who knew who could forge it.",
        "{We} brought Bishop Farthing's request to the dwarven priest Glorin Steelbrow in Menethil. {We} had come a long way, Glorin said, and the quest was a dire one."},
    [289] = {act = "freed some of the Third Fleet's cursed crew", giver = "First Mate Fitzsimmons",
        "Fitzsimmons was the only man of the Third Fleet still breathing, but not the only one still walking, for a terrible treasure held his brothers' souls in the wrecks. {We} swam out to the rotting hulls and freed some of the drowned sailors and marines.",
        "{We} fought the cursed crew of the Third Fleet in the wrecks north of Menethil, men whose moans Fitzsimmons heard in his dreams. He thanked {us} for himself and for them."},
    [296] = {act = "slew Sarltooth, the raptor that led the attack", giver = "Ormer Ironbraid",
        "Ormer had noticed one raptor bigger and more menacing than the rest, Sarltooth, and was sure it had led the others to the dig. {We} hunted it down and brought back a talon, and Ormer said {our} vengeance would make the beasts think twice.",
        "{We} ended Sarltooth for the dwarves who died at Whelgar's dig simply doing their jobs. Ormer said the deed would not be forgotten."},
    [321] = {act = "searched the wreck of the Flying Osprey for Lightforge Iron", giver = "Glorin Steelbrow",
        "The Flying Osprey, an elven ship carrying Lightforge Iron, had joined the Third Fleet for protection and sunk to the same dragons. {We} swam to its wreck south of Menethil and found its chest clawed open by murlocs, a single ingot left inside.",
        "{We} searched the sunken Flying Osprey for Glorin and found only one Lightforge ingot in a broken chest. It was far from enough for a weapon, and the murlocs had taken the rest."},
    [324] = {act = "took the lost Lightforge ingots back from the murlocs",
        "The murloc raiders near the Osprey's wreck had stolen the rest of the Lightforge Iron. {We} hunted them along the shore until {we} had enough, and Glorin was ready to have it hammered into something useful.",
        "{We} brought Glorin Steelbrow the Lightforge ingots the murlocs had carried off. Now, he said, the iron could become a weapon."},
    [290] = {act = "took the strongbox key from Captain Halyndor's ghost", giver = "First Mate Fitzsimmons",
        "To break the curse, Fitzsimmons said, the thing stowed in the Intrepid's strongbox had to be taken and cleansed, and his old captain Halyndor still walked the ship with its key. {We} faced the captain's ghost aboard the wreck, and his rusted key fit the strongbox neatly.",
        "{We} went aboard the sunken Intrepid and took the strongbox key from Captain Halyndor, who still lorded over his doomed ship. The lock turned."},
    [292] = {act = "brought the Cursed Eye of Paleth to Glorin Steelbrow",
        "In the Intrepid's strongbox lay a blackened orb pulsing with an eerie light, a Cursed Eye of Paleth. {We} carried it to Glorin Steelbrow, who grumbled about drunk Fitzsimmons until he saw it, then said it was no wonder the man was spooked.",
        "{We} brought the dwarven priest the cursed thing that had held the Third Fleet's dead. Glorin had not known the fleet carried such an Eye, and called it no cause for mirth."},
    [303] = {act = "fought the Dark Irons outside Dun Modr", giver = "Longbraid",
        "The Dark Irons had laid waste to the Thandol Span and taken Dun Modr while dwarven soldiers died abroad. {We} struck their encampment and killed fifteen Dark Irons and their tunnelers, saboteurs and demolitionists, and Longbraid saluted {us}.",
        "{We} kept the pressure on the Dark Iron camp at Dun Modr while Longbraid waited for a reserve that never came. With what {we} had done, he thought they might drive the enemy off for good."},
    [465] = {act = "burned Nek'rosh's catapults in the Dragonmaw camp", giver = "Captain Stoutfist",
        "Nek'rosh had built catapults to lay siege to Menethil, and the fighting at Dun Algaz kept reinforcements away. {We} fought into the Dragonmaw camp with Stoutfist's tinder, struck a spark on each catapult, and watched them burn.",
        "{We} set fire to the Dragonmaw's siege engines one by one, the flame erupting and spreading fast. Only Nek'rosh himself remained."},
    [474] = {act = "killed Chieftain Nek'rosh of the Dragonmaw", giver = "Captain Stoutfist",
        "With his catapults burning, {we} found Chieftain Nek'rosh in his camp and cut him down. Stoutfist called it a telling blow from which the Dragonmaw might never recover, and Menethil Harbor was safe.",
        "{We} ended Nek'rosh, son of Nekros, and with him his siege of Menethil. Captain Stoutfist rewarded {us} in the name of Ironforge as people of merit."},
    [631] = {act = "found Ol' Rustlocke's body by the Thandol Span", giver = "Rhag Garmason",
        "A great explosion had torn the Thandol Span, and Longbraid had sent Ol' Rustlocke to scout the eastern bridge days before. {We} searched for him and found a small dwarven body, its helmet engraved Ebenezer Rustlocke.",
        "{We} went looking for the scout Rhag Garmason could not spare anyone to find. By the bridge {we} found Ol' Rustlocke dead."},
    [632] = {act = "brought Rustlocke's parchment to Rhag Garmason",
        "Ol' Rustlocke had run into a Dark Iron ambush, and a parchment lay beside his clenched fist. {We} carried it and the grim news back to Rhag Garmason, who called it grave.",
        "{We} told Rhag Garmason how his scout had died in a Dark Iron ambush, and showed him the parchment Rustlocke had held at the end. Rhag called the news grave."},
    [633] = {act = "destroyed Kam Deepfury's explosives across the Thandol Span", giver = "Rhag Garmason",
        "Rustlocke's parchment showed that Kam Deepfury had hidden a cache of explosives just across the Thandol Span, enough to sever the supply line north. {We} crossed into the Arathi Highlands and destroyed it, and the last bridge was saved.",
        "{We} made sure Rustlocke had not died in vain, destroying Kam Deepfury's cache before it could reach the bridge. Rhag said {we} had done King Magni a great service."},
    [1248] = {act = "found Trias's old contact Mikhail in Menethil", giver = "Elling Trias",
        "The Defias docket said nothing of where the diplomat had been taken, so Trias sent {us} to Mikhail, a contact retired to a Menethil bar. Mikhail offered {us} ale and mutton, then hushed {us} at the name Trias.",
        "{We} went to Menethil Harbor to find Slim through Mikhail, Trias's old contact. The bartender welcomed {us} warmly, until he heard who had sent {us}."},
    [1249] = {act = "caught Slim listening in Mikhail's tavern", giver = "Mikhail",
        "Mikhail did not know the name Slim, but warned {us} of a man by the door listening too intently. {We} stopped him before he could run, and he turned out to be Slim himself.",
        "{We} caught the eavesdropper at the tavern door, and Mikhail was surprised to learn he was Slim. He admitted he missed the old excitement, and asked {us} not to tell Elling."},
    [1250] = {act = "learned from Slim that the Defias had taken the king", giver = "Slim",
        "The Defias did not pay Slim enough to die for them, so he talked to {us}. It was no diplomat they had taken, but the king of Stormwind on his way to Theramore, and Slim's part had been to get a man called Hendel aboard his ship.",
        "{We} brought Mikhail the truth Slim had confessed, that the king himself was missing. Mikhail sent word to Elling at once, and thought he could help {us} find Hendel."},
    [304] = {act = "slew Balgaras the Foul for Longbraid the Grim", giver = "Longbraid",
        "Longbraid's brother had died when the West Bridge fell, and Roggo had named the Dark Iron leader, a cowardly warlock called Balgaras the Foul. {We} found him at last and brought his ear to Longbraid, who said it would ease the minds of the survivors.",
        "{We} hunted down Balgaras the Foul, who sent his soldiers to fight and kept himself out of danger. His death could not bring back the dwarves he had killed, Longbraid said, but the rest of the Dark Irons would be easier now."},

    -- Ashenvale (seasoned).
    [990] = {act = "took the road south to Raene Wolfrunner in Astranaar", giver = "Sentinel Selarin",
        "Sentinel Selarin's mistress, Raene Wolfrunner, was waiting in Astranaar, where corruption had taken hold. {We} followed the road south out of Darkshore into the forest, and Raene said Selarin had done well to send {us} so quickly.",
        "{We} came south into Ashenvale and found Raene Wolfrunner in Astranaar, wishing {our} visit were under less dire stress. The townsfolk could use {our} help, she said, and that was the place to start."},
    [1133] = {act = "offered help to Shindrell Swiftfire in Astranaar", giver = "Fiora Longears",
        "Fiora Longears had advice for anyone fresh off the boat from Menethil, to go to Astranaar and offer help, but not to mention her name. {We} found Shindrell Swiftfire there, who welcomed {us} to a forest still lovely but no longer peaceful.",
        "{We} came to Astranaar to offer {our} services to Shindrell Swiftfire, who did not know Fiora, just as Fiora had said. The forest kept its beauty, Shindrell told {us}, but not its peace."},
    [1008] = {act = "fought the naga on the Zoram Strand", giver = "Shindrell Swiftfire",
        "The naga had come back to the Zoram Strand, where a city of the night elves had lain drowned since the Sundering, and nobody knew why. {We} went to the northwestern coast and threw them back toward the depths, and Shindrell called it commendable.",
        "{We} fought the naga among the drowned ruins of Zoram for Shindrell Swiftfire. She knew their strength and guile well, from a history her people shared with them and did not care to repeat."},
    [1007] = {act = "found a lost statuette on the Zoram Strand",
        "An elf camped on the strand had been skimming over the sunken ruins of Zoram when naga surged up and tore at him, and in his flight he lost the statuette he had come for. {We} searched the beach north of his meager camp and found it.",
        "{We} brought the elf of the strand camp the ancient statuette he had dropped when the naga ambushed him. The old city held many secrets, he said, and this might be the key to them."},
    [1010] = {act = "gathered Bathran's Hair from the haunted ruins", giver = "Orendil Broadleaf",
        "A child in Astranaar was sick, and Orendil Broadleaf believed it was more than an illness of the body. {We} went north to Bathran's Haunt for the herb that cured the spirit, and found Forsaken among the ruins.",
        "{We} brought Orendil the strands of Bathran's Hair from the ruins near the Darkshore border. He set to mixing a cure, troubled by {our} news that the Forsaken were camped there."},
    [1020] = {act = "carried Orendil's cure to Pelturas Whitemoon", giver = "Orendil Broadleaf",
        "Orendil's cure was ready, and {we} followed the road south and east to Astranaar with it. Pelturas Whitemoon had no time to speak, for his daughter Relara was deathly ill, until he saw it came from Orendil.",
        "{We} brought Relara's father the remedy from Maestra's Post. Pelturas trusted Orendil's skill, and the cure gave him hope where he had had little."},
    [1033] = {act = "brought Elune's Tear from the isle in Iris Lake", giver = "Pelturas Whitemoon",
        "Orendil's cure had only slowed the disease in Relara, and Pelturas needed stronger medicine. {We} went to the isle in Iris Lake east of Astranaar for Elune's Tear, a stone said to wash away corruption, and he meant to put it in her stew.",
        "{We} brought Pelturas a stone from the only place it rested, the island in Iris Lake. He thanked {us} over and over and prayed it would end his child's sickness."},
    [1082] = {act = "brought Tara Thenysil word that Kaela and Gaxim were alive", giver = "Kaela Shadowspear",
        "Kaela Shadowspear wanted Astranaar to know that she and Gaxim were alive and well on their way to stopping the Venture Company. {We} carried the good news back to Tara Thenysil, who was glad of Kaela, and even of Gaxim.",
        "{We} came back from Stonetalon with good news for once, that Kaela and the gnome were safe. Sentinel Tara Thenysil thanked {us} for the service to the Sentinels."},
    [1034] = {act = "gathered frosted dust in the Ruins of Stardust", giver = "Pelturas Whitemoon",
        "Elune's Tear had eased Relara's nightmares, but her fever still raged. {We} went south to the Ruins of Stardust for the frosted dust Orendil had spoken of, and Pelturas made a poultice to bring the fever down.",
        "{We} brought Pelturas the frosted stardust he needed for Relara's fever, and he set to making his poultice. Without {our} help, he said plainly, his child would surely perish."},
    [976] = {act = "guarded Feero Ironhand's supplies to Auberdine", giver = "Feero Ironhand",
        "Delgren had given Feero Ironhand supplies and messages for Auberdine, and Feero would not take the road alone with dangerous foes in the forest. {We} walked beside him north to Darkshore and kept the goods out of the wrong hands.",
        "{We} escorted Feero Ironhand and his supplies from Maestra's Post all the way to the Sentinels in Auberdine. The goods would be used at once against the dark threats in the forest."},
    [1016] = {act = "gathered intact bracers from the corrupt elementals", giver = "Sentinel Velene Starstrike",
        "Someone was filling the pools with corrupt elementals, and Sentinel Velene Starstrike's divining scroll could name him if {we} found a few unbroken bracers. {We} fought the elementals until the scroll worked, and Velene wanted the mage to pay.",
        "{We} broke elemental after elemental for the few whole bracers Velene's scroll needed. The divined paper named a wizard poisoning the forest's waters on purpose, and it sickened her."},
    [1025] = {act = "struck the Foulweald furbolgs along the eastern road", giver = "Raene Wolfrunner",
        "Furbolgs had been attacking travelers on the road east of Astranaar, feeding on fear, Raene Wolfrunner said. {We} went to their camps south of the road and showed them the same mercy they had shown her people.",
        "{We} thinned the furbolgs camped south of the road before the Falfarren River, as Raene asked. She thanked {us}, and said {we} had done well."},
    [1009] = {act = "took the Ring of Zoram from Ruuzel's isle",
        "The statuette's lock would only open to the Ring of Zoram, worn by the city's rulers before the Sundering drowned them, and the naga had found it. {We} crossed to the isle at Zoram's northern edge, killed their leader Ruuzel, and brought the ring back to the elf's camp.",
        "{We} took the Ring of Zoram from Ruuzel, the naga leader, on his island off the drowned city. The elf who had lost the statuette paid {us} and said he would remember the deed forever."},
    [1054] = {act = "brought Raene the skull of Dal Bloodclaw", giver = "Raene Wolfrunner",
        "The Thistlefur furbolgs north of Astranaar had grown in number for months, and Raene feared they would soon dare to attack the town. {We} fought into their territory and brought back their chieftain's skull.",
        "{We} killed Dal Bloodclaw, the chieftain of the Thistlefur, and laid his skull before Raene. It would keep the furbolgs at bay a while longer, she said, though the threat was constant."},
    [4581] = {act = "took Shindrell's report to Kayneth Stillwind", giver = "Shindrell Swiftfire",
        "The druid Kayneth Stillwind wanted word of the coast and the forests around Astranaar, fearing a corruption moving through Ashenvale. {We} carried Shindrell's report east to his shrine in the Nightsong Woods.",
        "{We} brought Kayneth Stillwind the report he had asked for, and he called Shindrell a fine sentinel, brave and keen. He meant to read it for signs of the wickedness he feared."},
    [1011] = {act = "stole a bottle of disease from the Forsaken camp", giver = "Kayneth Stillwind",
        "Kayneth believed the Forsaken had come into Ashenvale to spread disease among the night elves, and needed proof. {We} fought into their camp near the Dor'Danil Barrow Den and took a bottle of their brew for him to test.",
        "{We} brought Kayneth a stolen bottle from the camp where the Forsaken brewed their poisons. Testing it, he said, would reveal what they meant to do."},
    [1022] = {act = "read the Tome of Mel'Thandris in the Howling Vale", giver = "Sentinel Melyria Frostshadow",
        "Wolf-men had overrun the ruined shrine of Mel'Thandris near the Felwood border, their howls giving the Howling Vale its name. {We} fought through them to the tome kept there, and what it showed {us} pointed to a priestess named Starsong and the Scythe of Elune.",
        "{We} went into the Howling Vale and stood before the Tome of Mel'Thandris, whose blessed leaves showed events of import. Melyria could not say why it showed what it did, but the scythe bore investigation."},
    [1035] = {act = "took a fallen moonstone from the Shadethicket Oracle", giver = "Pelturas Whitemoon",
        "Relara's fever had passed, but she was too weak for time alone to mend her, and only a moonstone would do. {We} went to Fallen Sky Lake and slew the Shadethicket Oracle who hoarded them, and Pelturas cried that {we} had saved his daughter.",
        "{We} brought Pelturas the moonstone from the Oracle's hoard with Relara down to her last breaths. He gave {us} his most dear possession after his daughter."},
    [1012] = {act = "laid the maddened druid spirits of Dor'Danil to rest", giver = "Kayneth Stillwind",
        "Struggling with the Forsaken's poisons, Kayneth had seen a vision of the Dor'Danil druids murdered and driven mad as ghosts. {We} went into the barrow den and destroyed their leaders, Taneel Darkwood, Uthil Mooncall and Mavoris Cloudsbreak.",
        "{We} did grim work in the Dor'Danil Barrow Den, destroying spirits who had only been victims of the Forsaken. Kayneth felt the anguish there lessen, and hoped the rest might find peace."},
    [1021] = {act = "found the dryad Anilia dying in Xavian", giver = "Illiyana",
        "Illiyana's sisters had gone to take back the Branch of Cenarius from the satyrs two whole days before. {We} searched the ruins of Xavian and found Anilia, who had led them, with a gaping wound in her side.",
        "{We} went into the satyr ruins of Xavian looking for Illiyana's lost sisters, gone two days after the stolen branch. Anilia lay there among the stones, on the verge of death."},
    [1031] = {act = "recovered the Branch of Cenarius from Geltharis",
        "Anilia drew {me} close, pointed north to the arch, and breathed the name Geltharis before she died. {We} went after him and brought the Branch of Cenarius back to the dryads, as she had wished.",
        "{We} fulfilled a dying dryad's wish, taking the Branch of Cenarius from Geltharis. Illiyana could not believe her sister was gone, for only yesterday they had played together in the woods."},
    [1032] = {act = "brought Illiyana the horns of Anilia's killers", giver = "Illiyana",
        "Illiyana almost felt sad, she said, and knew one thing that might help, the deaths of the satyrs that took Anilia. {We} hunted them through Xavian and brought her their horns.",
        "{We} avenged Anilia on the satyrs of Xavian, horn by horn, and carried them back to Illiyana. Illiyana said her sister's spirit was gladdened by it."},

    -- Stormwind City (from the first errands to the Keep).
    [332] = {act = "took Renato Gallina's pamphlet to the family wine shop", giver = "Renato Gallina",
        "Renato Gallina swore his family sold the best wine in Stormwind and pressed a pamphlet on {us}. {We} followed the lovely canals of the Trade District to the shop, where his sister Suzetta gave {us} a bottle of their famous pinot noir.",
        "{We} found the Gallinas' wine shop along the canals of the great city, a pamphlet in hand. Suzetta swore the pinot noir she gave {us} had no equal in all of Azeroth."},
    [333] = {act = "carried Harlan Bagley's order to Rema Schneider", giver = "Harlan Bagley",
        "Everyone was buying armor and sturdy clothes from Harlan Bagley, as if a harsh season lay ahead, and he was running out of knitted goods. {We} took his order to Rema Schneider at the Canal Tailor and Fit Shop.",
        "{We} brought Rema Schneider word that Harlan's business was booming. She was glad, but wondered why so many people needed armor with no open war, and what the nobles were not telling them."},
    [334] = {act = "brought Thurman's forgotten sewing kit to Larson Clothiers", giver = "Rema Schneider",
        "Rema's son Thurman had rushed off to his apprenticeship without his shears and needles. {We} carried the kit to Larson Clothiers deep in the Mage Quarter, near the tower, and found him less than grateful.",
        "{We} brought young Thurman his sewing kit at Larson Clothiers. He groaned, for he had hoped forgetting it would get him out of a day's work."},
    [61] = {act = "carried William Pestle's candles to his brother Morgan", giver = "William Pestle",
        "William Pestle had no time to make the trip, so {we} carried his shipment of kobold candles to Stormwind, to his brother Morgan at Pestle's Apothecary in the Trade District. Morgan said fortune truly shone on him that day.",
        "{We} brought Morgan Pestle the candles his brother had gathered, wax for the family's apothecary. He paid {us} well and invited {us} to look over his potions and trinkets."},
    [6281] = {act = "flew Lewis's note to Osric Strang in Stormwind", giver = "Thor",
        "For a small fee Thor put {us} on a gryphon with Quartermaster Lewis's note, the fastest way to Stormwind. Osric Strang in Old Town was not surprised Lewis needed more gear, for Westfall was a land Stormwind had all but forgotten.",
        "{We} flew from Sentinel Hill over the forest to Stormwind with a note for Osric Strang. He covered {our} travel costs and said Lewis's need came as no surprise."},
    [6261] = {act = "took Osric's crate of armor to the gryphon master", giver = "Osric Strang",
        "Osric packed everything Lewis had asked for into a crate, so the fighters of Westfall would not go without fresh equipment. {We} took it to Dungar Longdrink in the Trade District, who laughed at the sweat on {our} brows and offered a gryphon.",
        "{We} carried Osric's crate to Dungar Longdrink, the gryphon master of Stormwind. Since {we} had been to Westfall before, he had plenty of gryphons trained for the route."},
    [1338] = {act = "carried Mountaineer Stormpike's shield order to Furen Longbeard", giver = "Mountaineer Stormpike",
        "Mountaineer Stormpike had to have a shield made by Furen Longbeard, though he could not see why the smith lived among humans so far from Ironforge. {We} carried the order south to the Dwarven District, and Furen promised to start that very day.",
        "{We} brought Furen Longbeard an order from the Stormpikes, a proud clan, he said, and a rich one. The shield would be under way by the end of the day."},
    [399] = {act = "found Baros Alexston's boyhood compass on his family's farm", giver = "Baros Alexston",
        "Baros Alexston had worked a farm in Westfall as a boy, and now it was burned and taken by thieves. {We} searched the Alexston Farmstead west of Sentinel Hill for the first compass he ever owned, and brought it to him in Cathedral Square.",
        "{We} went all the way to Westfall for a compass of no practical use, and Baros Alexston was deeply grateful. It was the sentimental value, he said, from the boy he had been."},
    [1097] = {act = "answered Grimand Elmore's call for a courier", giver = "Smith Argus",
        "Smith Argus said a dwarven weaponsmith in Stormwind needed a package carried north, and that keeping ties strong with the dwarves mattered. {We} went to the weapon shop in the Dwarven District, and Grimand Elmore was glad of the help.",
        "{We} found Grimand Elmore at his shop in the Dwarven District, as Argus had sent {us}. He had a delivery for his homeland in the north."},
    [2041] = {act = "found Shoni the Shilent among the dwarves of Stormwind",
        "Help for the battle for Gnomeregan was needed in Stormwind, where the commander of the underground assault crew worked among the dwarves. {We} found Shoni the Shilent there, who asked whether {we} brought word from central command.",
        "{We} carried the movement's word to Shoni the Shilent, whose gyrodrillmatic excavationators needed help. She took {us} for messengers from central command."},
    [135] = {act = "showed Wiley's note to Mathias Shaw in Old Town", giver = "Gryan Stoutmantle",
        "Wiley had mentioned the Stonemasons, and Stoutmantle wondered whether the Defias were tied to them. {We} took the note to Mathias Shaw, master of the kingdom's spies, in the barracks of Old Town, who said the matter might be more complex than Stoutmantle realized.",
        "{We} brought Wiley's note into Stormwind's shadows, to Mathias Shaw, a very busy man. The question of the Stonemasons was more tangled than anyone in Westfall knew, he said."},
    [373] = {act = "delivered VanCleef's unsent letter to Baros Alexston",
        "On Edwin VanCleef's body {we} found a letter, recently sealed, addressed to Baros Alexston, the City Architect. Baros was surprised VanCleef was dead, a peerless fighter in his youth, and found him an idealist still, consumed by revenge.",
        "{We} carried a dead man's last letter to Cathedral Square. Baros read it and said revenge had consumed Edwin, though he was not sure he could blame him."},
    [389] = {act = "went down to the Stockade to ask about Bazil Thredd", giver = "Baros Alexston",
        "Baros told {us} how the nobles had refused to pay the Stonemasons for rebuilding Stormwind, and how VanCleef led a riot and left swearing revenge. {We} went to the Stockade to ask about his lieutenant, Bazil Thredd, and found the prison in uproar.",
        "{We} went to Warden Thelwater about Bazil Thredd, and walked into a riot with every cell open. The warden suspected {us} of being Thredd's cronies, and would have locked {us} up if he had a cell to spare."},
    [343] = {act = "asked Milton Sheaf for the Stresses of Iron", giver = "Brother Kristoff",
        "Brother Kristoff wanted passages from the Stresses of Iron for a speech on the Fortitude of the Spirit. {We} went to the Royal Library in Stormwind Keep, where Milton Sheaf knew every shelf like his own son.",
        "{We} carried Kristoff's request to Milton Sheaf, head of the Royal Library. He had many volumes on metallurgy and was happy to help, once he knew which one."},
    [346] = {act = "brought the Stresses of Iron back to Brother Kristoff", giver = "Brother Paxton",
        "Paxton had finished his copy at last and gave {us} the original Stresses of Iron, with an apology for Milton. {We} carried it to Brother Kristoff in Cathedral Square, who asked the Light to shine on {our} body and spirit.",
        "{We} brought the long-delayed volume back from the abbey to Brother Kristoff. It was the one, he said, and blessed {us} for it."},
    [337] = {act = "returned a long-lost history of Stormwind to the Royal Library",
        "{We} found an old volume caked in mud, The History of Stormwind, stamped with the seal of the city's library. Milton Sheaf said it had not rested on his shelves since before the rebuilding, and would join the rare collection.",
        "Someone had borrowed The History of Stormwind years ago and never brought it back, until {we} did. Milton Sheaf paid {us} and promised to restore it."},
    [1075] = {act = "carried Gaxim's request for a spell to Collin Mauren", giver = "Gaxim Rustfizzle",
        "Gaxim wanted to set off his NG-5 explosives from a distance, and for that he needed a spell from his friend Collin Mauren. {We} went to the Mage Quarter, where Mauren turned the strange request over in his mind.",
        "{We} brought Collin Mauren a gnome's request for a spell to detonate explosives at a distance. He thought it would take some work."},
    [1078] = {act = "brought Collin Mauren basilisk scales from the Charred Vale", giver = "Collin Mauren",
        "Basilisks had once lived in the Charred Vale of Stonetalon whose scales, ground to dust, made a fine reagent for Collin Mauren's spells. {We} found them still there, and he hoped one day to help {us} as {we} had helped him.",
        "{We} carried basilisk scales from the Charred Vale back across the sea to Collin Mauren. There had been no rush, he said, but he was very glad of them."},
    [1274] = {act = "answered Bishop DeLavey's quiet summons to the Keep",
        "A young man named Thomas asked {us} quietly to go to Stormwind Keep, where Bishop DeLavey had a delicate matter. {We} went, and the bishop was blunt, with no time to explain and a plea to keep it from common knowledge.",
        "{We} went discreetly to Bishop DeLavey in Stormwind Keep at Thomas's request. The bishop would say little, and asked {us} to say less."},
    [1241] = {act = "took Bishop DeLavey's note to Jorgen in the Valley of Heroes", giver = "Bishop DeLavey",
        "A diplomat sent to meet Jaina Proudmoore in Theramore had never arrived, and Bishop DeLavey suspected the Defias. {We} carried his note to Jorgen, fishing in the Valley of Heroes, who helped out of obligation and warned {us} to keep it secret.",
        "{We} found Jorgen at his fishing in the Valley of Heroes and gave him DeLavey's note. He squinted at {us}, said {we} knew far more than {we} should, and agreed to help."},
    [1242] = {act = "carried Jorgen's note to Elling Trias at his cheese shop", giver = "Jorgen",
        "Jorgen sent {us} to Elling Trias at Trias' Cheese in the Trade District, with orders to say nothing else and wait. Trias was surprised by a letter that was not a crate or barrel, and asked if all was well with {us}.",
        "{We} handed Elling Trias the note across his counter of cheddar and Darnassian bleu, as Jorgen instructed. Trias read it and looked up at {us} closely."},
    [269] = {act = "sought Bishop Farthing's counsel against Morbent Fel", giver = "Sven Yorgen",
        "Sven sent {us} to Stormwind with Jitters' account, for though the city had forsaken Darkshire, Bishop Farthing was kind and wise. Farthing told {us} that Morbent Fel was immensely powerful and shielded against physical harm.",
        "{We} brought the account of Sven's farm to Bishop Farthing in the Cathedral of Light. He saw the burden on {us}, and said {we} would need a weapon proof against the necromancer's enchantments."},
    [322] = {act = "brought the Lightforge Iron to Grimand Elmore", giver = "Glorin Steelbrow",
        "Glorin packed the Lightforge Iron into a crate for Grimand Elmore, the one smith who could work it. {We} carried it to the Dwarven District, and Grimand said it would be an honor to forge it after so many years.",
        "{We} told Grimand Elmore the long account of the iron and the necromancer, and handed him the crate. He set to work, and asked {us} to come back one day and tell him how the battle went."},
    [392] = {act = "brought Thelwater's description of the visitor Maelik to Baros", giver = "Warden Thelwater",
        "For years Thredd had no visitors, then a quiet man came once or twice a week, with papers that named him Maelik. {We} took Warden Thelwater's description to Baros Alexston, who did not know the man.",
        "{We} brought Baros the description of Thredd's mysterious visitor. The name Maelik meant nothing to him, but someone better connected might know."},
    [393] = {act = "learned from Mathias Shaw who Maelik really was", giver = "Baros Alexston",
        "Baros sent {us} to Mathias Shaw, who owed him a favor and knew the city's shady dealings. Shaw knew the man, an assassin called Marzon among other names, in the pay of Lord Gregor Lescovar.",
        "{We} showed Shaw the description, and he named the man at once, not Maelik but Marzon, an assassin. His master was Lord Gregor Lescovar, a noble of shady reputation."},
    [293] = {act = "brought the Eye of Paleth to Archbishop Benedictus", giver = "Glorin Steelbrow",
        "Human priests had made the Eyes of Paleth, so Glorin sent {us} south to Stormwind and Archbishop Benedictus. The Archbishop saw that the Eye had witnessed a terrible tragedy, and cleansed it.",
        "{We} carried the cursed Eye from the Third Fleet to the Cathedral of Light. Benedictus cleansed it so it could shine as it was made to, for tainted its powers were dangerous."},
    [335] = {act = "gathered a flower and a root for Zardeth's brew", giver = "Zardeth",
        "Lord Wishock was lobbying the nobles to investigate the warlocks below the Slaughtered Lamb, and Zardeth of the Black Claw meant to keep him busy. {We} brought him a Tear of Tilloa from Stalvan's garden in Duskwood and a Musquash Root from below the Stonewrought Dam.",
        "{We} gathered a small white flower in Duskwood and a root from the falls below the dam for Zardeth, who called them fine samples. He meant to brew something special with them for Lord Wishock."},
    [336] = {act = "delivered Zardeth's Black Claw stout to Lord Wishock", giver = "Zardeth",
        "Lord Wishock spent his days trying to shut the warlocks' tavern and his nights drinking upstairs at it. {We} carried Zardeth's Black Claw stout to him in the Hall of Petitioners, and he tipped {us} a copper and called {us} servant.",
        "{We} brought Lord Wishock a fine-looking stout with quite a kick in it. He waved {us} out of sight so he could enjoy his drink."},
    [397] = {act = "claimed Zardeth's gift from his servant Zggi", giver = "Zardeth",
        "Zardeth heard that Lord Wishock had enjoyed his drink, and said the warlocks of Stormwind could practice undisturbed thanks to {us}. {We} claimed his gift from the imp Zggi, who wanted to keep it but knew better.",
        "{We} took {our} reward from Zggi, Zardeth's servant, who would have liked to keep it. The warlocks under the city were safe from Wishock for now."},
    [1245] = {act = "brought the Defias papers to Elling Trias", giver = "Watcher Backus",
        "Watcher Backus thought the Defias papers too complex to be a ruse and too big for him, and begged {us} not to say he had seen them. {We} carried them to Trias, who found the name Fist among them.",
        "{We} brought Trias the papers from Addle's Stead, and he read them with growing interest. Jorgen and DeLavey had been smart to bring him in, he said."},
    [1246] = {act = "confronted Dashel Stonefist in Old Town", giver = "Elling Trias",
        "Fist was Dashel Stonefist, a brawler found in the middle of Old Town, and Trias did not expect him to talk willingly. {We} went into his alley and asked about his business, and he took it badly.",
        "{We} found Dashel Stonefist in Old Town and put Trias's questions to him. He was furious anyone would come into his alley asking."},
    [1247] = {act = "got the name Slim out of Dashel Stonefist", giver = "Dashel Stonefist",
        "Once persuaded, Dashel admitted to the meeting at Addle's Stead, though his part had ended when plan A failed. The man on the inside for plan B was called Slim, out of Menethil, and {we} took the name to Trias.",
        "{We} brought Trias the name Dashel had given up, Slim, from Menethil. Trias was glad to see {us} alive, and Menethil was a place to start."},
    [350] = {act = "went to Elling Trias for help against Lescovar", giver = "Mathias Shaw",
        "With VanCleef and Thredd dead there was no testimony against Lescovar, and a well-connected noble stood above the law. Shaw loathed to ask, but sent {us} to Trias, who wanted to hear everything from the beginning.",
        "{We} brought Trias word that Shaw wanted his help again, against the Defias. Next, he said, {we} would be telling him Deathwing still lived."},
    [2745] = {act = "found the gnome Tyrion watching Lescovar from the bushes", giver = "Elling Trias",
        "Trias would help, but the justice {we} needed against Lescovar and Marzon was not a legal one. {We} went to the castle and found his friend Tyrion hiding in the bushes, who nearly jumped out of his skin.",
        "{We} crept up on Tyrion in the castle gardens, where he had watched Lescovar for weeks. He hissed at {us} to keep quiet before the guards saw them both in the bushes."},
    [2746] = {act = "brought Tyrion silk and apples for Spybot's disguise", giver = "Tyrion",
        "Tyrion had a disguise in mind to get his Spybot past Lescovar's guards, and needed silk and apples from Clara's farm outside the city. {We} brought them, and he laid out the plan.",
        "{We} fetched silk and a couple of apples for Tyrion's plan. He had followed leads tying Lescovar to the Twilight's Hammer, he said, and now the man was more dangerous than the city could handle."},
    [434] = {act = "killed Lord Lescovar and Marzon in the castle garden", giver = "Tyrion",
        "Spybot went in disguised, and Lescovar dismissed his guards to wait for Marzon in the garden. When {we} heard them speak of the Defias {we} struck, and both were dead before the guards returned.",
        "{We} ended Lord Gregor Lescovar and his assassin in the royal gardens, quickly and quietly. Trias thanked {us} for {our} discretion and said he would keep an eye on {us}."},
    [394] = {act = "told Mathias Shaw that Lescovar was dead", giver = "Elling Trias",
        "Trias sent {us} to Shaw in Old Town to tell him the Lescovar threat was dealt with. Shaw called {our} justice swift and prayed he would never become {our} quarry, then thanked {us} for the people of Stormwind.",
        "{We} reported Lescovar's death to Mathias Shaw in the barracks of Old Town. As master of all assassins he meant no criticism of {our} swiftness, he said, only thanks."},
    [395] = {act = "met Baros Alexston after Lescovar's death", giver = "Mathias Shaw",
        "Shaw advised {us} to tell everything except whose hand slew Lescovar, and never to speak of Trias. {We} met Baros Alexston, who had heard Lescovar was found dead and was grateful to be saved from VanCleef's revenge.",
        "{We} went to Baros Alexston with the end of the Defias affair, keeping Shaw's advice. Baros thanked {us} for saving him and many others."},
    [396] = {act = "brought Baros's report before Highlord Bolvar Fordragon", giver = "Baros Alexston",
        "Baros wanted {me} to deliver his report on the Defias to the King, along with {our} own account. At Stormwind Keep Highlord Bolvar Fordragon received it, for the King was away, and commended {us} for the service.",
        "{We} stood in Stormwind Keep and told the whole affair, from Westfall's fields to Lescovar's garden. Bolvar gave {us} a token of the King's appreciation, sorry that His Majesty could not present it himself."},
    [543] = {act = "took the Perenolde Tiara from Grel'borg the Miser", giver = "Count Remington Ridgewell",
        "The Perenolde Tiara had belonged to the rulers of Alterac before their kingdom fell, and the ogre mage Grel'borg the Miser was said to have found it. {We} went into the Ruins of Alterac, took it from him, and brought it to Count Remington Ridgewell.",
        "{We} brought Count Ridgewell the emerald tiara of the Perenolde family from the ruins of Alterac. He was splendidly pleased, minded only that {we} not tread on his newly tailored cuffs."},
    [7781] = {act = "brought Nefarian's head to Highlord Bolvar Fordragon",
        "The old feeling of victory ran through {me} as {we} stood over the battle-scarred head of Nefarian, lord of Blackrock. {We} carried it to Highlord Bolvar Fordragon, who said this day would be remembered as a victory the Alliance had not known in years, if ever.",
        "By then all of Stormwind knew {my} name. {We} laid the head of Nefarian before Bolvar Fordragon, who called it inconceivable, and the city's greatest triumph in memory."},
    [7782] = {act = "went to the Valley of Heroes for the celebration", giver = "Highlord Bolvar Fordragon",
        "With Nefarian's head displayed, Bolvar sent {us} to Field Marshal Afrasiabi in the Valley of Heroes. The Field Marshal bowed to {us} and called for the celebration to begin.",
        "{We} walked between the statues of the Valley of Heroes to Field Marshal Afrasiabi. He bowed, offered {us} {our} choice of reward, and the city began to celebrate."},

    -- Ironforge.
    [291] = {act = "carried Senir Whitebeard's report to Senator Barin Redstone", giver = "Senir Whitebeard",
        "Senir Whitebeard gave {us} his report for Senator Barin Redstone and asked {us} not to mention how much {we} had helped. {We} followed the bannered road up the mountainside into Ironforge, a city carved out of the mountain, and found the senator in the king's chamber.",
        "Senator Barin Redstone read Senir's report and exploded at its use of the king's authority, swearing the Senate would not be pleased. Then he told {us} to go before he called the guards."},
    [6391] = {act = "flew Brock's list of students to Golnir Bouldertoe", giver = "Thorgrum Borrelson",
        "For a few coins a gryphon carried {us} from Thelsamar to Ironforge and set {us} down by the Great Forge. {We} brought Brock's list to Golnir Bouldertoe in the Deep Mountain Mining Guild, who had picks ready and names to chisel.",
        "{We} rode a gryphon into Ironforge with the names of Brock's best pupils. Golnir Bouldertoe took the list and began chiseling the names into their honorary picks."},
    [6388] = {act = "took the honorary picks to Gryth Thurden for the flight back", giver = "Golnir Bouldertoe",
        "Golnir handed {us} the finished picks for Brock's students. {We} took them to Gryth Thurden, the gryphon master of Ironforge, who would fly {us} to Thelsamar since {we} had already been there.",
        "{We} carried a bundle of honorary picks to Ironforge's gryphon roost. Gryth Thurden saw {we} had somewhere to go and offered {us} a gryphon home to Thelsamar."},
    [301] = {act = "took Ironband's report to Prospector Stormpike", giver = "Jern Hornhelm",
        "Ironband needed approval for more blastpowder, so {we} took his report to Prospector Stormpike in the Hall of Explorers, ready to duck as Jern advised. Stormpike cursed, for he had sent a load of powder weeks ago that Ironband never mentioned.",
        "{We} brought the hotheaded Prospector Stormpike news he did not want, the slow progress at Ironband's dig. Where had the last blastpowder gone, he demanded."},
    [1072] = {act = "went to Lomac Gearstrip in Tinker Town for Gaxim", giver = "Gaxim Rustfizzle",
        "Gaxim's most advanced device needed Nitromirglyceronium, and only his old friend Lomac Gearstrip could make it. {We} crossed the sea to Tinker Town, where Lomac squinted at {us} and asked how he could know it was not a lie.",
        "{We} found Lomac Gearstrip in Tinker Town and said Gaxim had sent {us}. Lomac was suspicious, as gnomes who make explosives tend to be."},
    [1073] = {act = "brewed the potions Lomac needed for his NG-5", giver = "Lomac Gearstrip", solo = true,
        "Lomac laughed that {I} wanted Nitromirglyceronium to stop goblins from destroying a forest, and said he would give it just to see something explode. First {I} had to prove {my} skill as an alchemist by bringing him the right potions.",
        "{I} brewed the potions Lomac Gearstrip asked for, and he said {I} seemed to know something about alchemy after all. The world was not all swords and sorcery, he said, and he made the NG-5."},
    [2923] = {act = "went to Tinkmaster Overspark about Techbot", giver = "Brother Sarno",
        "Brother Sarno remembered Techbot as a kind and helpful tool, and had heard from Tinkmaster Overspark that it had malfunctioned. {We} went to Tinker Town, where Overspark said it was true, Techbot had gone rogue, and begged for help.",
        "{We} found Tinkmaster Overspark grieving over his creation in Tinker Town. Techbot had gone rogue in Gnomeregan, and he asked {us} to help."},
    [2931] = {act = "joined Master Mechanic Castpipe's mission into Gnomeregan",
        "A gnome of the Enlightened Assembly reckoned there was an eighty-four percent chance that Master Mechanic Castpipe's mission really mattered. {We} went to Castpipe in Tinker Town, who was organizing bands to go back into Gnomeregan for lost data.",
        "{We} answered Castpipe's call for adventurers to enter Gnomeregan. If {we} had come for the data extraction, he said, then listen up."},
    [637] = {act = "brought Sully Balloo's last letter to his wife Sara",
        "Under the Thandol Span {we} found a dwarf pinned beneath the icy water and a waterlogged letter that fell apart in {our} hands, leaving a few sheets addressed to Mrs. Sara Balloo. {We} carried it to Ironforge, and she begged {us} to say it was not so.",
        "{We} brought Sara Balloo the last letter her husband Sully had written, found where he died beneath the bridge. She asked to read what he had written to her."},
    [683] = {act = "carried Sara Balloo's plea to King Magni", giver = "Sara Balloo",
        "Sara Balloo was too grief-stricken to go before the king herself, so she asked {us} to carry her note to Magni Bronzebeard. The king knew {my} name, for word of {my} deeds had traveled far, and he read her letter.",
        "{We} stood before King Magni Bronzebeard with a widow's plea. He had heard of {us}, and asked what business brought {us} before him."},
    [686] = {act = "carried King Magni's commission to Grand Mason Marblesten", giver = "King Magni Bronzebeard",
        "Magni could not bring Sully back, but the loss of every dwarf weighed on his soul, and he would pay tribute. {We} carried his commission for a memorial to Grand Mason Marblesten, trusted with the king's bidding.",
        "{We} brought Grand Mason Marblesten a royal commission for a memorial to Sully Balloo. The king himself had sent {us}, and the mason knew it must be important."},
    [2925] = {act = "went to Klockmort Spannerspan in Tinker Town", giver = "Mathiel",
        "Mathiel in Darnassus could not leave his post, but his heart ached to help his gnome friend Klockmort. {We} went in his stead, across the sea to Tinker Town, where Klockmort declared {us} just right for his mission.",
        "{We} found Klockmort Spannerspan in Tinker Town on Mathiel's behalf. He did need help, he said, with a mission into Gnomeregan."},
    [689] = {act = "gathered Alterac Granite for Sully Balloo's memorial", giver = "Grand Mason Marblesten",
        "Marblesten wanted the finest stone for the king's memorial, and sent {us} to Darrow Hill in Hillsbrad for Alterac Granite. {We} brought it back, and he called it better than he could have imagined.",
        "{We} quarried Alterac Granite in Hillsbrad for a memorial to a soldier {we} had found dead beneath a bridge. Marblesten was delighted with it."},
    [700] = {act = "told King Magni that Sully Balloo's memorial was done", giver = "Grand Mason Marblesten",
        "The memorial to Sully Balloo was finished in fine granite from Lordaeron, and {we} carried word to King Magni. The stone was a small token beside a dwarf's life, the king said, but it would remind the future who had died for them.",
        "{We} told Magni Bronzebeard that his tribute to Sully Balloo stood complete. He hoped it would remind those who came after that soldiers like Sully gave their lives for them."},
    [2948] = {act = "had Talvash del Kissel improve an old ring", giver = "Talvash del Kissel", solo = true,
        "Talvash del Kissel could make {my} simple ring better, for a fee and the materials he was out of. {I} brought him a bar of silver and a moss agate, and he added a silver and agate lattice for a fraction of his usual price.",
        "{I} gave Talvash the silver and moss agate he needed, down on his luck as he was. One day, he swore, he would make the finest trinkets in all of Azeroth, and he handed {me} the improved ring."},
    [4512] = {act = "gathered corrupted ooze samples in Felwood", giver = "Laris Geardawdle",
        "Laris Geardawdle had made a study of oozes and wanted to know why the Royal Apothecary Society collected them. {We} knew Felwood's corruption well by then, and filled his containers from its tainted oozes.",
        "{We} brought Laris samples from the corrupted oozes of Felwood, and he was amazed {we} looked no worse for wear. If he was right, he said, it would prove the dwarves had not erred in letting the gnomes into Ironforge."},
    [4513] = {act = "found a pure ooze sample for Laris", giver = "Laris Geardawdle",
        "The Felwood oozes had taken on the corruption around them, and Laris needed pure ones to compare. {We} searched until {we} found an untainted one, and he called {us} a treasure.",
        "{We} brought Laris Geardawdle the pure ooze he could not find himself. His thanks were boundless, and he hoped to need {our} help again."},

    -- Darnassus.
    [922] = {act = "took a timberling seed to Rellian Greenspyre in Darnassus", giver = "Denalan",
        "Denalan's friend Rellian Greenspyre had ideas of his own about the timberlings, so {we} carried a seed up to Darnassus and found him on the paths of the Cenarion Enclave. Rellian had bad news, for the seeds carried their parents' taint.",
        "{We} brought Rellian Greenspyre a timberling seed in the great city in the branches. The corruption was beyond his skill, he said, and Denalan might be the timberlings' only hope."},
    [923] = {act = "burned the mossy tumors of Wellspring Lake's timberlings", giver = "Rellian Greenspyre",
        "Until the source of the timberlings' malevolence was found, Rellian said, the worst of them had to be cut down. {We} went to Wellspring Lake in the north of the tree and gathered the mossy tumors from the tainted ones.",
        "{We} brought Rellian the poisoned tumors of the Wellspring Lake timberlings to be burned. They were the symptom of the disease, he said, and had to be cleansed from the new land."},
    [2519] = {act = "went to Priestess A'moora at the Temple of the Moon", giver = "Sister Aquinne",
        "A once great creature of the forest needed help, Sister Aquinne said, and the task would be difficult. {We} went to the Temple of the Moon, where Priestess A'moora would explain it.",
        "{We} found Priestess A'moora inside the Temple of the Moon, southeast of where Aquinne stood. She knew who had sent {us}."},
    [6344] = {act = "went down to Rut'theran to find Nessa Shadowsong", giver = "Mydrannul",
        "Mydrannul's friend Nessa Shadowsong needed a parcel taken to Darkshore. {We} took the portal west of the Temple Gardens down to Rut'theran Village, where Nessa asked if {we} would be her courier.",
        "{We} went down through the portal to Rut'theran Village to meet Nessa Shadowsong, a fishing merchant. She had a package bound for Darkshore and needed someone to carry it."},
    [935] = {act = "brought the gathered moonwell waters to Fandral Staghelm", giver = "Corithras Moonrage",
        "Corithras poured all {our} phials into one vessel for the Arch Druid, hoping he would find a solution quickly. {We} carried it to Fandral Staghelm in the druid grove, who grumbled that the water had taken its time.",
        "{We} brought Fandral Staghelm the waters of every moonwell on the tree. The weight of Teldrassil's problems was on his shoulders, he said, a yoke he wished to be rid of."},
    [940] = {act = "carried the Oracle Tree's bark message to the Arch Druid",
        "The forest whispered of {our} deeds, and as the harpies were driven from their nests the Oracle Tree felt calm return. It trusted {us} with a message for the Arch Druid, and Fandral wondered why the tree had been silent so long.",
        "{We} brought the Oracle Tree's message to Fandral Staghelm, who said {we} came with the spirit of the forest. Some problems were lessening and others growing, and he feared immortality would never be restored."},
    [98046] = {act = "took the Arch Druid's discarded phial to the Temple of the Moon", giver = "Arch Druid Fandral Staghelm",
        "Fandral's gaze narrowed when he saw {us} still there, and he told {us} to take the phial out of his sight. {We} carried it to the Temple of the Moon, where Priestess Lariia found drops still in it, perhaps the reason his incantation failed.",
        "{We} brought the Arch Druid's failed vessel to Priestess Lariia, who asked {us} not to mind him, for he bore much in Malfurion's absence. Some of the water remained."},
    [98065] = {act = "brought the blessed moonwell remnants to Tyrande Whisperwind", giver = "Priestess Lariia",
        "Lariia set the last of the moonwell water in a ceremonial vessel and sent {us} up to the High Priestess. Tyrande Whisperwind said Staghelm was not Malfurion and did not run Darnassus, then thanked {us} for saving every blessed drop.",
        "{We} stood before Tyrande Whisperwind herself with the water the Arch Druid had thrown away. She asked {us} to respect Fandral's station, and said the burden of leading their people was hers alone."},
    [2520] = {act = "offered Lady Sathrah's spinnerets at the temple fountain", giver = "Priestess A'moora",
        "A'moora asked {us} to finish what {we} had begun and offer Lady Sathrah's sacrifice to Elune. {We} laid the spinnerets in the temple's central fountain, where the holy waters would cleanse the madness from her.",
        "{We} placed the spider's silvery spinnerets in the fountain of the Temple of the Moon. Only in this way, A'moora said, could Sathrah be reborn with a renewed spirit."},
    [741] = {act = "brought Remtravel's fossil to Greywhisker in Darnassus", giver = "Archaeologist Hollee",
        "Hollee would not leave the prospector alone in Darkshore, so {we} carried Remtravel's mysterious fossil to Chief Archaeologist Greywhisker in Darnassus. Leave it to Remtravel, Greywhisker said, to find such a thing.",
        "{We} brought the fossil from the golem-haunted dig across the sea to the Explorers' League in Darnassus. Greywhisker was delighted with the find."},
    [3370] = {act = "carried Falla Sagewind's nightmare shard to Mathrengyl Bearwalker", giver = "Falla Sagewind",
        "Falla Sagewind's shard held the pure essence of the Emerald Dream, but what she saw in it was a nightmare. {We} carried it to Mathrengyl Bearwalker of the Cenarion Circle, who looked into it and faltered.",
        "{We} brought Mathrengyl the shard Falla had been so reluctant to speak of. Things in the Emerald Dream were not as the druids had thought, he said, and asked {us} not to speak of it."},
    [1081] = {act = "met Tyrande Whisperwind at the Temple of the Moon", giver = "Sentinel Tara Thenysil",
        "What {we} had helped start in Stonetalon might strengthen the night elves' hold there, and Tara Thenysil sent {us} to Darnassus. Tyrande Whisperwind had heard {my} name before, and was pleased with the path {I} had chosen.",
        "{We} came to the Temple of the Moon at the High Priestess's pleasure. Tyrande Whisperwind received {us} and gave a gift of thanks, pleased with one so young on such a path."},
    [1037] = {act = "asked Thyn'tel Bladeweaver about Velinde Starsong", giver = "Sentinel Melyria Frostshadow",
        "Velinde Starsong had held Ashenvale against Felwood before Melyria, until one day she simply disappeared. {We} went to Thyn'tel Bladeweaver, a commander of the Sentinels in Darnassus, who said it would take good reason to tell more.",
        "{We} brought Melyria's questions about her vanished predecessor to Thyn'tel Bladeweaver. That Velinde was gone was common knowledge, Thyn'tel said, but the rest was not to be shared lightly."},
    [1038] = {act = "searched Velinde Starsong's belongings in the Sentinels' bunkhouse", giver = "Thyn'tel Bladeweaver",
        "When Thyn'tel heard what the Tome of Mel'Thandris had shown {us}, she gave {us} the key to the chest that held Velinde's things. {We} read her notes, and her disappearance looked more troubling than anyone had thought.",
        "{We} opened Velinde's chest in the Sentinels' bunkhouse and read the notes of her duties. Thyn'tel still believed she had come to no bad end, and asked {us} to help find her."},
    [1044] = {act = "brought Thyn'tel the news of Velinde's fate",
        "{We} had followed Velinde's trail through Duskwood and its worgen-held mine, and what {we} found there went back to Thyn'tel in Darnassus. Thyn'tel said Tyrande would be saddened, for the two had been friends.",
        "Thyn'tel Bladeweaver heard from {us} what had become of Velinde and her Scythe of Elune. It unsettled the commander that a boon of the goddess had fallen out of her servants' hands, and she thanked {us} deeply."},

    -- Stonetalon Mountains (seasoned).
    [1056] = {act = "made the perilous journey to Keeper Albagorm on Stonetalon Peak", giver = "Faldreas Goeth'Shael",
        "The forest spirits spoke to Faldreas of {our} courage and wanderlust, so he sent {us} through the Talondeep Path into the Stonetalon Mountains. {We} climbed past Cragpool Lake and up the steep slope to Stonetalon Peak, where Keeper Albagorm said {we} had finally arrived.",
        "{We} followed the tunnel south of Mystral Lake out into Windshear Crag and climbed all the way to Stonetalon Peak. Keeper Albagorm had been waiting, and was glad Faldreas had listened to the spirits."},
    [1070] = {act = "went looking for Kaela Shadowspear in Stonetalon", giver = "Sentinel Tara Thenysil",
        "Tara Thenysil's friend Kaela Shadowspear had gone into Stonetalon to watch the Venture Company, with a gnome mage of all things, and had not been heard from. {We} found her at her camp, missing her homeland and proud of Tara.",
        "{We} crossed into the Stonetalon Mountains to find Kaela Shadowspear for Tara. Kaela was well, and pleased to meet {us}."},
    [1085] = {act = "met the gnome Gaxim Rustfizzle at Kaela's camp", giver = "Kaela Shadowspear",
        "Things in Stonetalon were grave enough that a night elf and a gnome were working together, Kaela said, and she asked {us} not to judge Gaxim too soon. {We} went to him, and he explained that the night elves needed magic and engineering both.",
        "{We} met Gaxim Rustfizzle, who meant to show the night elves that engineering and a dash of magic made the land safer. The possibilities, he said, were endless."},
    [1071] = {act = "drove back the Venture Company's workers at Windshear Crag", giver = "Gaxim Rustfizzle",
        "Gaxim needed time to plan, and the goblins of the Venture Company bred like rabbits. {We} went east into Windshear Crag and kept them at bay, and came back just as he hit on the plan, explosives, or part of it.",
        "{We} fought the Venture Company's goblins at Windshear Crag while Gaxim worked on his inventions. He had been herding them with explosions along the mountain edges, he said, but was low on supplies."},
    [1074] = {act = "carried Lomac's NG-5 back to Gaxim", giver = "Lomac Gearstrip",
        "Lomac handed over the NG-5 and warned that it was volatile stuff, and that anyone who was no friend of Gaxim's could have fun blowing up. {We} carried it carefully back to Stonetalon, and Gaxim explained it would ignite wagons of dynamite.",
        "{We} brought the volatile Nitromirglyceronium all the way to Gaxim without blowing up. It was the perfect distraction, he said, wagons of dynamite, just wait and see."},
    [1077] = {act = "brought Collin Mauren's spell scroll to Gaxim", giver = "Collin Mauren",
        "Collin Mauren had worked out the spell Gaxim needed and sent his regards with it. {We} carried it back to Stonetalon, where Gaxim said the spell and the NG-5 together would make the perfect remote explosive.",
        "{We} brought Gaxim the scroll from Stormwind's Mage Quarter, the last piece of his plan. Now he could make a distraction while {we} stole the Venture Company's letters and plans."},
    [1134] = {act = "took pridewing venom sacs near Mirkfallon Lake", giver = "Shindrell Swiftfire",
        "Word from Theramore said orc assassins used the venom of the pridewings near Mirkfallon Lake on secret raids against the Alliance. {We} went into Stonetalon and took the venom sacs first, and Shindrell said it saddened her to order it.",
        "{We} hunted the pridewings of Mirkfallon Lake so the Horde could not have their venom. Shindrell said {our} hearts might weep for them, but should swell knowing {our} allies were safer."},
    [1079] = {act = "stole the Venture Company's engineering plans from the lumber mill", giver = "Gaxim Rustfizzle",
        "Gaxim's devices were ready, and Plan Alpha's success depended on the plans inside the lumber mill south of Cragpool Lake. {We} planted the explosives where his notes showed, slipped in during the distraction, and came out with the engineering plans.",
        "{We} brought Gaxim the Venture Company's engineering plans from the lumber mill. A huge blow to them, he crowed, and their designs would improve his own."},
    [1080] = {act = "stole the Venture Company's letters from their mine", giver = "Gaxim Rustfizzle",
        "Plan Beta was like Plan Alpha, a distraction and a theft, and the key was the letters. {We} set the charges, went into the Venture Company's mine and came back alive with their correspondence.",
        "{We} took the Venture Company's letters from under their noses while Gaxim's explosives drew them away. With {our} skill and his creations, he said, they were unstoppable."},
    [1091] = {act = "brought the stolen Venture letters to Kaela", giver = "Gaxim Rustfizzle",
        "Gaxim wanted Kaela to hear how well it had gone, and that it could not have been done without a little magic. {We} carried the stolen letters to her, and she found them interesting indeed.",
        "{We} brought Kaela Shadowspear the Venture Company's letters and Gaxim's boasts. She thanked {us} for what {we} and the gnome had done."},
    [1083] = {act = "quelled the enraged spirits of the Charred Vale", giver = "Kaela Shadowspear",
        "The Venture Company had set the Charred Vale aflame and released something in their ignorance, elementals of flame, stone and rage. {We} went into the burned basin and fought them, and brought Kaela their smoldering embers.",
        "{We} fought the burning spirits that raged over the Charred Vale, a sight that had nearly made Kaela weep. Her thanks were brief, but {our} strength had served them well, she said."},
    [1057] = {act = "drove the Bloodfury harpies from the Charred Vale", giver = "Keeper Albagorm",
        "Greed had burned the Charred Vale, and now the Bloodfury harpies would not let the druids in to begin regrowth. {We} drove them out with great losses, and Keeper Albagorm hoped the true work of restoring the land could begin.",
        "{We} cleared the Bloodfury harpies from the scorched Charred Vale for Keeper Albagorm. Only then, he said, could the land be reclaimed for nature."},
    [1084] = {act = "gathered shrapnel from the wounded ancients", giver = "Kaela Shadowspear",
        "The treants who had driven the Venture Company back were now corrupted themselves, and Gaxim suspected the goblins' weapons. {We} gathered shrapnel from the wounded ancients of the Vale, and Kaela took it to him at once.",
        "{We} took shrapnel from the maddened treants of the Charred Vale, once great guardians. It would be enough for Gaxim to learn how they had been corrupted."},

    -- Gnomeregan and the roads beyond (seasoned).
    [2922] = {act = "brought Techbot's memory core out of Gnomeregan", giver = "Tinkmaster Overspark",
        "When Gnomeregan fell, a rogue spark had turned Tinkmaster Overspark's helpful Techbot into a frenzied thing that roamed the ruined city. {We} went down into Gnomeregan, faced Techbot, and brought its memory core back to Tinker Town.",
        "{We} carried poor Techbot's memory core up out of Gnomeregan for Overspark. He promised the machine it would be fixed, then went hunting for the plug of his hydro-jack swivel spanner."},
    [2926] = {act = "brought Ozzie a phial of green glow from the troggs", giver = "Ozzie Togglevolt",
        "Ozzie Togglevolt and Razzle were close to a cure for Gnomeregan's sickness, or else a very powerful rum. {We} filled his phial with fallout from the irradiated troggs, and he meant to test it on a captured leper gnome, and his own bald head.",
        "{We} brought Ozzie a phial of green glow from the troggs of Gnomeregan. If the formula worked, the leper gnome would be cured and Ozzie would have a full head of hair, so he told {us} to stand back."},
    [2962] = {act = "brought Ozzie pure green glow from Gnomeregan's depths", giver = "Ozzie Togglevolt",
        "{Our} first sample had been too small and impure, Ozzie said, and he needed fallout straight from the tap. {We} went deep into Gnomeregan among the irradiated slimes, lurkers and horrors and came back with it, every limb still attached.",
        "{We} filled Ozzie's phial at the source, from the radiant horrors deep in the city. He looked {us} over, impressed that nobody was glowing, and turned to his test."},
    [2924] = {act = "gathered essential artificials in Gnomeregan for Klockmort", giver = "Klockmort Spannerspan",
        "In the frantic flight from Gnomeregan nobody had taken any essential artificials, and Klockmort needed a large supply. {We} found the artificial extrapolators in the city's deeper halls and filled {our} packs.",
        "{We} brought Klockmort Spannerspan the essential artificials from Gnomeregan's depths. {Our} bravery, he said, had advanced gnomish research by a leap and a bound."},
    [2928] = {act = "tore apart Gnomeregan's robots for Shoni's excavationators", giver = "Shoni the Shilent",
        "Shoni's fleet of gyrodrillmatic excavationators needed spare parts, and Gnomeregan's robots roamed like cattle on an open range. {We} tore two dozen of them apart for their guts.",
        "{We} brought Shoni the Shilent a sack of robot guts from Gnomeregan. That fixed one excavationator, she said, with three hundred and ninety-eight to go."},
    [2930] = {act = "recovered the prismatic punch card from the 3005-D terminal", giver = "Master Mechanic Castpipe",
        "The gnomes had left vital data in Gnomeregan on a prismatic punch card, behind terminals A, B and C. {We} worked {our} way down through the city card by card, from white to prismatic, and recovered the data.",
        "{We} brought Castpipe the prismatic punch card from the 3005-D terminal deep in Gnomeregan. The data was vitally, critically, immeasurably important, he said, and the gnomes would long remember."},
    [2904] = {act = "led Kernobee out of Gnomeregan", giver = "Kernobee",
        "{We} found Kernobee among the troggs of Gnomeregan, beaten nearly to death by Dark Iron dwarves. {We} led him to the exit alive and carried his message to Scooty in Booty Bay, who rewarded {us} against Mekgineer Thermaplugg.",
        "Out of Gnomeregan {we} brought Kernobee alive, then went all the way to Booty Bay to tell Scooty he had gone to warn Tinkerwiz in Ratchet. Scooty called Thermaplugg a good-for-nothing backstabber."},
    [2951] = {act = "fed a grimy find and three silver to the Sparklematic 5200",
        "Among the gnomes holding out in Gnomeregan stood the Sparklematic 5200, promising to put the shine back in shine-tastic. {We} gave it something grimy and three silver coins, and it churned and lurched as it worked.",
        "{We} tried the Sparklematic 5200, a cleaning machine in the middle of a ruined city. It groaned and creaked from side to side while it purged the grime."},
    [1132] = {act = "sailed to Theramore to meet Fiora Longears", giver = "Red Jack Flint",
        "Red Jack Flint in Menethil saw the sea in {my} future and sent {us} across to Theramore, to his partner Fiora Longears. Fiora said Mr. Flint was a strong judge of character, so {we} surely belonged in Kalimdor.",
        "{We} took ship from Menethil to Theramore on Red Jack Flint's word. Fiora Longears welcomed {us} to the land of opportunity."},
    [971] = {act = "brought the Lorgalis Manuscript out of Blackfathom Deeps", giver = "Gerrig Bonegrip",
        "Gerrig Bonegrip collected old lore, the kind that opened doorways and could wake Those Who Sleep. {We} went down to the bottom of Blackfathom Deeps among the ruins of long-dead elves and brought him the Lorgalis Manuscript.",
        "{We} carried the Lorgalis Manuscript all the way from Blackfathom Deeps to Gerrig in Ironforge. He rejoiced that its knowledge would reach his brothers and sisters, and said {we} had served them more than {we} knew."},
    [1017] = {act = "killed Sarilus Foulborne on Dreadmist Peak", giver = "Sentinel Velene Starstrike",
        "Only one undead mage in the Barrens was foolish enough to defile so many water elementals, Sarilus Foulborne on Dreadmist Peak. {We} went deep into Horde lands, killed him, and brought Velene his head.",
        "{We} wiped the smile off Sarilus Foulborne's face for good, in the middle of enemy country. Sentinel Velene gave {us} the Light of Elune, to drink when death seemed near."},
    [1039] = {act = "asked the dockmaster of Ratchet about Velinde", giver = "Thyn'tel Bladeweaver",
        "Velinde had most likely sailed from Ratchet, the Barrens' only port, and Thyn'tel sent {us} south through Horde lands to ask. The goblin who kept the docks did not see many of {our} kind, and dug through his ledgers.",
        "{We} crossed the Barrens to Ratchet, watching for Horde patrols, to ask after a night elf priestess. The dockmaster was sure he had her written down somewhere."},
    [1040] = {act = "followed Velinde's passage to Booty Bay and Ruzzgot", giver = "Wharfmaster Dizzywig",
        "The ledger said Velinde had sailed to Booty Bay on the Black Osprey, and had asked about overland travel there. {We} followed across the sea to Caravaneer Ruzzgot, who asked whether {we} wanted a job or had the wrong goblin.",
        "{We} took the trail of the vanished priestess over the sea to Booty Bay and the goblin caravan driver Ruzzgot. He had no jobs, and little patience."},
    [1059] = {act = "carried Albagorm's call to the druid Falfindel Waywarder", giver = "Keeper Albagorm",
        "The Bloodfuries would regroup if nothing was done, and Keeper Albagorm needed the great forest spirits that only Falfindel Waywarder could call. {We} traveled far south to the edge of Feralas in Thousand Needles, and Falfindel said Albagorm was wise to send {us}.",
        "{We} carried Keeper Albagorm's urgent word to the druid Falfindel Waywarder at the forest's edge. He would call the great spirits to the Charred Vale before it was too late."},
    [1135] = {act = "hunted the Highperch wyverns for their venom", giver = "Fiora Longears",
        "Wyvern venom was worth more than the beast in some circles, and Fiora Longears sent {us} to Highperch in Thousand Needles. {We} brought back sacs nearly bursting, and she said it must have been quite a slaughter.",
        "{We} hunted the wyverns of Highperch for their potent venom and carried it back to Fiora. Most of the sacs were full, the kind usually taken only from young wyverns."},
    [1142] = {act = "carried Heralath's pendant and last words to Treshala", giver = "Heralath Fallowbrook",
        "In Razorfen Kraul {we} found Heralath Fallowbrook dying, and he begged {us} to take his wife Treshala the pendant of bonding stolen from him, and word of his lonely death. {We} found the pendant and carried it to Darnassus, and she cried out against a cruel world.",
        "{We} brought Treshala Fallowbrook her husband's pendant and the news that he had died in Razorfen Kraul. She would not let his work die with him, she said, and asked to mourn alone."},
    [2866] = {act = "searched the Ruins of Solarsal for what drew the naga", giver = "General Shandris Feathermoon",
        "By then {my} name carried weight far from home, and General Shandris Feathermoon sent {us} south to the Ruins of Solarsal, where the Hatecrest naga had gathered in alarming numbers. Among the old stones {we} found a gazebo newer than the rest, carved with glyphs and warm to the touch.",
        "{We} searched the ruins of Solarsal among the Hatecrest naga for anything out of place. A strange gazebo stood at their heart, its stone warm and its glyphs unknown."},
    [2867] = {act = "reported the strange gazebo to General Feathermoon",
        "{We} came back to Feathermoon Stronghold with word of the warm, glyph-carved gazebo in the Ruins of Solarsal. Shandris Feathermoon found it disturbing, attack or not, and offered {us} more work against the Hatecrest.",
        "General Shandris Feathermoon heard {our} report on the gazebo and paid {us} for the investigation. The naga's presence boded ill for the push into Feralas, she said."},
    [2869] = {act = "brought Latronicus Moonspear ten Hatecrest scales", giver = "Latronicus Moonspear",
        "The naga would move to take the island sooner or later, Latronicus Moonspear judged, and he meant to strike first. {We} cut {our} teeth on the Hatecrest and brought him ten scales in good condition.",
        "{We} weakened the Hatecrest naga's hold for Feathermoon Stronghold and brought Latronicus their scales. The night elves were no warmongers, he said, but they would protect their own."},

-- POV-END
}
for id, pov in pairs(POV) do
    if P.questIDs[id] then P.questIDs[id].pov = pov end
end
A.Lore.RegisterStoryPack("alliance-starters", P)

